    ('E2E QA 加購服務 '||v_tag,902),
    ('E2E QA 長時數服務 '||v_tag,903);
  v_booking_type_count := 3;

  select id into v_type1 from public.booking_service_types where name='E2E QA 基礎服務 '||v_tag order by created_at desc limit 1;
  select id into v_type2 from public.booking_service_types where name='E2E QA 加購服務 '||v_tag order by created_at desc limit 1;
  select id into v_type3 from public.booking_service_types where name='E2E QA 長時數服務 '||v_tag order by created_at desc limit 1;

  insert into public.booking_service_type_rewards(service_type_id,point_card_id,minutes_per_point,created_by,updated_by)
  values
    (v_type1,v_card1,30,v_created_by,v_created_by),
    (v_type3,v_card2,75,v_created_by,v_created_by);

  insert into public.booking_services(
    title,description,is_active,
    created_by,duration_minutes,price_amount,service_type,counts_toward_membership,requires_companion_service
  ) values
  ('E2E QA 標準主服務 '||v_tag,'30 分鐘計入會員階級。',true,v_created_by,30,880,'E2E QA 基礎服務 '||v_tag,true,false),
  ('E2E QA 加購短服務 '||v_tag,'必須搭配其他項目，不計會員階級。',true,v_created_by,15,260,'E2E QA 加購服務 '||v_tag,false,true),
  ('E2E QA 長時數主服務 '||v_tag,'跨多時段、計入會員階級。',true,v_created_by,120,2480,'E2E QA 長時數服務 '||v_tag,true,false),
  ('E2E QA 停用服務 '||v_tag,'管理端保留但用戶端不可預約。',false,v_created_by,45,999,'E2E QA 基礎服務 '||v_tag,true,false);
  get diagnostics v_booking_service_count = row_count;

  insert into public.booking_technicians(name,is_active,sort_order,created_by)
  values
    ('E2E QA 技師甲 '||v_tag,true,901,v_created_by),
    ('E2E QA 技師乙 '||v_tag,true,902,v_created_by),
    ('E2E QA 停用技師 '||v_tag,false,903,v_created_by);
  get diagnostics v_technician_count = row_count;

  select id into v_primary_technician_id
    from public.booking_technicians
   where name = 'E2E QA 技師甲 '||v_tag
     and is_active = true
   order by created_at desc
   limit 1;

  -- A paired E2E fixture must be self-contained. Always bind the current
  -- fixture's active technician as primary instead of silently reusing a
  -- technician created by an earlier retained QA run.
  select primary_technician_id
    into v_existing_primary_technician_id
    from public.booking_settings
   where id = 1;

  if not found then
    insert into public.booking_settings(id,max_party_size,primary_technician_id,updated_by)
    values (1,2,v_primary_technician_id,v_created_by);
  else
    update public.booking_settings
       set primary_technician_id = v_primary_technician_id,
           max_party_size = greatest(max_party_size,2),
           updated_by = v_created_by,
           updated_at = clock_timestamp()
     where id = 1;
  end if;

  select max_party_size into v_booking_max_party_size
    from public.booking_settings
   where id = 1;

  return jsonb_build_object(
    'runTag', v_tag,
    'createdBy', v_created_by,
    'today', v_today,
    'ticketTemplates', v_ticket_count,
    'pointCards', v_card_count,
    'pointRewardNodes', v_reward_count,
    'eventTickets', v_event_count,
    'calendarItems', v_calendar_count,
    'fixedTickets', v_fixed_count,
    'bookingServiceTypes', v_booking_type_count,
    'bookingServices', v_booking_service_count,
    'bookingTechnicians', v_technician_count,
    'primaryTechnicianId', coalesce((select primary_technician_id::text from public.booking_settings where id=1),''),
    'maxPartySize', v_booking_max_party_size,
    'coverage', jsonb_build_object(
      'ticketTypes', jsonb_build_array('coupon','lottery','fixed'),
      'fixedSchedules', jsonb_build_array('birthday_month','yearly','monthly','weekly'),
      'fixedExpiryModes', jsonb_build_array('month_end','week_end','days_after_issue','fixed_date'),
      'eventDateStates', jsonb_build_array('past','today','active-window','future'),
      'membershipTiers', jsonb_build_array('general','silver','gold','platinum'),
      'pointThresholds', jsonb_build_array(2,3,5,8,13,21),
      'bookingModes', jsonb_build_array('primary','companion','membership-counting','non-membership','inactive')
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.admin_prepare_complex_e2e_fixtures_v2(p_run_tag text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result jsonb;
  v_tag text;
  v_created_by text;
  v_marked integer := 0;
begin
  perform pg_advisory_xact_lock(2026092202);

  v_result := public.admin_prepare_complex_e2e_fixtures(p_run_tag, p_actor);
  v_tag := coalesce(v_result ->> 'runTag', '');
  v_created_by := coalesce(v_result ->> 'createdBy', '');

  if v_tag = '' or v_created_by not like 'qa:e2e:%' then
    raise exception 'E2E_SERVICE_TYPE_PROVENANCE_INVALID';
  end if;

  update public.booking_service_types
     set created_by = v_created_by
   where created_by is null
     and (
       (name = 'E2E QA 基礎服務 ' || v_tag and sort_order = 901)
       or (name = 'E2E QA 加購服務 ' || v_tag and sort_order = 902)
       or (name = 'E2E QA 長時數服務 ' || v_tag and sort_order = 903)
     );
  get diagnostics v_marked = row_count;

  if v_marked <> 3 then
    raise exception 'E2E_SERVICE_TYPE_PROVENANCE_INCOMPLETE';
  end if;

  return v_result || jsonb_build_object('bookingServiceTypesMarked', v_marked);
end
$function$

CREATE OR REPLACE FUNCTION public.admin_purge_all_test_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_test_member_ids uuid[] := array[]::uuid[];
  v_base jsonb := '{}'::jsonb;
  v_extended jsonb := '{}'::jsonb;
  v_receipts integer := 0;
  v_consents integer := 0;
  v_service_types integer := 0;
  v_second_pass_technicians integer := 0;
  v_evolution integer := 0;
  v_extended_total integer := 0;
  v_extended_technicians integer := 0;
  v_system_primary_technician_id uuid;
begin
  perform pg_advisory_xact_lock(2026092001);
  perform pg_advisory_xact_lock(2026092202);

  delete from public.test_execution_leases
   where expires_at <= clock_timestamp();

  if exists (
    select 1
      from public.test_execution_leases
     where expires_at > clock_timestamp()
  ) then
    raise exception 'TEST_EXECUTION_ACTIVE';
  end if;

  if exists (
    select 1
      from public.automation_test_runs
     where environment = 'MemberWebsocket-dev'
       and status in ('queued','running')
  ) then
    raise exception 'TEST_RUN_ACTIVE';
  end if;

  select coalesce(array_agg(id order by id), array[]::uuid[])
    into v_test_member_ids
    from public.members
   where is_test_account = true;

  delete from public.booking_receipts
   where member_id = any(v_test_member_ids);
  get diagnostics v_receipts = row_count;

  delete from public.membership_consents
   where member_id = any(v_test_member_ids);
  get diagnostics v_consents = row_count;

  v_base := public.admin_purge_test_data();

  -- Replace a QA-owned primary directly with a non-QA baseline. Setting it to
  -- NULL is intentionally blocked by booking_settings_protect_primary_technician.
  if exists (
    select 1
      from public.booking_settings bs
      join public.booking_technicians t on t.id = bs.primary_technician_id
     where bs.id = 1
       and t.created_by like 'qa:e2e:%'
  ) then
    select t.id
      into v_system_primary_technician_id
      from public.booking_technicians t
     where lower(btrim(t.name)) = lower(btrim('系統主要技師'))
       and coalesce(t.created_by, '') not like 'qa:%'
     order by t.created_at
     limit 1;

    if v_system_primary_technician_id is null then
      insert into public.booking_technicians(name, is_active, sort_order, created_by)
      values ('系統主要技師', true, 0, 'system')
      returning id into v_system_primary_technician_id;
    else
      update public.booking_technicians
         set is_active = true,
             sort_order = 0,
             updated_at = clock_timestamp()
       where id = v_system_primary_technician_id;
    end if;

    update public.booking_settings
       set primary_technician_id = v_system_primary_technician_id,
           updated_by = 'qa:e2e:purge',
           updated_at = clock_timestamp()
     where id = 1;
  end if;

  v_extended := public.admin_purge_extended_qa_artifacts();

  delete from public.booking_service_types t
   where t.created_by like 'qa:e2e:%'
     and not exists (
       select 1
         from public.booking_service_type_rewards r
        where r.service_type_id = t.id
     )
     and not exists (
       select 1
         from public.booking_services s
        where lower(btrim(s.service_type)) = lower(btrim(t.name))
     );
  get diagnostics v_service_types = row_count;

  delete from public.booking_technicians t
   where t.created_by like 'qa:e2e:%'
     and not exists (select 1 from public.bookings b where b.technician_id = t.id)
     and not exists (select 1 from public.booking_participants p where p.technician_id = t.id)
     and not exists (select 1 from public.booking_participant_reservations r where r.technician_id = t.id)
     and not exists (select 1 from public.booking_settings bs where bs.primary_technician_id = t.id);
  get diagnostics v_second_pass_technicians = row_count;

  delete from public.e2e_evolution_state
   where id = true;
  get diagnostics v_evolution = row_count;

  v_extended_total := coalesce((v_extended ->> 'deletedExtendedQaArtifacts')::integer, 0)
    + v_service_types + v_second_pass_technicians;
  v_extended_technicians := coalesce((v_extended ->> 'deletedBookingTechnicians')::integer, 0)
    + v_second_pass_technicians;

  v_extended := v_extended || jsonb_build_object(
    'deletedBookingServiceTypes', v_service_types,
    'deletedBookingTechnicians', v_extended_technicians,
    'deletedExtendedQaArtifacts', v_extended_total,
    'restoredPrimaryTechnicianId', v_system_primary_technician_id
  );

  return v_base
    || v_extended
    || jsonb_build_object(
      'deletedBookingReceipts', v_receipts,
      'deletedMembershipConsents', v_consents,
      'deletedEvolutionStateRows', v_evolution
    );
end
$function$

