  v_qa_artifact_count := v_qa_artifact_count + v_rows;

  return jsonb_build_object(
    'testAccountCount', v_test_account_count,
    'deletedAutomationRuns', v_automation_run_count,
    'deletedBookings', v_booking_count,
    'deletedEventClaims', v_event_claim_count,
    'deletedPointEntries', v_point_entry_count,
    'deletedPointTickets', v_point_ticket_count,
    'deletedPointBalances', v_point_balance_count,
    'deletedPointTransfers', v_point_transfer_count,
    'deletedMemberReferrals', v_member_referral_count,
    'deletedServiceTimeEntries', v_service_time_count,
    'deletedFixedTicketGrants', v_fixed_grant_count,
    'deletedBirthdayBenefitGrants', 0,
    'deletedSessions', v_session_count,
    'deletedPresenceSessions', v_presence_count,
    'deletedAuditRows', v_audit_count,
    'deletedIdempotencyRows', v_idempotency_count,
    'deletedRateLimitRows', v_rate_limit_count,
    'deletedScheduledMessages', v_scheduled_message_count,
    'deletedQaArtifacts', v_qa_artifact_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_recycle_e2e_runtime(p_lease_id uuid, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_test_member_ids uuid[] := array[]::uuid[];
  v_line_user_ids text[] := array[]::text[];
  v_member_codes text[] := array[]::text[];
  v_member_id_texts text[] := array[]::text[];
  v_booking_ids uuid[] := array[]::uuid[];
  v_booking_id_texts text[] := array[]::text[];
  v_test_account_count integer := 0;
  v_automation_run_count integer := 0;
  v_booking_count integer := 0;
  v_event_claim_count integer := 0;
  v_point_entry_count integer := 0;
  v_point_ticket_count integer := 0;
  v_point_balance_count integer := 0;
  v_point_transfer_count integer := 0;
  v_member_referral_count integer := 0;
  v_service_time_count integer := 0;
  v_fixed_grant_count integer := 0;
  v_session_count integer := 0;
  v_presence_count integer := 0;
  v_audit_count integer := 0;
  v_idempotency_count integer := 0;
  v_rate_limit_count integer := 0;
  v_scheduled_message_count integer := 0;
  v_qa_artifact_count integer := 0;
  v_rows integer := 0;
  v_old_receipts integer := 0;
  v_old_consents integer := 0;
  v_pass integer := 0;
  v_pass_result jsonb := '{}'::jsonb;
  v_extended_deleted integer := 0;
  v_service_types_deleted integer := 0;
  v_remaining integer := 0;
  v_recycled_at timestamptz;
  v_system_primary_technician_id uuid;
begin
  perform pg_advisory_xact_lock(2026092001);
  perform pg_advisory_xact_lock(2026092202);

  -- Only the currently authenticated admin's active E2E lease may reset data.
  select runtime_recycled_at into v_recycled_at
    from public.test_execution_leases
   where id = p_lease_id
     and lease_type = 'full_e2e'
     and actor_line_user_id = p_actor
     and expires_at > clock_timestamp()
   for update;
  if not found then
    raise exception 'E2E_RECYCLE_LEASE_INVALID';
  end if;
  if v_recycled_at is not null then

  return jsonb_build_object('alreadyRecycled', true, 'cleanupComplete', true);
  end if;
  if exists (
    select 1 from public.test_execution_leases
     where id <> p_lease_id and lease_type = 'full_e2e'
       and expires_at > clock_timestamp()
  ) then
    raise exception 'E2E_RECYCLE_OTHER_RUN_ACTIVE';
  end if;
  if exists (
    select 1 from public.automation_test_runs
     where environment = 'MemberWebsocket-dev' and status in ('queued','running')
  ) then
    raise exception 'E2E_RECYCLE_BACKEND_RUN_ACTIVE';
  end if;

  select
    count(*)::integer,
    coalesce(array_agg(id order by id), array[]::uuid[]),
    coalesce(array_agg(id::text order by id), array[]::text[]),
    coalesce(array_agg(line_user_id order by id) filter (where line_user_id is not null), array[]::text[]),
    coalesce(array_agg(member_code order by id) filter (where member_code is not null), array[]::text[])
  into
    v_test_account_count,
    v_test_member_ids,
    v_member_id_texts,
    v_line_user_ids,
    v_member_codes
  from public.members
  where is_test_account = true;

  delete from public.booking_receipts
   where member_id = any(v_test_member_ids);
  get diagnostics v_old_receipts = row_count;

  delete from public.membership_consents
   where member_id = any(v_test_member_ids);
  get diagnostics v_old_consents = row_count;

  perform id
    from public.members
   where id = any(v_test_member_ids)
   for update;

  select
    coalesce(array_agg(id order by id), array[]::uuid[]),
    coalesce(array_agg(id::text order by id), array[]::text[])
  into v_booking_ids, v_booking_id_texts
  from public.bookings
  where member_id = any(v_test_member_ids);

  if exists (
    select 1
      from public.point_transfers t
      join public.members sender on sender.id = t.sender_member_id
      join public.members receiver on receiver.id = t.receiver_member_id
     where (t.sender_member_id = any(v_test_member_ids) or t.receiver_member_id = any(v_test_member_ids))
       and (sender.is_test_account is not true or receiver.is_test_account is not true)
  ) then
    raise exception 'TEST_DATA_CROSS_BOUNDARY_POINT_TRANSFER';
  end if;

  if exists (
    select 1
      from public.member_referrals r
      join public.members inviter on inviter.id = r.inviter_member_id
      join public.members invitee on invitee.id = r.invitee_member_id
     where (r.inviter_member_id = any(v_test_member_ids) or r.invitee_member_id = any(v_test_member_ids))
       and (inviter.is_test_account is not true or invitee.is_test_account is not true)
  ) then
    raise exception 'TEST_DATA_CROSS_BOUNDARY_REFERRAL';
  end if;

  -- Keep automation_test_runs/cases/steps and adaptive-learning history.
  -- Only test-member operational data and QA fixture assets are recycled.

  delete from public.api_rate_limits
   where principal_hash = any (
     select encode(extensions.digest(line_user_id, 'sha256'), 'hex')
       from unnest(v_line_user_ids) as ids(line_user_id)
   );
  get diagnostics v_rate_limit_count = row_count;

  delete from public.idempotency_results
   where actor_line_user_id = any(v_line_user_ids)
      or exists (
        select 1
          from unnest(v_member_id_texts || v_member_codes || v_booking_id_texts || v_line_user_ids) as ids(value)
         where result::text like '%' || value || '%'
      );
  get diagnostics v_idempotency_count = row_count;

  delete from public.booking_audit_events
   where actor_line_user_id = any(v_line_user_ids)
      or target_id = any(v_member_id_texts)
      or target_id = any(v_member_codes)
      or target_id = any(v_booking_id_texts)
      or exists (
        select 1
          from unnest(v_member_id_texts || v_member_codes || v_booking_id_texts || v_line_user_ids) as ids(value)
         where metadata::text like '%' || value || '%'
      );
  get diagnostics v_rows = row_count;
  v_audit_count := v_audit_count + v_rows;

  delete from public.audit_logs
   where actor_line_user_id = any(v_line_user_ids)
      or target_id = any(v_member_id_texts)
      or target_id = any(v_member_codes)
      or target_id = any(v_booking_id_texts)
      or exists (
        select 1
          from unnest(v_member_id_texts || v_member_codes || v_booking_id_texts || v_line_user_ids) as ids(value)
         where detail::text like '%' || value || '%'
      );
  get diagnostics v_rows = row_count;
  v_audit_count := v_audit_count + v_rows;

  delete from booking_notifications.outbox
   where booking_id = any(v_booking_ids);

  delete from public.booking_completion_settlements
   where member_id = any(v_test_member_ids)
      or booking_id = any(v_booking_ids);

  delete from public.member_referrals
   where inviter_member_id = any(v_test_member_ids)
      or invitee_member_id = any(v_test_member_ids);
  get diagnostics v_member_referral_count = row_count;

  delete from public.point_transfers
   where sender_member_id = any(v_test_member_ids)
      or receiver_member_id = any(v_test_member_ids);
  get diagnostics v_point_transfer_count = row_count;

  delete from public.event_ticket_claims
   where member_id = any(v_test_member_ids);
  get diagnostics v_event_claim_count = row_count;

  delete from public.scheduled_grant_messages
   where member_id = any(v_test_member_ids)
      or line_user_id = any(v_line_user_ids);
  get diagnostics v_scheduled_message_count = row_count;

  delete from public.point_tickets
   where member_id = any(v_test_member_ids);
  get diagnostics v_point_ticket_count = row_count;

  delete from public.point_entries
   where member_id = any(v_test_member_ids);
  get diagnostics v_point_entry_count = row_count;

  delete from public.point_balances
   where member_id = any(v_test_member_ids);
  get diagnostics v_point_balance_count = row_count;

  delete from public.service_time_entries
   where member_id = any(v_test_member_ids);
  get diagnostics v_service_time_count = row_count;

  delete from public.fixed_ticket_grants
   where member_id = any(v_test_member_ids);
  get diagnostics v_fixed_grant_count = row_count;

  delete from public.bookings
   where member_id = any(v_test_member_ids);
  get diagnostics v_booking_count = row_count;

  delete from public.test_login_sessions
   where member_id = any(v_test_member_ids);
  get diagnostics v_session_count = row_count;

  delete from public.member_presence_sessions
   where member_id = any(v_test_member_ids);
  get diagnostics v_presence_count = row_count;

  delete from public.calendar_items c
   where public.is_qa_test_provenance(c.created_by)
     and not exists (
       select 1
         from public.event_ticket_claims claim
        where claim.event_ticket_id = c.source_event_ticket_id
          and not (claim.member_id = any(v_test_member_ids))
     );
  get diagnostics v_rows = row_count;
  v_qa_artifact_count := v_qa_artifact_count + v_rows;

  delete from public.event_tickets e
   where public.is_qa_test_provenance(e.created_by)
     and not exists (select 1 from public.event_ticket_claims c where c.event_ticket_id = e.id)
     and not exists (select 1 from public.fixed_ticket_grants g where g.event_ticket_id = e.id)
     and not exists (select 1 from public.member_referrals r where r.reward_event_ticket_id = e.id);
  get diagnostics v_rows = row_count;
  v_qa_artifact_count := v_qa_artifact_count + v_rows;

  delete from public.point_cards pc
   where public.is_qa_test_provenance(pc.created_by)
     and not exists (select 1 from public.point_entries e where e.point_card_id = pc.id)
     and not exists (select 1 from public.point_tickets t where t.point_card_id = pc.id)
     and not exists (select 1 from public.point_balances b where b.point_card_id = pc.id)
     and not exists (select 1 from public.point_transfers t where t.point_card_id = pc.id);
  get diagnostics v_rows = row_count;
  v_qa_artifact_count := v_qa_artifact_count + v_rows;

  delete from public.ticket_templates tt
   where public.is_qa_test_provenance(tt.created_by)
     and not exists (select 1 from public.point_card_rewards r where r.ticket_template_id = tt.id)
     and not exists (select 1 from public.point_tickets t where t.ticket_template_id = tt.id);
  get diagnostics v_rows = row_count;
  v_qa_artifact_count := v_qa_artifact_count + v_rows;

  -- Release booking_settings -> QA technician before deleting QA fixtures.
  -- Restoring a permanent baseline is required by the protected primary-setting
  -- constraint: setting it to NULL or deleting its current technician is unsafe.
  if exists (
    select 1 from public.booking_settings bs
    join public.booking_technicians t on t.id = bs.primary_technician_id
    where bs.id = 1 and public.is_qa_test_provenance(t.created_by)
  ) then
    select t.id into v_system_primary_technician_id
      from public.booking_technicians t
     where lower(btrim(t.name)) = lower(btrim('系統主要技師'))
       and not public.is_qa_test_provenance(t.created_by)
     order by t.created_at
     limit 1;

    if v_system_primary_technician_id is null then
      insert into public.booking_technicians(name, is_active, sort_order, created_by)
      values ('系統主要技師', true, 0, 'system')
      returning id into v_system_primary_technician_id;
    else
      update public.booking_technicians
         set is_active = true,
             sort_order = 0,
             updated_at = clock_timestamp()
       where id = v_system_primary_technician_id;
    end if;

    update public.booking_settings
       set primary_technician_id = v_system_primary_technician_id,
           updated_by = 'qa:e2e:recycle',
           updated_at = clock_timestamp()
     where id = 1;
  end if;

  -- The extended pass removes QA-owned parent fixtures after test-member
  -- ticket/point/booking references have been cleared above.
  for v_pass in 1..4 loop
    v_pass_result := public.admin_purge_extended_qa_artifacts();
    v_rows := coalesce((v_pass_result ->> 'deletedExtendedQaArtifacts')::integer, 0);
    v_extended_deleted := v_extended_deleted + v_rows;
    exit when v_rows = 0;
  end loop;

  delete from public.booking_service_types t
   where public.is_qa_test_provenance(t.created_by)
     and not exists (select 1 from public.booking_service_type_rewards r where r.service_type_id = t.id)
     and not exists (select 1 from public.booking_services s where lower(btrim(s.service_type)) = lower(btrim(t.name)));
  get diagnostics v_service_types_deleted = row_count;

  select
      (select count(*) from public.point_cards pc where public.is_qa_test_provenance(pc.created_by))
    + (select count(*) from public.ticket_templates tt where public.is_qa_test_provenance(tt.created_by))
    + (select count(*) from public.fixed_ticket_templates ft where public.is_qa_test_provenance(ft.created_by))
    + (select count(*) from public.calendar_items ci where public.is_qa_test_provenance(ci.created_by))
    + (select count(*) from public.booking_services bs where public.is_qa_test_provenance(bs.created_by))
    + (select count(*) from public.booking_service_types bst where public.is_qa_test_provenance(bst.created_by))
    + (select count(*) from public.booking_technicians bt where public.is_qa_test_provenance(bt.created_by))
    + (select count(*) from public.event_tickets et where public.is_qa_test_provenance(et.created_by))
    into v_remaining;

  -- Do not create another run on top of residual QA assets: roll back atomically.
  if v_remaining <> 0 then
    raise exception 'E2E_RECYCLE_QA_ARTIFACTS_REMAIN: %', v_remaining;
  end if;

  update public.test_execution_leases
     set runtime_recycled_at = clock_timestamp()
   where id = p_lease_id and actor_line_user_id = p_actor;

  return jsonb_build_object(
    'testAccountCount', v_test_account_count,
    'deletedAutomationRuns', v_automation_run_count,
    'deletedBookings', v_booking_count,
    'deletedEventClaims', v_event_claim_count,
    'deletedPointEntries', v_point_entry_count,
    'deletedPointTickets', v_point_ticket_count,
    'deletedPointBalances', v_point_balance_count,
    'deletedPointTransfers', v_point_transfer_count,
    'deletedMemberReferrals', v_member_referral_count,
    'deletedServiceTimeEntries', v_service_time_count,
    'deletedFixedTicketGrants', v_fixed_grant_count,
    'deletedBirthdayBenefitGrants', 0,
    'deletedSessions', v_session_count,
    'deletedPresenceSessions', v_presence_count,
    'deletedAuditRows', v_audit_count,
    'deletedIdempotencyRows', v_idempotency_count,
    'deletedRateLimitRows', v_rate_limit_count,
    'deletedScheduledMessages', v_scheduled_message_count,
    'deletedQaArtifacts', v_qa_artifact_count,
    'deletedQaExtendedArtifacts', v_extended_deleted,
    'deletedQaServiceTypes', v_service_types_deleted,
    'deletedBookingReceipts', v_old_receipts,
    'deletedMembershipConsents', v_old_consents,
    'remainingQaArtifacts', v_remaining,
    'cleanupComplete', true,
    'alreadyRecycled', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_replace_booking_benefit_selections_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_selections jsonb DEFAULT '[]'::jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_previous jsonb := '[]'::jsonb;
  v_current jsonb := '[]'::jsonb;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    raise exception 'BOOKING_NOT_FOUND';
  end if;
  if p_expected_updated_at is null or v_booking.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;
  if v_booking.status not in ('pending', 'confirmed') then
    raise exception 'BOOKING_NOT_EDITABLE';
  end if;
  if v_booking.cancellation_requested_at is not null
     and v_booking.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;

  p_selections := coalesce(p_selections, '[]'::jsonb);
  if jsonb_typeof(p_selections) <> 'array'
     or jsonb_array_length(p_selections) > 20
     or exists (
       select 1
       from jsonb_array_elements(p_selections) item
       where lower(btrim(coalesce(item->>'kind', ''))) not in ('points', 'event')
     ) then
    raise exception 'INVALID_BOOKING_BENEFITS';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'kind', benefit_kind,
        'id', benefit_ref,
        'title', title_snapshot
      )
      order by selected_at
    ),
    '[]'::jsonb
  )
  into v_previous
  from public.booking_benefit_selections
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind in ('points', 'event');

  perform public.replace_booking_benefit_selections_request(
    p_booking_id,
    v_booking.member_id,
    p_selections
  );

  update public.bookings
  set updated_at = clock_timestamp()
  where id = p_booking_id
  returning * into v_booking;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'kind', benefit_kind,
        'id', benefit_ref,
        'title', title_snapshot
      )
      order by selected_at
    ),
    '[]'::jsonb
  )
  into v_current
  from public.booking_benefit_selections
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind in ('points', 'event');

  insert into public.booking_audit_events(
    actor_line_user_id,
    actor_role,
    action,
    target_type,
    target_id,
    result,
    metadata
  ) values (
    left(coalesce(p_actor, ''), 255),
    'admin',
    'BOOKING_BENEFITS_UPDATED',
    'booking',
    p_booking_id::text,
    'success',
    jsonb_build_object(
      'previousSelections', v_previous,
      'selections', v_current,
      'status', v_booking.status
    )
  );

  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_maintenance_test_access(p_maintenance_enabled boolean, p_allow_pc_test_login boolean, p_allow_mobile_test_login boolean, p_maintenance_message text, p_updated_by text, p_add_account_count integer DEFAULT 0)
 RETURNS TABLE(created_account_count integer, total_test_accounts integer)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count integer := coalesce(p_add_account_count, 0);
  v_message text := coalesce(p_maintenance_message, '');
  v_existing integer;
  v_seq bigint;
  v_i integer;
  v_was_maintenance boolean := false;
  v_transition_to_maintenance boolean := false;
  v_revoked_at timestamptz;
  v_surnames text[] := array['陳','林','黃','張','李','王','吳','劉','蔡','楊','許','鄭','謝','洪','郭','邱','曾','廖','賴','徐'];
  v_male_names text[] := array['志明','俊傑','冠宇','柏翰','家豪','承翰','宇翔','子豪','建宏','宗翰','彥廷','品睿'];
  v_female_names text[] := array['怡君','雅婷','欣怡','佳穎','郁婷','佩珊','詩涵','筱涵','雨柔','佳蓉','婉婷','思妤'];
  v_surname text;
  v_given_name text;
  v_salutation text;
  v_birthday date;
  v_phone text;
begin
  if v_count < 0 or v_count > 50 then
    raise exception 'INVALID_TEST_ACCOUNT_COUNT';
  end if;
  if char_length(v_message) > 500 then
    raise exception 'INVALID_MAINTENANCE_MESSAGE';
  end if;

  perform pg_advisory_xact_lock(2026092001);

  select coalesce(maintenance_enabled, false)
    into v_was_maintenance
    from public.test_mode_settings
   where id = true;

  v_transition_to_maintenance :=
    not coalesce(v_was_maintenance, false)
    and coalesce(p_maintenance_enabled, false);
  if v_transition_to_maintenance then
    v_revoked_at := clock_timestamp();
  end if;

  select count(*)::integer into v_existing
  from public.members
  where is_test_account = true;

  if v_existing + v_count > 200 then
    raise exception 'TEST_ACCOUNT_LIMIT_REACHED';
  end if;

  insert into public.test_mode_settings (
    id, maintenance_enabled,
    allow_pc_test_login, allow_mobile_test_login, maintenance_message,
    maintenance_revoked_after, updated_by, updated_at
  )
  values (
    true,
    coalesce(p_maintenance_enabled, false),
    coalesce(p_allow_pc_test_login, false),
    coalesce(p_allow_mobile_test_login, false),
    v_message,
    case when v_transition_to_maintenance then v_revoked_at else null end,
    nullif(btrim(coalesce(p_updated_by, '')), ''),
    now()
  )
  on conflict (id) do update set
    maintenance_enabled = excluded.maintenance_enabled,
    allow_pc_test_login = excluded.allow_pc_test_login,
    allow_mobile_test_login = excluded.allow_mobile_test_login,
    maintenance_message = excluded.maintenance_message,
    maintenance_revoked_after = case
      when v_transition_to_maintenance then v_revoked_at
      else public.test_mode_settings.maintenance_revoked_after
    end,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at;

  if v_transition_to_maintenance then
    update public.test_login_sessions
       set revoked_at = coalesce(revoked_at, v_revoked_at),
           last_used_at = v_revoked_at
     where revoked_at is null;

    update public.member_presence_sessions
       set last_seen_at = v_revoked_at,
           offline_at = v_revoked_at,
           offline_reason = 'maintenance',
           updated_at = v_revoked_at
     where offline_at is null;
  elsif not coalesce(p_maintenance_enabled, false) then
    update public.test_login_sessions
       set revoked_at = coalesce(revoked_at, now())
     where revoked_at is null;
  else
    if not coalesce(p_allow_pc_test_login, false) then
      update public.test_login_sessions
         set revoked_at = coalesce(revoked_at, now())
       where revoked_at is null
         and device_class = 'pc';
    end if;
    if not coalesce(p_allow_mobile_test_login, false) then
      update public.test_login_sessions
         set revoked_at = coalesce(revoked_at, now())
       where revoked_at is null
         and device_class = 'mobile';
    end if;
  end if;

  for v_i in 1..v_count loop
    v_seq := nextval('public.test_member_sequence');
    v_salutation := case when random() < 0.5 then 'mr' else 'ms' end;
    v_surname := v_surnames[1 + floor(random() * array_length(v_surnames, 1))::int];
    if v_salutation = 'mr' then
      v_given_name := v_male_names[1 + floor(random() * array_length(v_male_names, 1))::int];
    else
      v_given_name := v_female_names[1 + floor(random() * array_length(v_female_names, 1))::int];
    end if;
    v_birthday := ((current_date - make_interval(years => 18 + floor(random() * 48)::int))::date
      - floor(random() * 365)::int);

    loop
      -- Match the same E.164 and phone-quality constraints as real members.
      v_phone := '+8869' || lpad(floor(random() * 100000000)::bigint::text, 8, '0');
      exit when v_phone !~ '([0-9])\1{6,}'
        and not exists (select 1 from public.members where phone = v_phone);
    end loop;

    insert into public.members (
      line_user_id, display_name, member_code, status, membership_status,
      birthday, phone, joined_at, last_login_at, surname, salutation,
      is_test_account, test_account_sequence, created_at, updated_at
    ) values (
      'TEST-' || replace(gen_random_uuid()::text, '-', ''),
      v_surname || v_given_name || '（測試）',
      'TST' || lpad(v_seq::text, 6, '0'),
      'active',
      'active',
      v_birthday,
      v_phone,
      now(),
      now(),
      v_surname,
      v_salutation,
      true,
      v_seq,
      now(),
      now()
    );
  end loop;

  return query
  select v_count, count(*)::integer
  from public.members
  where is_test_account = true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_service_grant_catalog(p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists(select 1 from public.admins where line_user_id=p_actor and role='admin' and status='active') then
    raise exception 'ADMIN_REQUIRED';
  end if;
  return jsonb_build_object('services',coalesce((
    select jsonb_agg(jsonb_build_object(
      'serviceId',id,'title',title,'serviceType',service_type,'durationMinutes',duration_minutes,
      'countsTowardMembership',counts_toward_membership,'requiresCompanionService',requires_companion_service
    ) order by service_type,title,id) from public.booking_services where is_active and deleted_at is null
  ),'[]'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_booking_items_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_items jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_settings public.booking_settings%rowtype;
  v_service public.booking_services%rowtype;
  v_item jsonb;
  v_service_id uuid;
  v_primary_service_id uuid;
  v_seen_service_ids uuid[] := array[]::uuid[];
  v_quantity integer;
  v_item_count integer;
  v_previous_items jsonb;
  v_previous_total_duration integer;
  v_previous_end_time time;
  v_total_duration integer := 0;
  v_end_time time;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if exists (select 1 from public.booking_participants where booking_id = p_booking_id) then raise exception 'BOOKING_PARTICIPANT_EDIT_REQUIRED'; end if;
  if p_expected_updated_at is null or v_booking.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;
  if v_booking.status not in ('pending','confirmed') then
    raise exception 'BOOKING_NOT_EDITABLE';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'INVALID_BOOKING_ITEMS';
  end if;

  v_item_count := jsonb_array_length(p_items);
  if v_item_count < 1 or v_item_count > 20 then
    raise exception 'INVALID_BOOKING_ITEMS';
  end if;

  select * into v_settings
  from public.booking_settings
  where id = 1
  for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;

  v_previous_total_duration := v_booking.total_duration_minutes;
  v_previous_end_time := v_booking.end_time;

  select coalesce(jsonb_agg(jsonb_build_object(
    'serviceId', bi.service_id,
    'quantity', bi.quantity,
    'serviceTitle', bi.service_title,
    'unitDurationMinutes', bi.unit_duration_minutes,
    'unitPriceAmount', bi.unit_price_amount
  ) order by bi.created_at), '[]'::jsonb)
  into v_previous_items
  from public.booking_items bi
  where bi.booking_id = p_booking_id
    and bi.service_id <> '00000000-0000-4000-8000-000000000010'::uuid;

  -- Preserve the system/store-service snapshot already attached to the booking.
  select coalesce(sum(bi.unit_duration_minutes * greatest(coalesce(bi.quantity, 1), 1)), 0)::integer
  into v_total_duration
  from public.booking_items bi
  where bi.booking_id = p_booking_id
    and bi.service_id = '00000000-0000-4000-8000-000000000010'::uuid;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    begin
      v_service_id := (v_item ->> 'serviceId')::uuid;
      v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);
    exception when others then
      raise exception 'INVALID_BOOKING_ITEMS';
    end;

    if v_service_id = '00000000-0000-4000-8000-000000000010'::uuid then
      raise exception 'BOOKING_SYSTEM_SERVICE_IMMUTABLE';
    end if;
    if v_quantity < 1 or v_quantity > 2 then
      raise exception 'INVALID_BOOKING_QUANTITY';
    end if;
    if v_service_id = any(v_seen_service_ids) then
      raise exception 'DUPLICATE_BOOKING_SERVICE';
    end if;
    v_seen_service_ids := array_append(v_seen_service_ids, v_service_id);

    select * into v_service
    from public.booking_services
    where id = v_service_id
      and deleted_at is null
    for share;

    if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
    if v_primary_service_id is null then v_primary_service_id := v_service_id; end if;
    v_total_duration := v_total_duration + (v_service.duration_minutes * v_quantity);
  end loop;

  if v_total_duration < 1 or v_total_duration > 1440 then
    raise exception 'INVALID_BOOKING_DURATION';
  end if;

  v_end_time := v_booking.start_time + make_interval(mins => v_total_duration);
  if not public.booking_slot_fits(v_booking.booking_date,v_booking.start_time,v_total_duration,v_settings.work_start_time,v_settings.work_end_time,v_settings.slot_interval_minutes) then
    raise exception 'INVALID_BOOKING_SLOT';
  end if;

  delete from public.booking_items
  where booking_id = p_booking_id
    and service_id <> '00000000-0000-4000-8000-000000000010'::uuid;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_service_id := (v_item ->> 'serviceId')::uuid;
    v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);
    select * into v_service from public.booking_services where id = v_service_id;

    insert into public.booking_items(
      booking_id,
      service_id,
      service_title,
      unit_duration_minutes,
      quantity
    ) values (
      p_booking_id,
      v_service.id,
      v_service.title,
      v_service.duration_minutes,
      v_quantity
    );
  end loop;

  begin
    update public.bookings
    set service_id = v_primary_service_id,
        total_duration_minutes = v_total_duration,
        end_time = v_end_time
    where id = p_booking_id
    returning * into v_booking;
  exception
    when exclusion_violation or unique_violation then
      raise exception 'BOOKING_SLOT_TAKEN';
  end;

  insert into public.booking_audit_events(
    actor_line_user_id,
    actor_role,
    action,
    target_type,
    target_id,
    result,
    metadata
  ) values (
    left(coalesce(p_actor, ''), 255),
    'admin',
    'BOOKING_ITEMS_UPDATED',
    'booking',
    p_booking_id::text,
    'success',
    jsonb_build_object(
      'previousItems', coalesce(v_previous_items, '[]'::jsonb),
      'items', p_items,
      'status', v_booking.status,
      'scheduleRecalculated', true,
      'previousTotalDurationMinutes', v_previous_total_duration,
      'totalDurationMinutes', v_total_duration,
      'previousEndTime', v_previous_end_time,
      'endTime', v_end_time
    )
  );

  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_booking_participant_items_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_participants jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  b public.bookings%rowtype;
  cfg public.booking_settings%rowtype;
  participant public.booking_participants%rowtype;
  service public.booking_services%rowtype;
  person jsonb;
  item jsonb;
  v_service_id uuid;
  primary_service_id uuid;
  v_quantity integer;
  v_position integer;
  seen_positions integer[] := '{}';
  seen_services uuid[];
  participant_count integer;
  store_minutes integer;
  minutes integer;
  max_minutes integer := 0;
  total_minutes integer;
  v_end_time time;
  before_items jsonb;
begin
  if not exists (
    select 1 from public.admins as a
    where a.line_user_id = p_actor and a.role = 'admin' and a.status = 'active'
  ) then raise exception 'ADMIN_REQUIRED'; end if;

  select bk.* into b from public.bookings as bk where bk.id = p_booking_id for update;
  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if p_expected_updated_at is null or b.updated_at <> p_expected_updated_at then raise exception 'BOOKING_CONFLICT'; end if;
  if b.status not in ('pending','confirmed') then raise exception 'BOOKING_NOT_EDITABLE'; end if;
  if b.cancellation_requested_at is not null and b.cancellation_reviewed_at is null then raise exception 'BOOKING_CANCELLATION_PENDING'; end if;

  select bs.* into cfg from public.booking_settings as bs where bs.id = 1 for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;

  select count(*) into participant_count
  from public.booking_participants as bp_count
  where bp_count.booking_id = b.id;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
  if participant_count < 1 or participant_count <> b.party_size or jsonb_array_length(p_participants) <> participant_count then
    raise exception 'INVALID_BOOKING_PARTICIPANTS';
  end if;

  select coalesce(jsonb_agg(to_jsonb(bpi_before) order by bp_before.position,bpi_before.service_id),'[]'::jsonb)
  into before_items
  from public.booking_participant_items as bpi_before
  join public.booking_participants as bp_before on bp_before.id = bpi_before.participant_id
  where bp_before.booking_id = b.id;

  select sum(bi_store.unit_duration_minutes * bi_store.quantity)::integer
  into store_minutes
  from public.booking_items as bi_store
  where bi_store.booking_id = b.id
    and bi_store.service_id = '00000000-0000-4000-8000-000000000010'::uuid;
  if store_minutes is null then raise exception 'INVALID_BOOKING_ITEMS'; end if;

  for person in select j.value from jsonb_array_elements(p_participants) as j(value) loop
    if coalesce(person->>'position','') !~ '^[1-9][0-9]?$' then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
    v_position := (person->>'position')::integer;
    if v_position = any(seen_positions) then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
    seen_positions := array_append(seen_positions,v_position);

    select bp.* into participant
    from public.booking_participants as bp
    where bp.booking_id = b.id and bp.position = v_position
    for update;
    if not found then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;

    if jsonb_typeof(person->'items') is distinct from 'array' then raise exception 'INVALID_BOOKING_ITEMS'; end if;
    if jsonb_array_length(person->'items') not between 1 and 20 then raise exception 'INVALID_BOOKING_ITEMS'; end if;

    minutes := 0;
    seen_services := '{}';
    delete from public.booking_participant_items as bpi_delete
    where bpi_delete.participant_id = participant.id;

    for item in select j.value from jsonb_array_elements(person->'items') as j(value) loop
      begin v_service_id := (item->>'serviceId')::uuid;
      exception when invalid_text_representation then raise exception 'INVALID_BOOKING_ITEMS'; end;
      if v_service_id is null then raise exception 'INVALID_BOOKING_ITEMS'; end if;
      if coalesce(item->>'quantity','') !~ '^[12]$' then raise exception 'INVALID_BOOKING_QUANTITY'; end if;
      v_quantity := (item->>'quantity')::integer;
      if v_service_id = '00000000-0000-4000-8000-000000000010'::uuid then raise exception 'BOOKING_SYSTEM_SERVICE_IMMUTABLE'; end if;
      if v_service_id = any(seen_services) then raise exception 'DUPLICATE_BOOKING_SERVICE'; end if;
      seen_services := array_append(seen_services,v_service_id);

      select bs.* into service
      from public.booking_services as bs
      where bs.id = v_service_id and bs.deleted_at is null
      for share;
      if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;

      if primary_service_id is null then primary_service_id := service.id; end if;
      minutes := minutes + service.duration_minutes * v_quantity;

      insert into public.booking_participant_items(participant_id,service_id,service_title,unit_duration_minutes,unit_price_amount,quantity)
      values(participant.id,service.id,service.title,service.duration_minutes,service.price_amount,v_quantity);
    end loop;

    max_minutes := greatest(max_minutes,minutes);
    if minutes < 1 or minutes >= 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;

    if participant.technician_id is not null then
      insert into public.booking_participant_reservations(participant_id,booking_id,technician_id,booking_date,start_time,end_time,is_active)
      values(participant.id,b.id,participant.technician_id,b.booking_date,b.start_time,b.start_time + make_interval(mins => minutes),true)
      on conflict (participant_id) do update set end_time = excluded.end_time, updated_at = now();
    end if;
  end loop;

  total_minutes := max_minutes + store_minutes;
  if total_minutes not between 1 and 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;
  v_end_time := b.start_time + make_interval(mins => total_minutes);
  if not public.booking_slot_fits(b.booking_date,b.start_time,total_minutes,cfg.work_start_time,cfg.work_end_time,cfg.slot_interval_minutes) then
    raise exception 'INVALID_BOOKING_SLOT';
  end if;

  delete from public.booking_items as bi_delete
  where bi_delete.booking_id = b.id
    and bi_delete.service_id <> '00000000-0000-4000-8000-000000000010'::uuid;

  insert into public.booking_items(booking_id,service_id,service_title,unit_duration_minutes,unit_price_amount,quantity,service_type,counts_toward_membership)
  select b.id,bpi.service_id,max(bpi.service_title),max(bpi.unit_duration_minutes),max(bpi.unit_price_amount),sum(bpi.quantity)::smallint,
         bs.service_type,bs.counts_toward_membership
  from public.booking_participant_items as bpi
  join public.booking_participants as bp on bp.id = bpi.participant_id
  join public.booking_services as bs on bs.id = bpi.service_id
  where bp.booking_id = b.id
  group by bpi.service_id,bs.service_type,bs.counts_toward_membership;

  update public.bookings as bk
  set service_id = primary_service_id,total_duration_minutes = total_minutes,end_time = v_end_time
  where bk.id = b.id
  returning bk.* into b;

  insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata,created_at)
  values(p_actor,'admin','BOOKING_ITEMS_UPDATED','booking',b.id::text,'success',
    jsonb_build_object('previousParticipantItems',before_items,'participants',p_participants,'totalDurationMinutes',total_minutes),b.updated_at);

  return b;
exception when exclusion_violation then raise exception 'BOOKING_SLOT_TAKEN';
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_booking_participant_technicians_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_participants jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  b public.bookings%rowtype;
  participant public.booking_participants%rowtype;
  person jsonb;
  v_position integer;
  v_technician_id uuid;
  v_primary_technician_id uuid;
  v_participant_count integer;
  v_duration integer;
  v_seen_positions integer[] := '{}';
  v_before jsonb := '[]'::jsonb;
begin
  if not exists (
    select 1
    from public.admins
    where line_user_id = p_actor
      and role = 'admin'
      and status = 'active'
  ) then
    raise exception 'ADMIN_REQUIRED';
  end if;

  select *
  into b
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    raise exception 'BOOKING_NOT_FOUND';
  end if;
  if p_expected_updated_at is null or b.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;
  if b.status not in ('pending', 'confirmed') then
    raise exception 'BOOKING_NOT_EDITABLE';
  end if;
  if b.cancellation_requested_at is not null and b.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;

  select count(*)
  into v_participant_count
  from public.booking_participants
  where booking_id = b.id;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then
    raise exception 'INVALID_BOOKING_PARTICIPANTS';
  end if;
  if v_participant_count < 1
     or v_participant_count <> b.party_size
     or jsonb_array_length(p_participants) <> v_participant_count then
    raise exception 'INVALID_BOOKING_PARTICIPANTS';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'position', p.position,
        'technicianId', coalesce(p.technician_id::text, '')
      )
      order by p.position
    ),
    '[]'::jsonb
  )
  into v_before
  from public.booking_participants p
  where p.booking_id = b.id;

  v_primary_technician_id := public.validate_group_booking_technicians(p_participants);

  -- Clear this booking's own reservations before rebuilding the final assignment.
  -- This allows valid technician swaps (A↔B) without falsely conflicting with
  -- the other participant's old reservation from the same booking.
  delete from public.booking_participant_reservations
  where booking_id = b.id;

  for person in
    select value
    from jsonb_array_elements(p_participants)
  loop
    if coalesce(person->>'position', '') !~ '^[1-9][0-9]?$' then
      raise exception 'INVALID_BOOKING_PARTICIPANTS';
    end if;

    v_position := (person->>'position')::integer;
    if v_position = any(v_seen_positions) then
      raise exception 'INVALID_BOOKING_PARTICIPANTS';
    end if;
    v_seen_positions := array_append(v_seen_positions, v_position);

    select *
    into participant
    from public.booking_participants p
    where p.booking_id = b.id
      and p.position = v_position
    for update;

    if not found then
      raise exception 'INVALID_BOOKING_PARTICIPANTS';
    end if;

    v_technician_id := null;
    if nullif(btrim(coalesce(person->>'technicianId', '')), '') is not null then
      begin
        v_technician_id := (person->>'technicianId')::uuid;
      exception
        when others then
          raise exception 'INVALID_BOOKING_TECHNICIAN';
      end;
    end if;

    update public.booking_participants
    set technician_id = v_technician_id
    where id = participant.id;

    if v_technician_id is not null then
      select coalesce(sum(unit_duration_minutes * quantity), 0)::integer
      into v_duration
      from public.booking_participant_items
      where participant_id = participant.id;

      if v_duration < 1 then
        raise exception 'INVALID_BOOKING_DURATION';
      end if;

      insert into public.booking_participant_reservations(
        participant_id,
        booking_id,
        technician_id,
        booking_date,
        start_time,
        end_time,
        is_active
      )
      values(
        participant.id,
        b.id,
        v_technician_id,
        b.booking_date,
        b.start_time,
        b.start_time + make_interval(mins => v_duration),
        true
      );
    end if;
  end loop;

  update public.bookings
  set technician_id = v_primary_technician_id,
      updated_at = now()
  where id = b.id
  returning * into b;

  insert into public.booking_audit_events(
    actor_line_user_id,
    actor_role,
    action,
    target_type,
    target_id,
    result,
    metadata,
    created_at
  )
  values(
    p_actor,
    'admin',
    'BOOKING_PARTICIPANT_TECHNICIANS_UPDATED',
    'booking',
    b.id::text,
    'success',
    jsonb_build_object(
      'previousParticipants', v_before,
      'participants', p_participants,
      'primaryTechnicianId', v_primary_technician_id
    ),
    b.updated_at
  );

  return b;
exception
  when exclusion_violation then
    raise exception 'BOOKING_SLOT_TAKEN';
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_booking_service_batch(p_operations jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_op jsonb; v_kind text; v_service_id uuid; v_title text; v_type_input text; v_type text;
  v_duration integer; v_price integer; v_active boolean; v_requires_companion boolean; v_current_requires_companion boolean;
  v_expected timestamptz; v_current_updated_at timestamptz;
  v_created integer := 0; v_updated integer := 0; v_deleted integer := 0;
begin
  if jsonb_typeof(p_operations) <> 'array' or jsonb_array_length(p_operations) < 1 or jsonb_array_length(p_operations) > 100 then raise exception 'INVALID_BATCH_OPERATIONS'; end if;
  for v_op in select value from jsonb_array_elements(p_operations) loop
    v_kind := lower(btrim(coalesce(v_op->>'op', '')));
    if v_kind not in ('create','update','delete') then raise exception 'INVALID_BATCH_OPERATION'; end if;
    if v_kind = 'delete' then
      begin v_service_id := (v_op->>'serviceId')::uuid; exception when others then raise exception 'INVALID_SERVICE_ID'; end;
      if v_service_id = '00000000-0000-4000-8000-000000000010'::uuid then raise exception 'BOOKING_SYSTEM_SERVICE_IMMUTABLE'; end if;
      select updated_at into v_current_updated_at from public.booking_services where id = v_service_id and deleted_at is null for update;
      if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
      if nullif(v_op->>'expectedUpdatedAt','') is not null then
        begin v_expected := (v_op->>'expectedUpdatedAt')::timestamptz; exception when others then raise exception 'INVALID_EXPECTED_UPDATED_AT'; end;
        if v_current_updated_at <> v_expected then raise exception 'BOOKING_SERVICE_CONFLICT'; end if;
      end if;
      update public.booking_services set is_active = false, deleted_at = now(), deleted_by = nullif(btrim(coalesce(p_actor,'')), '') where id = v_service_id;
      v_deleted := v_deleted + 1; continue;
    end if;

    v_title := btrim(coalesce(v_op->>'title',''));
    v_type_input := btrim(coalesce(v_op->>'serviceType',''));
    begin v_duration := (v_op->>'durationMinutes')::integer; exception when others then raise exception 'INVALID_SERVICE_DURATION'; end;
    begin v_price := (v_op->>'priceAmount')::integer; exception when others then raise exception 'INVALID_SERVICE_PRICE'; end;
    begin v_active := coalesce((v_op->>'isActive')::boolean, true); exception when others then raise exception 'INVALID_BATCH_OPERATION'; end;
    if v_op ? 'requiresCompanionService' and v_op->>'requiresCompanionService' is not null then
      begin v_requires_companion := (v_op->>'requiresCompanionService')::boolean; exception when others then raise exception 'INVALID_BATCH_OPERATION'; end;
    else
      v_requires_companion := null;
    end if;

    if char_length(v_title) not between 1 and 100 then raise exception 'INVALID_SERVICE_TITLE'; end if;
    if v_duration < 1 or v_duration > 720 then raise exception 'INVALID_SERVICE_DURATION'; end if;
    if v_price < 0 or v_price > 10000000 then raise exception 'INVALID_SERVICE_PRICE'; end if;
    select name into v_type from public.booking_service_types where lower(btrim(name)) = lower(v_type_input) limit 1;
    if not found then raise exception 'BOOKING_SERVICE_TYPE_INVALID'; end if;

    if v_kind = 'create' then
      insert into public.booking_services(
        title, description, service_type, duration_minutes, price_amount,
        counts_toward_membership, is_active, requires_companion_service, created_by
      )
      values (
        v_title, '__TYPE__:' || v_type, v_type, v_duration, v_price,
        true, v_active, coalesce(v_requires_companion,false), p_actor
      );
      v_created := v_created + 1;
    else
      begin v_service_id := (v_op->>'serviceId')::uuid; exception when others then raise exception 'INVALID_SERVICE_ID'; end;
      if v_service_id = '00000000-0000-4000-8000-000000000010'::uuid then raise exception 'BOOKING_SYSTEM_SERVICE_IMMUTABLE'; end if;
      select updated_at, requires_companion_service
      into v_current_updated_at, v_current_requires_companion
      from public.booking_services
      where id = v_service_id and deleted_at is null
      for update;
      if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
      if nullif(v_op->>'expectedUpdatedAt','') is not null then
        begin v_expected := (v_op->>'expectedUpdatedAt')::timestamptz; exception when others then raise exception 'INVALID_EXPECTED_UPDATED_AT'; end;
        if v_current_updated_at <> v_expected then raise exception 'BOOKING_SERVICE_CONFLICT'; end if;
      end if;
      update public.booking_services
      set title=v_title,
          description='__TYPE__:'||v_type,
          service_type=v_type,
          duration_minutes=v_duration,
          price_amount=v_price,
          is_active=v_active,
          requires_companion_service=coalesce(v_requires_companion,v_current_requires_companion)
      where id=v_service_id;
      v_updated := v_updated + 1;
    end if;
  end loop;
  return jsonb_build_object('created', v_created, 'updated', v_updated, 'deleted', v_deleted);
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_calendar_batch(p_actor_line_user_id text, p_operations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_op jsonb;
  v_item jsonb;
  v_action text;
  v_id text;
  v_expected timestamptz;
  v_result jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(p_operations) <> 'array' or jsonb_array_length(p_operations) < 1 or jsonb_array_length(p_operations) > 20 then
    raise exception 'INVALID_CALENDAR_BATCH';
  end if;

  for v_op in select value from jsonb_array_elements(p_operations)
  loop
    v_action := coalesce(nullif(v_op->>'action', ''), nullif(v_op->>'operation', ''), 'save');
    if v_action not in ('save', 'delete') then
      raise exception 'INVALID_CALENDAR_BATCH';
    end if;

    if v_action = 'delete' then
      v_id := coalesce(v_op->>'calendarItemId', v_op#>>'{calendarItem,calendarItemId}');
      v_expected := nullif(coalesce(v_op->>'expectedUpdatedAt', v_op#>>'{calendarItem,expectedUpdatedAt}'), '')::timestamptz;
      if not exists(select 1 from public.calendar_items where calendar_item_id = v_id for update) then
        raise exception 'CALENDAR_ITEM_NOT_FOUND';
      end if;
      if v_expected is not null and not exists(select 1 from public.calendar_items where calendar_item_id = v_id and updated_at = v_expected) then
        raise exception 'CONFLICT';
      end if;
    else
      v_item := coalesce(v_op->'calendarItem', v_op);
      v_id := nullif(v_item->>'calendarItemId', '');
      if v_id is not null then
        v_expected := nullif(coalesce(v_op->>'expectedUpdatedAt', v_item->>'expectedUpdatedAt'), '')::timestamptz;
        if not exists(select 1 from public.calendar_items where calendar_item_id = v_id for update) then
          raise exception 'CALENDAR_ITEM_NOT_FOUND';
        end if;
        if v_expected is not null and not exists(select 1 from public.calendar_items where calendar_item_id = v_id and updated_at = v_expected) then
          raise exception 'CONFLICT';
        end if;
      end if;
    end if;
  end loop;

  for v_op in select value from jsonb_array_elements(p_operations)
  loop
    v_action := coalesce(nullif(v_op->>'action', ''), nullif(v_op->>'operation', ''), 'save');
    if v_action = 'delete' then
      v_id := coalesce(v_op->>'calendarItemId', v_op#>>'{calendarItem,calendarItemId}');
      delete from public.calendar_items where calendar_item_id = v_id;
      v_result := v_result || jsonb_build_array(jsonb_build_object('action', 'delete', 'calendarItemId', v_id));
    else
      v_item := coalesce(v_op->'calendarItem', v_op);
      v_id := nullif(v_item->>'calendarItemId', '');
      if v_id is null then
        v_id := public.new_public_id('CAL');
        insert into public.calendar_items(
          calendar_item_id, title, item_type, description, starts_on, ends_on, status, accent, allowed_tier_keys, link_label, link_url, created_by, updated_by
        ) values(
          v_id, trim(v_item->>'title'), v_item->>'itemType', coalesce(v_item->>'description', ''), (v_item->>'startsOn')::date,
          nullif(v_item->>'endsOn', '')::date, v_item->>'status', v_item->>'accent',
          coalesce(array(select jsonb_array_elements_text(v_item->'allowedTierKeys')), array[]::text[]),
          coalesce(v_item->>'linkLabel', ''), coalesce(v_item->>'linkUrl', ''), p_actor_line_user_id, p_actor_line_user_id
        );
      else
        update public.calendar_items set
          title = trim(v_item->>'title'),
          item_type = v_item->>'itemType',
          description = coalesce(v_item->>'description', ''),
          starts_on = (v_item->>'startsOn')::date,
          ends_on = nullif(v_item->>'endsOn', '')::date,
          status = v_item->>'status',
          accent = v_item->>'accent',
          allowed_tier_keys = coalesce(array(select jsonb_array_elements_text(v_item->'allowedTierKeys')), array[]::text[]),
          link_label = coalesce(v_item->>'linkLabel', ''),
          link_url = coalesce(v_item->>'linkUrl', ''),
          updated_by = p_actor_line_user_id,
          updated_at = now()
        where calendar_item_id = v_id;
      end if;
      v_result := v_result || jsonb_build_array(jsonb_build_object('action', 'save', 'calendarItemId', v_id));
    end if;
  end loop;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_fixed_ticket_location_rule()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_requires boolean;
  v_locations jsonb;
begin
  if new.fixed_ticket_template_id is null then
    return new;
  end if;

  select requires_location, redemption_locations
    into v_requires, v_locations
  from public.fixed_ticket_templates
  where id = new.fixed_ticket_template_id;

  if found then
    new.requires_location := coalesce(v_requires,false);
    new.redemption_locations := case when coalesce(v_requires,false) then coalesce(v_locations,'[]'::jsonb) else '[]'::jsonb end;
  end if;
  return new;
end;
$function$

