CREATE OR REPLACE FUNCTION public.assert_booking_item_bundle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_booking_id uuid;
  v_status text;
  v_store_count integer;
  v_visible_count integer;
  v_store_duration integer;
  v_invalid_store_count integer;
begin
  if tg_table_name = 'bookings' then
    v_booking_id := coalesce(new.id, old.id);
  else
    v_booking_id := coalesce(new.booking_id, old.booking_id);
  end if;

  select status into v_status
  from public.bookings
  where id = v_booking_id;

  if not found or v_status not in ('pending', 'confirmed') then
    return coalesce(new, old);
  end if;

  select duration_minutes into v_store_duration
  from public.booking_services
  where id = '00000000-0000-4000-8000-000000000010'::uuid
    and is_active = true
    and deleted_at is null;

  if not found then
    raise exception 'BOOKING_SERVICE_NOT_FOUND';
  end if;

  select
    count(*) filter (where service_id = '00000000-0000-4000-8000-000000000010'::uuid),
    count(*) filter (where service_id <> '00000000-0000-4000-8000-000000000010'::uuid),
    count(*) filter (
      where service_id = '00000000-0000-4000-8000-000000000010'::uuid
        and (quantity <> 1 or unit_duration_minutes <> v_store_duration)
    )
  into v_store_count, v_visible_count, v_invalid_store_count
  from public.booking_items
  where booking_id = v_booking_id;

  if v_store_count <> 1 or v_visible_count < 1 or v_invalid_store_count <> 0 then
    raise exception 'INVALID_BOOKING_ITEMS';
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_member_invite_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_candidate text;
begin
  if new.membership_status = 'active' and nullif(btrim(coalesce(new.invite_code, '')), '') is null then
    loop
      v_candidate := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
      exit when not exists (
        select 1 from public.members where invite_code = v_candidate and id <> new.id
      );
    end loop;
    new.invite_code := v_candidate;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_member_removal(p_actor text, p_target text, p_confirm_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m members%rowtype; j member_removal_jobs%rowtype; h text:=encode(extensions.digest(p_target,'sha256'),'hex');
begin
 if not exists(select 1 from admins where line_user_id=p_actor and role='admin' and status='active') then raise exception 'ADMIN_REQUIRED'; end if;
 if p_actor=p_target or exists(select 1 from admins where line_user_id=p_target) then raise exception 'ADMIN_PROTECTED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('member-removal:'||h,0));
 select * into m from members where line_user_id=p_target for update;
 select * into j from member_removal_jobs where identity_hash=h for update;
 if m.id is null then
   if j.state='complete' then return jsonb_build_object('jobId',j.id,'state','complete'); end if;
   raise exception 'MEMBER_NOT_FOUND';
 end if;
 if exists(select 1 from test_execution_leases where expires_at>clock_timestamp()) and m.is_test_account then raise exception 'E2E_ACTIVE'; end if;
 if m.member_code is distinct from p_confirm_code then raise exception 'CONFIRMATION_MISMATCH'; end if;
 if j.id is not null and j.state='deleting' then return jsonb_build_object('jobId',j.id,'state',j.state,'memberId',j.member_id); end if;
 insert into member_removal_jobs(identity_hash,member_id,state,revoked_before,completed_at)
 values(h,m.id,'deleting',clock_timestamp(),null)
 on conflict(identity_hash) do update set member_id=excluded.member_id,state='deleting',revoked_before=excluded.revoked_before,completed_at=null returning * into j;
 update member_removal_jobs set run_ids=coalesce((select array_agg(distinct run_id) from automation_test_cases where member_id=m.id),'{}'::uuid[]) where id=j.id;
 update member_removal_jobs set artifact_paths=coalesce((select array_agg(distinct o.name) from storage.objects o join automation_test_runs r on r.id=any((select run_ids from member_removal_jobs where id=j.id)::uuid[]) where o.bucket_id='e2e-failure-artifacts' and (o.name like 'runs/'||r.run_code||'--%' or (nullif(r.summary->>'rootRunId','') is not null and o.name like 'runs/'||(r.summary->>'rootRunId')||'--%') or exists(select 1 from jsonb_path_query(r.summary,'$.**.path') path where path#>>'{}'=o.name))),'{}'::text[]) where id=j.id;
 perform set_config('membership.removal_job',j.id::text,true);
 update members set status='disabled',force_logout_after=j.revoked_before,updated_at=now() where id=m.id;
 delete from member_login_token_grants where line_user_id=p_target;
 delete from member_login_sessions where line_user_id=p_target;
 update test_login_sessions set revoked_at=clock_timestamp(),revoked_reason='member_removed' where member_id=m.id;
 update member_presence_sessions set offline_at=clock_timestamp(),offline_reason='member_removed' where member_id=m.id;
 insert into realtime_events(scope,event_type) values('all','member.removal.started');
 return jsonb_build_object('jobId',j.id,'state',j.state,'memberId',m.id);
end; $function$

CREATE OR REPLACE FUNCTION public.cancel_snapshot_receipt_request(p_receipt_id text, p_member_id uuid, p_actor text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.booking_receipts%rowtype;
begin
 perform 1 from public.members where id=p_member_id and line_user_id=p_actor and status='active' and membership_status='active' for update;
 if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;
 select * into r from public.booking_receipts where receipt_id=p_receipt_id and member_id=p_member_id and submission_mode='accessible' for update;
 if not found then raise exception 'RECEIPT_NOT_OWNED'; end if;
 if r.status='failed' and r.failure_reason='member-cancelled' then return jsonb_build_object('cancelled',true,'alreadyApplied',true); end if;
 if r.status not in ('pending_upload','awaiting_review') then raise exception 'RECEIPT_NOT_PENDING'; end if;
 if r.updated_at is distinct from p_expected_updated_at then raise exception 'BOOKING_CONFLICT'; end if;
 update public.booking_receipts set status='failed',failure_reason='member-cancelled',updated_at=now() where id=r.id;
 insert into public.booking_receipt_cleanup_queue(object_path,reason) values(r.object_path,'member-cancelled') on conflict(object_path) do nothing;
 insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
 values(public.new_public_id('AUD'),p_actor,'member','SNAPSHOT_CANCELLED','receipt',p_receipt_id,'success','{}');
 return jsonb_build_object('cancelled',true);
end $function$

CREATE OR REPLACE FUNCTION public.claim_event_ticket(p_line_user_id text, p_event_ticket_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member public.members%rowtype;
  v_event public.event_tickets%rowtype;
  v_tier text;
  v_claim_id text;
  v_today date;
  v_count integer;
begin
  select * into v_member from public.members
    where line_user_id=p_line_user_id and membership_status='active' and status='active';
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  select * into v_event from public.event_tickets
    where event_ticket_id=p_event_ticket_id for update;
  if not found then raise exception 'EVENT_TICKET_NOT_AVAILABLE'; end if;
  if v_event.fixed_ticket_template_id is not null then raise exception 'FIXED_TICKET_AUTO_ONLY'; end if;
  if v_event.ticket_type = 'referral' then raise exception 'REFERRAL_TICKET_AUTO_ONLY'; end if;
  if v_event.ticket_type = 'membership_join' then raise exception 'MEMBERSHIP_JOIN_TICKET_AUTO_ONLY'; end if;

  select claim_id into v_claim_id from public.event_ticket_claims
    where event_ticket_id=v_event.id and member_id=v_member.id;
  if found then return jsonb_build_object('claimId',v_claim_id,'alreadyClaimed',true); end if;

  if v_event.deleted_at is not null or v_event.status <> 'active' then raise exception 'EVENT_TICKET_NOT_AVAILABLE'; end if;
  v_today := (clock_timestamp() at time zone 'Asia/Taipei')::date;
  if v_event.starts_on is not null and v_today < v_event.starts_on then raise exception 'EVENT_NOT_STARTED'; end if;
  if v_event.ends_on is not null and v_today > v_event.ends_on then raise exception 'EVENT_ENDED'; end if;

  v_tier := public.current_tier_key(v_member.id);
  if not (v_tier = any(v_event.allowed_tier_keys)) then raise exception 'TIER_NOT_ALLOWED'; end if;

  if v_event.quota > 0 then
    select count(*)::integer into v_count from public.event_ticket_claims where event_ticket_id=v_event.id;
    if v_count >= v_event.quota then raise exception 'EVENT_QUOTA_REACHED'; end if;
  end if;

  v_claim_id := public.new_public_id('EC');
  insert into public.event_ticket_claims(
    claim_id,event_ticket_id,member_id,ticket_type,ticket_title,ticket_description,usage_method,usage_instructions,prizes
  ) values (
    v_claim_id,v_event.id,v_member.id,v_event.ticket_type,v_event.title,v_event.description,v_event.usage_method,v_event.usage_instructions,v_event.prizes
  );

  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result)
    values(public.new_public_id('AUD'),v_member.line_user_id,'member','user.event.ticket.claim','event_ticket',v_event.event_ticket_id,'success');

  return jsonb_build_object('claimId',v_claim_id,'alreadyClaimed',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_fixed_ticket_calendar_items_on_template_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_template_id uuid;
  v_should_cleanup boolean;
begin
  if tg_op = 'DELETE' then
    v_template_id := old.id;
    v_should_cleanup := true;
  else
    v_template_id := new.id;
    v_should_cleanup := new.deleted_at is not null
      or new.status <> 'active'
      or new.calendar_enabled is not true;
  end if;

  if v_should_cleanup then
    delete from public.calendar_items c
    using public.event_tickets e
    where c.source_event_ticket_id = e.id
      and e.fixed_ticket_template_id = v_template_id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_booking_with_benefits_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_admin_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_member public.members%rowtype;
  v_selection public.booking_benefit_selections%rowtype;
  v_calendar public.calendar_items%rowtype;
  v_point_selection_ids uuid[];
  v_point_ids text[];
  v_event_ids text[];
  v_point_result jsonb := null;
  v_event_result jsonb := null;
  v_settlement jsonb;
  v_redemptions jsonb := '[]'::jsonb;
  v_tier text;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if p_expected_updated_at is null or v_booking.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;
  if v_booking.cancellation_requested_at is not null
     and v_booking.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;
  if v_booking.status <> 'confirmed' then
    raise exception 'INVALID_BOOKING_TRANSITION';
  end if;

  select * into v_member
  from public.members
  where id = v_booking.member_id
  for update;

  if not found
     or v_member.membership_status <> 'active'
     or v_member.status <> 'active' then
    raise exception 'MEMBERSHIP_REQUIRED';
  end if;

  select
    array_agg(id order by benefit_ref),
    array_agg(benefit_ref order by benefit_ref)
    into v_point_selection_ids, v_point_ids
  from public.booking_benefit_selections
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind = 'points';

  select array_agg(benefit_ref order by benefit_ref)
    into v_event_ids
  from public.booking_benefit_selections
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind = 'event';

  v_tier := public.current_tier_key(v_booking.member_id);
  for v_selection in
    select *
    from public.booking_benefit_selections
    where booking_id = p_booking_id
      and status = 'pending'
      and benefit_kind = 'calendar'
    order by benefit_ref
    for update
  loop
    select * into v_calendar
    from public.calendar_items
    where calendar_item_id = v_selection.benefit_ref
      and item_type = 'event';

    if not found
       or v_calendar.starts_on > v_booking.booking_date
       or coalesce(v_calendar.ends_on, v_calendar.starts_on) < v_booking.booking_date
       or (
         cardinality(v_calendar.allowed_tier_keys) > 0
         and not (v_tier = any(v_calendar.allowed_tier_keys))
       ) then
      raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
    end if;

    if coalesce(v_calendar.audience_type, 'all') = 'birthday_month' then
      if v_calendar.status <> 'targeted'
         or v_member.birthday is null
         or extract(month from v_member.birthday)::int <> v_calendar.audience_month then
        raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
      end if;
    elsif v_calendar.status <> 'active' then
      raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
    end if;
  end loop;

  if coalesce(cardinality(v_point_ids), 0) > 0 then
    -- Release only this booking's held points inside the same transaction.
    -- Any later failure rolls this status change and the point redemption back together.
    update public.booking_benefit_selections
    set status = 'redeemed'
    where id = any(v_point_selection_ids)
      and status = 'pending'
      and benefit_kind = 'points';

    v_point_result := public.redeem_point_tickets(
      v_member.line_user_id,
      v_point_ids,
      'BOOKING_POINT_' || replace(p_booking_id::text, '-', '')
    );
  end if;

  if coalesce(cardinality(v_event_ids), 0) > 0 then
    v_event_result := public.redeem_event_tickets_for_booking_request(
      v_member.line_user_id,
      v_event_ids,
      'BOOKING_EVENT_' || replace(p_booking_id::text, '-', ''),
      null,
      p_booking_id
    );
  end if;

  v_settlement := public.complete_booking_with_rewards_request(
    p_booking_id,
    p_expected_updated_at,
    p_actor,
    left(coalesce(p_admin_note, ''), 500)
  );

  if coalesce(cardinality(v_point_selection_ids), 0) > 0 then
    update public.booking_benefit_selections
    set redeemed_at = now(),
        redeemed_by = p_actor,
        result = v_point_result
    where id = any(v_point_selection_ids)
      and status = 'redeemed'
      and benefit_kind = 'points';
  end if;

  update public.booking_benefit_selections
  set status = 'redeemed',
      redeemed_at = now(),
      redeemed_by = p_actor,
      result = v_event_result
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind = 'event';

  update public.booking_benefit_selections
  set status = 'applied',
      redeemed_at = now(),
      redeemed_by = p_actor,
      result = jsonb_build_object('activityApplied', true)
  where booking_id = p_booking_id
    and status = 'pending'
    and benefit_kind = 'calendar';

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'kind', benefit_kind,
        'id', benefit_ref,
        'title', title_snapshot,
        'status', status,
        'result', result
      )
      order by selected_at, id
    ),
    '[]'::jsonb
  )
    into v_redemptions
  from public.booking_benefit_selections
  where booking_id = p_booking_id
    and status in ('redeemed', 'applied');

  insert into public.audit_logs(
    audit_id,
    actor_line_user_id,
    actor_role,
    action,
    target_type,
    target_id,
    result,
    detail
  ) values (
    public.new_public_id('AUD'),
    p_actor,
    'admin',
    'admin.booking.benefits.redeem',
    'booking',
    p_booking_id::text,
    'success',
    jsonb_build_object('redemptions', v_redemptions)
  );

  return coalesce(v_settlement, '{}'::jsonb)
    || jsonb_build_object('redemptions', v_redemptions);
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_booking_with_rewards_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_admin_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 perform 1 from public.booking_settings where id=1 for share;
 perform 1 from public.booking_service_type_rewards order by service_type_id for share;
 result:=public.complete_booking_with_rewards_base(p_booking_id,p_expected_updated_at,p_actor,p_admin_note);
 update public.booking_completion_settlements set correction_context=public.booking_reward_context((result->>'primaryTechnicianId')::uuid) where booking_id=p_booking_id;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.consume_api_rate_limit(p_principal_hash text, p_is_write boolean, p_cost integer DEFAULT 1, p_read_limit integer DEFAULT 90, p_write_limit integer DEFAULT 30)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_bucket timestamptz := date_trunc('minute', now());
  v_qa_mode boolean := false;
  v_multiplier integer := 1;
  v_effective_principal_hash text := p_principal_hash;
  v_type text := case when p_is_write then 'write' else 'read' end;
  v_limit integer;
  v_count integer;
begin
  if p_cost < 1 or p_cost > 20 then
    return false;
  end if;

  select coalesce(settings.maintenance_enabled, false)
    into v_qa_mode
  from public.test_mode_settings as settings
  where settings.id = true;

  v_qa_mode := coalesce(v_qa_mode, false);
  if v_qa_mode then
    v_multiplier := 8;
    v_effective_principal_hash := 'qa:' || p_principal_hash;
  end if;

  v_limit := greatest(
    1,
    (case when p_is_write then p_write_limit else p_read_limit end) * v_multiplier
  );

  insert into public.api_rate_limits(principal_hash, bucket_at, bucket_type, request_count)
  values(v_effective_principal_hash, v_bucket, v_type, p_cost)
  on conflict(principal_hash, bucket_at, bucket_type)
  do update set request_count = public.api_rate_limits.request_count + excluded.request_count
  returning request_count into v_count;

  delete from public.api_rate_limits
  where bucket_at < now() - interval '2 hours';

  return v_count <= v_limit;
end;
$function$

CREATE OR REPLACE FUNCTION public.copy_admin_settings(p_actor text, p_kind text, p_source text, p_title text, p_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_key text:='settings-copy:'||p_actor||':'||p_request_id;
 v_hash text:=encode(extensions.digest(jsonb_build_array(p_kind,p_source,btrim(p_title))::text,'sha256'),'hex');
 previous public.idempotency_results%rowtype; source jsonb; copied jsonb; child jsonb; reward record;
 new_id uuid:=gen_random_uuid(); new_public text; child_id uuid; result jsonb;
begin
 if not exists(select 1 from public.admins where line_user_id=p_actor and status='active' and role='admin') then raise exception 'ADMIN_REQUIRED'; end if;
 if p_request_id !~ '^COPY-[A-Za-z0-9-]{8,100}$' or char_length(btrim(p_title)) not between 1 and 100 then raise exception 'INVALID_COPY_INPUT'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_key,0));
 select * into previous from public.idempotency_results where request_key=v_key;
 if found then
  if previous.request_hash<>v_hash then raise exception 'REQUEST_ID_CONFLICT'; end if;
  return previous.result;
 end if;
 if p_kind='card' then
  select to_jsonb(c) into source from public.point_cards c where card_id=p_source for share;
  new_public:=public.new_public_id('PC');
 elsif p_kind='ticket' then
  select to_jsonb(c) into source from public.ticket_templates c where ticket_template_id=p_source for share;
  new_public:=public.new_public_id('TT');
 elsif p_kind='event' then
  select to_jsonb(c) into source from public.event_tickets c where event_ticket_id=p_source and deleted_at is null and fixed_ticket_template_id is null and referral_source_event_ticket_id is null for share;
  new_public:=public.new_public_id('EV');
 elsif p_kind='fixed' then
  select to_jsonb(c) into source from public.fixed_ticket_templates c where fixed_ticket_id=p_source and deleted_at is null for share;
  new_public:=public.new_public_id('FT');
 else raise exception 'INVALID_COPY_KIND'; end if;
 if source is null then raise exception 'COPY_SOURCE_NOT_FOUND'; end if;
 copied:=source||jsonb_build_object('id',new_id,'title',btrim(p_title),'status','draft','created_by',p_actor,'updated_by',p_actor,'created_at',now(),'updated_at',now());
 if p_kind='card' then
  copied:=copied||jsonb_build_object('card_id',new_public);
  insert into public.point_cards select (jsonb_populate_record(null::public.point_cards,copied)).*;
  for reward in select * from public.point_card_rewards where point_card_id=(source->>'id')::uuid order by threshold_stamps for share loop
   select to_jsonb(t) into child from public.ticket_templates t where id=reward.ticket_template_id for share;
   child_id:=gen_random_uuid();
   child:=child||jsonb_build_object('id',child_id,'ticket_template_id',public.new_public_id('TT'),'status','draft','created_by',p_actor,'updated_by',p_actor,'created_at',now(),'updated_at',now());
   insert into public.ticket_templates select (jsonb_populate_record(null::public.ticket_templates,child)).*;
   insert into public.point_card_rewards(reward_id,point_card_id,threshold_stamps,ticket_template_id,required_service_ids,required_service_match_mode)
    values(public.new_public_id('RW'),new_id,reward.threshold_stamps,child_id,reward.required_service_ids,reward.required_service_match_mode);
  end loop;
 elsif p_kind='ticket' then
  insert into public.ticket_templates select (jsonb_populate_record(null::public.ticket_templates,copied||jsonb_build_object('ticket_template_id',new_public))).*;
 elsif p_kind='event' then
  insert into public.event_tickets select (jsonb_populate_record(null::public.event_tickets,copied||jsonb_build_object('event_ticket_id',new_public,'deleted_at',null,'fixed_ticket_template_id',null,'fixed_cycle_key',null,'referral_source_event_ticket_id',null))).*;
 else
  insert into public.fixed_ticket_templates select (jsonb_populate_record(null::public.fixed_ticket_templates,copied||jsonb_build_object('fixed_ticket_id',new_public,'deleted_at',null,'notify_line',false,'calendar_enabled',false))).*;
 end if;
 result:=jsonb_build_object('kind',p_kind,'publicId',new_public,'status','draft');
 insert into public.idempotency_results(request_key,action,actor_line_user_id,request_hash,result) values(v_key,'admin.settings.copy',p_actor,v_hash,result);
 insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
 values(public.new_public_id('AUD'),p_actor,'admin','SETTINGS_COPIED',p_kind,new_public,'success',jsonb_build_object('sourceId',p_source,'newId',new_public));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.correct_completed_booking_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_request_id text, p_reason text, p_participants jsonb, p_apply boolean, p_expected_preview jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.bookings%rowtype; original public.booking_completion_settlements%rowtype;
 previous public.booking_completion_adjustments%rowtype; context jsonb; before_value jsonb; after_value jsonb;
 before_items jsonb; result jsonb; old_minutes integer; new_minutes integer; delta integer;
 recipient uuid; primary_id uuid; candidates uuid[]; line record; card public.point_cards%rowtype; balance integer;
 reward_member uuid; reward_key text; old_points jsonb; new_points jsonb; old_total integer; new_total integer;
 entry_request text; delegated boolean;
begin
 if not exists(select 1 from public.admins where line_user_id=p_actor and role='admin' and status='active') then raise exception 'ADMIN_REQUIRED'; end if;
 if p_request_id is null or p_request_id!~'^[A-Za-z0-9_-]{8,120}$' then raise exception 'INVALID_REQUEST_ID'; end if;
 if length(btrim(coalesce(p_reason,''))) not between 1 and 500 then raise exception 'CORRECTION_REASON_REQUIRED'; end if;
 select * into b from public.bookings where id=p_booking_id for update;
 if not found or b.status<>'completed' then raise exception 'BOOKING_NOT_EDITABLE'; end if;
 select * into previous from public.booking_completion_adjustments where booking_id=p_booking_id and request_id=p_request_id;
 if found then
 if previous.participants<>p_participants or previous.reason<>p_reason then raise exception 'REQUEST_ID_CONFLICT'; end if;
 return previous.result||jsonb_build_object('alreadyApplied',true);
 end if;
 if b.updated_at is distinct from p_expected_updated_at then raise exception 'BOOKING_CONFLICT'; end if;
 select * into original from public.booking_completion_settlements where booking_id=p_booking_id for update;
 if not found then raise exception 'BOOKING_COMPLETION_REQUIRES_SETTLEMENT'; end if;
 recipient:=original.member_id; delegated:=recipient<>b.member_id;
 perform 1 from public.members where id in(recipient,b.member_id) order by id for update;
 before_value:=jsonb_build_object('serviceMinutes',original.service_minutes,'rewards',original.reward_details,
 'friendRewardMinutes',coalesce((select service_minutes from public.friend_booking_rewards where booking_id=b.id),0),
 'friendRewards',coalesce((select reward_details from public.friend_booking_rewards where booking_id=b.id),'[]'));
 select after_settlement into after_value from public.booking_completion_adjustments where booking_id=b.id order by created_at desc,id desc limit 1;
 if found then before_value:=after_value; end if;
 context:=original.correction_context;
 if context is null then
 -- Historical records are editable only when the original reward recipient can be identified.
 select array_agg(x.technician_id) into candidates from (
 select bp.technician_id from public.booking_participants bp left join public.booking_participant_items pi on pi.participant_id=bp.id
 left join public.booking_items bi on bi.booking_id=bp.booking_id and bi.service_id=pi.service_id
 where bp.booking_id=b.id and bp.technician_id is not null group by bp.technician_id
 having coalesce(sum(pi.unit_duration_minutes*pi.quantity) filter(where bi.counts_toward_membership and pi.service_id<>'00000000-0000-4000-8000-000000000010'::uuid),0)=original.service_minutes
 ) x;
 if cardinality(candidates) is distinct from 1 then raise exception 'CORRECTION_CONTEXT_REQUIRED'; end if;
 context:=jsonb_build_object('primaryTechnicianId',candidates[1],'rules',original.reward_details);
 -- Historical orders contain rates only for their original service types.
 -- Never invent a historical rate for a newly added rewarded type.
 if exists(select 1 from jsonb_array_elements(p_participants) person cross join lateral jsonb_array_elements(person->'items') item
 join public.booking_services bs on bs.id=(item->>'serviceId')::uuid join public.booking_service_types st on lower(btrim(st.name))=lower(btrim(bs.service_type))
 join public.booking_service_type_rewards rw on rw.service_type_id=st.id where not exists(select 1 from jsonb_array_elements(original.reward_details) r where r->>'serviceTypeId'=st.id::text)) then raise exception 'CORRECTION_CONTEXT_REQUIRED'; end if;
 end if;
 select coalesce(jsonb_agg(to_jsonb(i) order by bp.position,i.service_id),'[]') into before_items from public.booking_participant_items i join public.booking_participants bp on bp.id=i.participant_id where bp.booking_id=b.id;
 begin
 perform public.replace_completed_booking_items(p_booking_id,p_expected_updated_at,p_actor,p_participants);
 -- A redeemed ticket's service requirement cannot be invalidated by a correction.
 if exists(select 1 from public.booking_benefit_selections s where s.booking_id=b.id and s.status='redeemed' and s.benefit_kind in('points','event') and not public.booking_ticket_matches_services(b.id,s.member_id,s.benefit_kind,s.benefit_ref)) then raise exception 'BOOKING_REDEEMED_BENEFIT_SERVICE_REQUIRED'; end if;
 after_value:=public.calculate_corrected_booking_settlement(b.id,context);
 if not delegated then after_value:=after_value||jsonb_build_object('friendRewardMinutes',0,'friendRewards','[]'::jsonb); end if;
 entry_request:='booking-adjust:'||b.id::text||':'||p_request_id;
 result:=jsonb_build_object('before',before_value,'after',after_value,'serviceMinutesDelta',(after_value->>'serviceMinutes')::integer-(before_value->>'serviceMinutes')::integer,'pointDeltas','[]'::jsonb);
 for line in select * from (values(recipient,'rewards'::text),(b.member_id,'friendRewards'::text)) as targets(member_id,reward_key) loop
 if line.reward_key='friendRewards' and not delegated then continue; end if;
 reward_member:=line.member_id; reward_key:=line.reward_key;
 old_points:=before_value->reward_key; new_points:=after_value->reward_key;
 for card in select pc.* from public.point_cards pc where pc.id in(
 select (r->>'pointCardId')::uuid from jsonb_array_elements(old_points||new_points) r) order by pc.id for update loop
 select coalesce(sum((r->>'points')::integer),0)::integer into old_total from jsonb_array_elements(old_points) r where r->>'pointCardId'=card.id::text;
 select coalesce(sum((r->>'points')::integer),0)::integer into new_total from jsonb_array_elements(new_points) r where r->>'pointCardId'=card.id::text;
 delta:=new_total-old_total;
 if delta=0 then continue; end if;
 if delta>0 and (card.status<>'active' or (card.expiry_mode<>'unlimited' and card.expires_on<(clock_timestamp() at time zone 'Asia/Taipei')::date)) then raise exception 'BOOKING_REWARD_POINT_CARD_UNAVAILABLE'; end if;
 select stamps into balance from public.point_balances where member_id=reward_member and point_card_id=card.id for update;
 if coalesce(balance,0)+delta<0 then raise exception 'INSUFFICIENT_POINTS'; end if;
 entry_request:='booking-adjust:'||b.id::text||':'||p_request_id;
 insert into public.point_entries(entry_id,member_id,point_card_id,amount,note,created_by,request_id,entry_type,reference_type,reference_id)
 values(public.new_public_id('PE'),reward_member,card.id,delta,p_reason,p_actor,entry_request,'adjustment','booking',b.id::text);
 insert into public.point_balances(member_id,point_card_id,stamps) values(reward_member,card.id,coalesce(balance,0)+delta)
 on conflict(member_id,point_card_id) do update set stamps=excluded.stamps,updated_at=now();
 if delta>0 then perform public.issue_eligible_point_tickets(reward_member,card.id); end if;
 result:=jsonb_set(result,'{pointDeltas}',result->'pointDeltas'||jsonb_build_array(jsonb_build_object('memberId',reward_member,'pointCardId',card.id,'cardTitle',card.title,'delta',delta)));
 end loop;
 old_minutes:=(before_value->>case when reward_key='rewards' then 'serviceMinutes' else 'friendRewardMinutes' end)::integer;
 new_minutes:=(after_value->>case when reward_key='rewards' then 'serviceMinutes' else 'friendRewardMinutes' end)::integer;
 delta:=new_minutes-old_minutes;
 if delta<>0 then
 if coalesce((select sum(minutes) from public.service_time_entries where member_id=reward_member),0)+delta<0 then raise exception 'INVALID_SERVICE_TIME_BALANCE'; end if;
 insert into public.service_time_entries(entry_id,member_id,minutes,note,created_by,request_id,entry_kind)
 values(public.new_public_id('SE'),reward_member,delta,p_reason,p_actor,entry_request,'adjustment');
 end if;
 end loop;
 if not p_apply then raise sqlstate 'ZX001'; end if;
 if p_expected_preview is null or p_expected_preview<>result then raise exception 'CORRECTION_PREVIEW_STALE'; end if;
 update public.booking_completion_settlements set correction_context=context where booking_id=b.id;
 insert into public.booking_completion_adjustments(booking_id,request_id,actor,reason,participants,before_items,before_settlement,after_settlement,result)
 values(b.id,p_request_id,p_actor,p_reason,p_participants,before_items,before_value,after_value,result);
 insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
 values(p_actor,'admin','COMPLETED_BOOKING_CORRECTED','booking',b.id::text,'success',result||jsonb_build_object('reason',p_reason,'requestId',p_request_id));
 return result;
 exception when sqlstate 'ZX001' then return result; end;
end $function$

CREATE OR REPLACE FUNCTION public.count_today_usable_event_tickets(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member public.members%rowtype;
  v_tier text;
  v_today date := (clock_timestamp() at time zone 'Asia/Taipei')::date;
  v_day_start timestamptz := (v_today::timestamp at time zone 'Asia/Taipei');
  v_day_end timestamptz := ((v_today + 1)::timestamp at time zone 'Asia/Taipei');
  v_available_count integer := 0;
  v_used_today_count integer := 0;
  v_max_tickets integer := 1;
  v_remaining_today integer := 0;
begin
  select * into v_member
  from public.members
  where line_user_id=p_line_user_id
    and status='active'
    and membership_status='active';
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  v_tier:=public.current_tier_key(v_member.id);

  select coalesce(max_tickets_per_day, 1)
    into v_max_tickets
  from public.event_ticket_settings
  where id=1;
  v_max_tickets := coalesce(v_max_tickets,1);

  select count(*)::integer into v_used_today_count
  from public.event_ticket_claims c
  where c.member_id=v_member.id
    and c.status='used'
    and c.used_at >= v_day_start
    and c.used_at < v_day_end;

  select count(*)::integer into v_available_count
  from public.event_ticket_claims c
  join public.event_tickets e on e.id=c.event_ticket_id
  where c.member_id=v_member.id
    and c.status='claimed'
    and e.deleted_at is null
    and e.status='active'
    and (e.starts_on is null or e.starts_on<=v_today)
    and (e.ends_on is null or e.ends_on>=v_today)
    and v_tier=any(e.allowed_tier_keys);

  if v_max_tickets = 0 then
    v_remaining_today := v_available_count;
  else
    v_remaining_today := greatest(v_max_tickets - v_used_today_count, 0);
  end if;

  return jsonb_build_object(
    'businessDate',v_today,
    'availableTodayCount',v_available_count,
    'usedTodayCount',v_used_today_count,
    'remainingTodayCount',v_remaining_today,
    'maxTicketsPerDay',v_max_tickets,
    'maxTicketsPerRedemption',v_max_tickets,
    'todayUsableCount',least(v_available_count,v_remaining_today)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_booking_bundle_request(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_member_note text DEFAULT ''::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_settings public.booking_settings%rowtype;
  v_member public.members%rowtype;
  v_existing public.bookings%rowtype;
  v_booking public.bookings%rowtype;
  v_service public.booking_services%rowtype;
  v_item jsonb;
  v_service_id uuid;
  v_primary_service_id uuid;
  v_seen_service_ids uuid[] := array[]::uuid[];
  v_quantity integer;
  v_total_duration integer := 0;
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_local_time time := (now() at time zone 'Asia/Taipei')::time;
  v_end_time time;
  v_item_count integer;
  v_participant_id uuid;
begin
  if p_request_id is null or char_length(btrim(p_request_id)) < 12 or char_length(p_request_id) > 100 then
    raise exception 'INVALID_REQUEST_ID';
  end if;

  select * into v_existing
  from public.bookings
  where request_id = p_request_id;

  if found then
    if v_existing.member_id <> p_member_id then
      raise exception 'REQUEST_ID_CONFLICT';
    end if;
    return v_existing;
  end if;

  select * into v_member
  from public.members
  where id = p_member_id;

  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;
  if coalesce(v_member.membership_status, '') <> 'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if coalesce(v_member.status, '') <> 'active' then raise exception 'MEMBER_DISABLED'; end if;

  select * into v_settings
  from public.booking_settings
  where id = 1
  for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  if v_settings.primary_technician_id is null
     or not exists (
       select 1
       from public.booking_technicians
       where id = v_settings.primary_technician_id
         and is_active = true
     ) then
    raise exception 'BOOKING_PRIMARY_TECHNICIAN_REQUIRED';
  end if;

  if jsonb_typeof(p_items) <> 'array' then raise exception 'INVALID_BOOKING_ITEMS'; end if;
  v_item_count := jsonb_array_length(p_items);
  if v_item_count < 1 or v_item_count > 20 then raise exception 'INVALID_BOOKING_ITEMS'; end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    begin
      v_service_id := (v_item ->> 'serviceId')::uuid;
      v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);
    exception when others then
      raise exception 'INVALID_BOOKING_ITEMS';
    end;

    if v_quantity < 1 or v_quantity > 2 then raise exception 'INVALID_BOOKING_QUANTITY'; end if;
    if v_service_id = any(v_seen_service_ids) then raise exception 'DUPLICATE_BOOKING_SERVICE'; end if;
    v_seen_service_ids := array_append(v_seen_service_ids, v_service_id);

    select * into v_service
    from public.booking_services
    where id = v_service_id
    for share;
    if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
    if not v_service.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;

    if v_primary_service_id is null then v_primary_service_id := v_service_id; end if;
    v_total_duration := v_total_duration + (v_service.duration_minutes * v_quantity);
  end loop;

  if v_total_duration < 1 or v_total_duration > 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;
  if p_booking_date < public.booking_business_date(clock_timestamp() at time zone 'Asia/Taipei',v_settings.work_start_time,v_settings.work_end_time) + coalesce(v_settings.min_advance_days,0) then raise exception 'BOOKING_TOO_EARLY'; end if;
  if public.booking_slot_start_at(p_booking_date,p_start_time,v_settings.work_start_time,v_settings.work_end_time) <= (clock_timestamp() at time zone 'Asia/Taipei') then raise exception 'BOOKING_TIME_PASSED'; end if;
  if extract(second from p_start_time) <> 0 then raise exception 'INVALID_BOOKING_SLOT'; end if;

  v_end_time := p_start_time + make_interval(mins => v_total_duration);
  if not public.booking_slot_fits(p_booking_date,p_start_time,v_total_duration,v_settings.work_start_time,v_settings.work_end_time,v_settings.slot_interval_minutes) then
    raise exception 'INVALID_BOOKING_SLOT';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_booking_date::text, 0));

  begin
    insert into public.bookings(
      request_id, service_id, member_id, booking_date, start_time, end_time,
      total_duration_minutes, status, member_note, technician_id
    ) values (
      btrim(p_request_id), v_primary_service_id, p_member_id, p_booking_date,
      p_start_time, v_end_time, v_total_duration, 'pending',
      left(coalesce(p_member_note, ''), 500),
      v_settings.primary_technician_id
    )
    returning * into v_booking;
  exception
    when exclusion_violation or unique_violation then
      raise exception 'BOOKING_SLOT_TAKEN';
  end;

  insert into public.booking_participants(
    booking_id, position, technician_id
  ) values (
    v_booking.id, 1, v_settings.primary_technician_id
  )
  returning id into v_participant_id;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_service_id := (v_item ->> 'serviceId')::uuid;
    v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);

    select * into v_service
    from public.booking_services
    where id = v_service_id;

    insert into public.booking_items(
      booking_id, service_id, service_title,
      unit_duration_minutes, unit_price_amount, quantity,
      service_type, counts_toward_membership
    ) values (
      v_booking.id, v_service.id, v_service.title,
      v_service.duration_minutes, v_service.price_amount, v_quantity,
      v_service.service_type, v_service.counts_toward_membership
    );

    insert into public.booking_participant_items(
      participant_id, service_id, service_title,
      unit_duration_minutes, unit_price_amount, quantity
    ) values (
      v_participant_id, v_service.id, v_service.title,
      v_service.duration_minutes, v_service.price_amount, v_quantity
    );
  end loop;

  insert into public.booking_participant_reservations(
    participant_id, booking_id, technician_id,
    booking_date, start_time, end_time, is_active
  ) values (
    v_participant_id, v_booking.id, v_settings.primary_technician_id,
    v_booking.booking_date, v_booking.start_time, v_booking.end_time, true
  );

  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_booking_bundle_with_benefits_request(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_member_note text, p_benefits jsonb DEFAULT '[]'::jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
begin
  select * into v_booking
  from public.create_booking_bundle_request(
    p_request_id,p_member_id,p_booking_date,p_start_time,p_items,p_member_note
  );
  perform public.replace_booking_benefit_selections_request(v_booking.id,p_member_id,p_benefits);
  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_booking_bundle_with_contact(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT ''::text, p_contact_salutation text DEFAULT ''::text, p_contact_phone text DEFAULT ''::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_member public.members%rowtype;
  v_booking public.bookings%rowtype;
  v_source text := lower(btrim(coalesce(p_contact_source, '')));
  v_surname text;
  v_salutation text;
  v_phone text;
begin
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;

  if v_source = 'member' then
    v_surname := btrim(coalesce(v_member.surname, ''));
    v_salutation := lower(btrim(coalesce(v_member.salutation, '')));
    v_phone := regexp_replace(btrim(coalesce(v_member.phone, '')), '[()[:space:]-]', '', 'g');
  elsif v_source = 'custom' then
    v_surname := btrim(coalesce(p_contact_surname, ''));
    v_salutation := lower(btrim(coalesce(p_contact_salutation, '')));
    v_phone := regexp_replace(btrim(coalesce(p_contact_phone, '')), '[()[:space:]-]', '', 'g');
  else
    raise exception 'INVALID_BOOKING_CONTACT_SOURCE';
  end if;

  if char_length(v_surname) < 1 or char_length(v_surname) > 40 then raise exception 'INVALID_BOOKING_CONTACT_SURNAME'; end if;
  if v_salutation not in ('mr','ms') then raise exception 'INVALID_BOOKING_CONTACT_SALUTATION'; end if;
  if v_phone !~ '^\+?[0-9]{8,15}$' then raise exception 'INVALID_BOOKING_CONTACT_PHONE'; end if;

  v_booking := public.create_booking_bundle_request(
    p_request_id, p_member_id, p_booking_date, p_start_time, p_items, p_member_note
  );

  if v_booking.contact_surname is not null or v_booking.contact_salutation is not null or v_booking.contact_phone is not null then
    if v_booking.contact_source <> v_source
       or coalesce(v_booking.contact_surname, '') <> v_surname
       or coalesce(v_booking.contact_salutation, '') <> v_salutation
       or coalesce(v_booking.contact_phone, '') <> v_phone then
      raise exception 'REQUEST_ID_CONFLICT';
    end if;
    return v_booking;
  end if;

  update public.bookings
  set contact_source = v_source,
      contact_surname = v_surname,
      contact_salutation = v_salutation,
      contact_phone = v_phone
  where id = v_booking.id
  returning * into v_booking;

  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_friend_booking_request(p_actor text, p_friend_code text, p_request_id text, p_booking_date date, p_start_time time without time zone, p_participants jsonb, p_member_note text, p_contact_source text, p_contact_surname text, p_contact_salutation text, p_contact_phone text, p_benefits jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m public.members%rowtype; f public.members%rowtype; b public.bookings%rowtype;
 v_key text:='friend-booking-create:'||p_actor||':'||p_request_id;
 v_hash text:=encode(extensions.digest(jsonb_build_array(p_friend_code,p_booking_date,p_start_time,p_participants,p_member_note,p_contact_source,p_contact_surname,p_contact_salutation,p_contact_phone,p_benefits)::text,'sha256'),'hex');
 previous public.idempotency_results%rowtype;
begin
 select * into m from public.members where line_user_id=p_actor and status='active' and membership_status='active';
 if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;
 select * into f from public.members where upper(member_code)=upper(btrim(p_friend_code)) and status='active' and membership_status='active' and is_test_account=m.is_test_account;
 if not found or f.id=m.id then raise exception 'FRIEND_NOT_FOUND'; end if;
 if jsonb_typeof(p_participants) is distinct from 'array' or jsonb_array_length(p_participants)<>1 then raise exception 'FRIEND_SINGLE_RECIPIENT_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('friend:'||least(m.id,f.id)::text||':'||greatest(m.id,f.id)::text,0));
 if not exists(select 1 from public.member_friendships where member_a=least(m.id,f.id) and member_b=greatest(m.id,f.id) and status='accepted') then raise exception 'FRIEND_ACCEPTED_REQUIRED'; end if;
 select * into b from public.bookings where request_id=p_request_id for update;
 if found and (b.member_id<>m.id or b.service_recipient_member_id is distinct from f.id) then raise exception 'REQUEST_ID_CONFLICT'; end if;
 perform 1 from public.members where id in(m.id,f.id) order by id for update;
 select * into previous from public.idempotency_results where request_key=v_key;
 if found then
  if previous.request_hash<>v_hash then raise exception 'REQUEST_ID_CONFLICT'; end if;
  return b;
 end if;
 b:=public.create_group_booking_with_benefits_request_v2(p_request_id,m.id,p_booking_date,p_start_time,p_participants,p_member_note,p_contact_source,p_contact_surname,p_contact_salutation,p_contact_phone,p_benefits);
 update public.bookings set service_recipient_member_id=f.id where id=b.id returning * into b;
 insert into public.idempotency_results(request_key,action,actor_line_user_id,request_hash,result) values(v_key,'friend.booking.create',p_actor,v_hash,jsonb_build_object('bookingId',b.id));
 return b;
end $function$

CREATE OR REPLACE FUNCTION public.create_group_booking_request(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_technician_id uuid, p_participants jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT NULL::text, p_contact_salutation text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_settings public.booking_settings%rowtype;
  v_member public.members%rowtype;
  v_existing public.bookings%rowtype;
  v_booking public.bookings%rowtype;
  v_technician public.booking_technicians%rowtype;
  v_service public.booking_services%rowtype;
  v_store public.booking_services%rowtype;
  v_participant jsonb;
  v_item jsonb;
  v_participant_id uuid;
  v_service_id uuid;
  v_primary_service_id uuid;
  v_seen uuid[];
  v_quantity integer;
  v_party_size integer;
  v_position integer := 0;
  v_total_duration integer := 0;
  v_participant_duration integer := 0;
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_local_time time := (now() at time zone 'Asia/Taipei')::time;
  v_end_time time;
begin
  if p_request_id is null or char_length(btrim(p_request_id)) < 12 or char_length(p_request_id) > 100 then raise exception 'INVALID_REQUEST_ID'; end if;
  select * into v_existing from public.bookings where request_id = p_request_id;
  if found then
    if v_existing.member_id <> p_member_id then raise exception 'REQUEST_ID_CONFLICT'; end if;
    return v_existing;
  end if;

  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;
  if coalesce(v_member.membership_status,'') <> 'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if coalesce(v_member.status,'') <> 'active' then raise exception 'MEMBER_DISABLED'; end if;

  select * into v_settings from public.booking_settings where id = 1 for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
  v_party_size := jsonb_array_length(p_participants);
  if v_party_size < 1 or v_party_size > v_settings.max_party_size then raise exception 'INVALID_PARTY_SIZE'; end if;

  if p_technician_id is null and v_settings.require_primary_technician then raise exception 'BOOKING_PRIMARY_TECHNICIAN_REQUIRED'; end if;
  if p_technician_id is not null then
  select * into v_technician from public.booking_technicians where id = p_technician_id for share;
  if not found then raise exception 'BOOKING_TECHNICIAN_NOT_FOUND'; end if;
  if not v_technician.is_active then raise exception 'BOOKING_TECHNICIAN_DISABLED'; end if;
  end if;

  for v_participant in select value from jsonb_array_elements(p_participants) loop
    v_position := v_position + 1;
    v_participant_duration := 0;
    if jsonb_typeof(v_participant->'items') <> 'array' or jsonb_array_length(v_participant->'items') < 1 or jsonb_array_length(v_participant->'items') > 20 then
      raise exception 'INVALID_BOOKING_ITEMS';
    end if;
    v_seen := array[]::uuid[];
    for v_item in select value from jsonb_array_elements(v_participant->'items') loop
      begin
        v_service_id := (v_item->>'serviceId')::uuid;
        v_quantity := coalesce((v_item->>'quantity')::integer,1);
      exception when others then raise exception 'INVALID_BOOKING_ITEMS'; end;
      if v_service_id = '00000000-0000-4000-8000-000000000010' then raise exception 'INVALID_BOOKING_ITEMS'; end if;
      if v_quantity < 1 or v_quantity > 2 then raise exception 'INVALID_BOOKING_QUANTITY'; end if;
      if v_service_id = any(v_seen) then raise exception 'DUPLICATE_BOOKING_SERVICE'; end if;
      v_seen := array_append(v_seen, v_service_id);
      select * into v_service from public.booking_services where id = v_service_id for share;
      if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
      if not v_service.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;
      if v_primary_service_id is null then v_primary_service_id := v_service_id; end if;
      v_participant_duration := v_participant_duration + (v_service.duration_minutes * v_quantity);
    end loop;
    v_total_duration := greatest(v_total_duration, v_participant_duration);
  end loop;

  select * into v_store from public.booking_services where id = '00000000-0000-4000-8000-000000000010' for share;
  if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
  if not v_store.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;
  v_total_duration := v_total_duration + v_store.duration_minutes;

  if v_total_duration < 1 or v_total_duration > 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;
  if p_booking_date < public.booking_business_date(clock_timestamp() at time zone 'Asia/Taipei',v_settings.work_start_time,v_settings.work_end_time) + coalesce(v_settings.min_advance_days,0) then raise exception 'BOOKING_TOO_EARLY'; end if;
  if public.booking_slot_start_at(p_booking_date,p_start_time,v_settings.work_start_time,v_settings.work_end_time) <= (clock_timestamp() at time zone 'Asia/Taipei') then raise exception 'BOOKING_TIME_PASSED'; end if;
  if extract(second from p_start_time) <> 0 then raise exception 'INVALID_BOOKING_SLOT'; end if;
  v_end_time := p_start_time + make_interval(mins => v_total_duration);
  if not public.booking_slot_fits(p_booking_date,p_start_time,v_total_duration,v_settings.work_start_time,v_settings.work_end_time,v_settings.slot_interval_minutes) then raise exception 'INVALID_BOOKING_SLOT'; end if;

  if p_contact_source not in ('member','custom') then raise exception 'INVALID_BOOKING_CONTACT'; end if;
  if p_contact_source = 'custom' and (nullif(btrim(coalesce(p_contact_surname,'')),'') is null or p_contact_salutation not in ('mr','ms') or nullif(btrim(coalesce(p_contact_phone,'')),'') is null) then
    raise exception 'INVALID_BOOKING_CONTACT';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_booking_date::text || ':' || coalesce(p_technician_id::text,'onsite'),0));
  begin
    insert into public.bookings(
      request_id, service_id, member_id, booking_date, start_time, end_time, total_duration_minutes,
      status, member_note, technician_id, party_size, contact_source, contact_surname, contact_salutation, contact_phone
    ) values (
      btrim(p_request_id), v_primary_service_id, p_member_id, p_booking_date, p_start_time, v_end_time, v_total_duration,
      'pending', left(coalesce(p_member_note,''),500), p_technician_id, v_party_size, p_contact_source,
      case when p_contact_source='custom' then left(btrim(p_contact_surname),40) else null end,
      case when p_contact_source='custom' then p_contact_salutation else null end,
      case when p_contact_source='custom' then left(btrim(p_contact_phone),20) else null end
    ) returning * into v_booking;
  exception when exclusion_violation or unique_violation then raise exception 'BOOKING_SLOT_TAKEN'; end;

  v_position := 0;
  for v_participant in select value from jsonb_array_elements(p_participants) loop
    v_position := v_position + 1;
    insert into public.booking_participants(booking_id, position) values (v_booking.id, v_position) returning id into v_participant_id;
    for v_item in select value from jsonb_array_elements(v_participant->'items') loop
      v_service_id := (v_item->>'serviceId')::uuid;
      v_quantity := coalesce((v_item->>'quantity')::integer,1);
      select * into v_service from public.booking_services where id = v_service_id;
      insert into public.booking_participant_items(participant_id, service_id, service_title, unit_duration_minutes, unit_price_amount, quantity)
      values (v_participant_id, v_service.id, v_service.title, v_service.duration_minutes, v_service.price_amount, v_quantity);
      insert into public.booking_items(booking_id, service_id, service_title, unit_duration_minutes, unit_price_amount, quantity, service_type, counts_toward_membership)
      values (v_booking.id, v_service.id, v_service.title, v_service.duration_minutes, v_service.price_amount, v_quantity, v_service.service_type, v_service.counts_toward_membership)
      on conflict (booking_id, service_id) do update set quantity = public.booking_items.quantity + excluded.quantity;
    end loop;
  end loop;

  insert into public.booking_items(booking_id, service_id, service_title, unit_duration_minutes, unit_price_amount, quantity, service_type, counts_toward_membership)
  values (v_booking.id, v_store.id, v_store.title, v_store.duration_minutes, v_store.price_amount, 1, v_store.service_type, v_store.counts_toward_membership)
  on conflict (booking_id, service_id) do update set quantity = excluded.quantity;

  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_group_booking_request_v2(p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_participants jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT NULL::text, p_contact_salutation text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_primary_technician_id uuid;
  v_booking public.bookings%rowtype;
  v_participant jsonb;
  v_position integer;
  v_participant_id uuid;
  v_technician_id uuid;
  v_duration integer;
begin
  v_primary_technician_id := public.validate_group_booking_technicians(p_participants);

  v_booking := public.create_group_booking_request(
    p_request_id,
    p_member_id,
    p_booking_date,
    p_start_time,
    v_primary_technician_id,
    p_participants,
    p_member_note,
    p_contact_source,
    p_contact_surname,
    p_contact_salutation,
    p_contact_phone
  );

  for v_participant, v_position in
    select value, ordinality::integer
    from jsonb_array_elements(p_participants) with ordinality
  loop
    select id into v_participant_id
    from public.booking_participants
    where booking_id = v_booking.id and position = v_position;
    if not found then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;

    v_technician_id := null;
    if nullif(btrim(coalesce(v_participant->>'technicianId','')), '') is not null then
      v_technician_id := (v_participant->>'technicianId')::uuid;
    end if;

    update public.booking_participants
    set technician_id = v_technician_id
    where id = v_participant_id;

    delete from public.booking_participant_reservations where participant_id = v_participant_id;
    if v_technician_id is not null then
      select coalesce(sum(unit_duration_minutes * quantity), 0)::integer
      into v_duration
      from public.booking_participant_items
      where participant_id = v_participant_id;

      if v_duration < 1 then raise exception 'INVALID_BOOKING_DURATION'; end if;

      insert into public.booking_participant_reservations(
        participant_id, booking_id, technician_id, booking_date, start_time, end_time, is_active
      ) values (
        v_participant_id,
        v_booking.id,
        v_technician_id,
        v_booking.booking_date,
        v_booking.start_time,
        v_booking.start_time + make_interval(mins => v_duration),
        v_booking.status in ('pending','confirmed')
      );
    end if;
  end loop;

  return v_booking;
exception
  when exclusion_violation then
    raise exception 'BOOKING_SLOT_TAKEN';
end;
$function$

