CREATE OR REPLACE FUNCTION public.delete_point_card(p_actor_line_user_id text, p_card_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_card uuid;
  v_ticket_count integer := 0;
  v_entry_count integer := 0;
begin
  select id into v_card from public.point_cards where card_id=p_card_id for update;
  if not found then raise exception 'POINT_CARD_NOT_FOUND'; end if;

  select count(*)::integer into v_ticket_count from public.point_tickets where point_card_id=v_card;
  select count(*)::integer into v_entry_count from public.point_entries where point_card_id=v_card;

  delete from public.point_tickets where point_card_id=v_card;
  delete from public.point_entries where point_card_id=v_card;
  delete from public.point_balances where point_card_id=v_card;
  delete from public.point_card_rewards where point_card_id=v_card;
  delete from public.point_cards where id=v_card;

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  ) values (
    public.new_public_id('AUD'),p_actor_line_user_id,'admin','admin.pointcards.delete',
    'point_card',p_card_id,'success',
    jsonb_build_object('deletedTicketCount',v_ticket_count,'deletedEntryCount',v_entry_count)
  );

  return jsonb_build_object(
    'cardId',p_card_id,
    'deletedTicketCount',v_ticket_count,
    'deletedEntryCount',v_entry_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_point_ticket_template(p_actor_line_user_id text, p_ticket_template_id text, p_expected_updated_at text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_template public.ticket_templates%rowtype;
  v_expected timestamptz;
  v_issued_count bigint;
  v_reward_count bigint;
begin
  if nullif(btrim(p_actor_line_user_id), '') is null then
    raise exception 'ADMIN_REQUIRED';
  end if;

  if nullif(btrim(p_ticket_template_id), '') is null then
    raise exception 'TICKET_TEMPLATE_DELETE_NOT_FOUND';
  end if;

  begin
    v_expected := p_expected_updated_at::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    raise exception 'INVALID_TICKET_TEMPLATE_VERSION';
  end;
  if v_expected is null then
    raise exception 'INVALID_TICKET_TEMPLATE_VERSION';
  end if;

  select * into v_template
  from public.ticket_templates
  where ticket_template_id = p_ticket_template_id
  for update;
  if not found then
    raise exception 'TICKET_TEMPLATE_DELETE_NOT_FOUND';
  end if;
  if v_template.updated_at is distinct from v_expected then
    raise exception 'CONFLICT';
  end if;

  select count(*) into v_reward_count
  from public.point_card_rewards
  where ticket_template_id = v_template.id;
  if v_reward_count > 0 then
    raise exception 'TICKET_TEMPLATE_IN_USE';
  end if;

  select count(*) into v_issued_count
  from public.point_tickets
  where ticket_template_id = v_template.id;

  -- FK RESTRICT also protects against a concurrent reward attachment.
  begin
    delete from public.ticket_templates where id = v_template.id;
  exception when foreign_key_violation then
    raise exception 'TICKET_TEMPLATE_IN_USE';
  end;

  insert into public.audit_logs (
    audit_id, actor_line_user_id, actor_role, action,
    target_type, target_id, result, detail
  ) values (
    'AUD-' || gen_random_uuid()::text, p_actor_line_user_id, 'admin',
    'TICKET_TEMPLATE_DELETED', 'ticket_template', p_ticket_template_id,
    'success', jsonb_build_object(
      'title', v_template.title,
      'preservedTicketCount', v_issued_count
    )
  );

  return jsonb_build_object(
    'deleted', true,
    'ticketTemplateId', p_ticket_template_id,
    'preservedTicketCount', v_issued_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.dismiss_accessible_receipt_request(p_receipt_id text, p_expected_updated_at timestamp with time zone, p_actor text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.booking_receipts%rowtype;
begin
  perform 1 from public.admins where line_user_id=p_actor and role='admin' and status='active';
  if not found then raise exception 'ADMIN_REQUIRED'; end if;
  select * into r from public.booking_receipts where receipt_id=p_receipt_id;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  perform 1 from public.members where id=r.member_id for update;
  select * into r from public.booking_receipts where receipt_id=p_receipt_id for update;
  if r.status='failed' and r.failure_reason='admin-dismissed' then return true; end if;
  if r.submission_mode<>'accessible' or r.booking_id is not null or r.status<>'awaiting_review' then raise exception 'RECEIPT_NOT_PENDING'; end if;
  if p_expected_updated_at is null or r.updated_at<>p_expected_updated_at then raise exception 'BOOKING_CONFLICT'; end if;
  update public.booking_receipts set status='failed',failure_reason='admin-dismissed',updated_at=now() where id=r.id;
  insert into public.booking_receipt_cleanup_queue(object_path,reason) values(r.object_path,'admin-dismissed') on conflict(object_path) do nothing;
  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
  values(public.new_public_id('AUD'),p_actor,'admin','admin.booking.receipt.dismiss','receipt',p_receipt_id,'success','{}');
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_booking_addon_companion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking_id uuid := coalesce(new.booking_id, old.booking_id);
  v_has_addon boolean := false;
  v_has_regular boolean := false;
begin
  if v_booking_id is null
     or not exists (select 1 from public.bookings where id = v_booking_id)
     or exists (select 1 from public.booking_participants where booking_id = v_booking_id) then
    return null;
  end if;

  select
    coalesce(bool_or(s.requires_companion_service), false),
    coalesce(bool_or(not s.requires_companion_service), false)
  into v_has_addon, v_has_regular
  from public.booking_items i
  join public.booking_services s on s.id = i.service_id
  where i.booking_id = v_booking_id
    and i.service_id <> '00000000-0000-4000-8000-000000000010'::uuid;

  if v_has_addon and not v_has_regular then
    raise exception 'BOOKING_ADD_ON_REQUIRES_COMPANION';
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_booking_advance_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_settings public.booking_settings%rowtype;
  v_today date;
begin
  if new.receipt_submission_id is not null and exists (
    select 1 from public.booking_receipts r
    where r.receipt_id=new.receipt_submission_id and r.member_id=new.member_id
      and r.submission_mode='accessible' and r.status in ('awaiting_review','bound')
  ) then return new; end if;
  if tg_op = 'UPDATE' and new.booking_date is not distinct from old.booking_date then return new; end if;
  select * into v_settings from public.booking_settings where id = 1;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  v_today := public.booking_business_date(clock_timestamp() at time zone 'Asia/Taipei',
    v_settings.work_start_time,v_settings.work_end_time);
  if new.booking_date < v_today + coalesce(v_settings.min_advance_days,0) then raise exception 'BOOKING_TOO_EARLY'; end if;
  if coalesce(v_settings.max_advance_days,0) > 0
     and new.booking_date > v_today + v_settings.max_advance_days then raise exception 'BOOKING_TOO_FAR'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.enforce_booking_cancellation_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.status is distinct from 'cancelled' and new.status = 'cancelled' then
    if new.cancellation_decision = 'approved'
       and new.cancellation_requested_at is not null
       and new.cancellation_reviewed_at is not null
       and new.cancellation_reviewed_by is not null then
      return new;
    end if;

    if new.cancelled_by is not null and exists (
      select 1
      from public.admins a
      where a.line_user_id = new.cancelled_by
        and a.role = 'admin'
        and a.status = 'active'
    ) then
      return new;
    end if;

    raise exception 'BOOKING_CANCELLATION_APPROVAL_REQUIRED';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_booking_live_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.receipt_submission_id is not null and exists (
    select 1 from public.booking_receipts r
    where r.receipt_id=new.receipt_submission_id and r.member_id=new.member_id
      and r.submission_mode='accessible' and r.status in ('awaiting_review','bound')
  ) then return new; end if;
  if new.status in ('pending','confirmed') and
     (new.booking_date + new.start_time + (case when new.starts_next_day then interval '1 day' else interval '0 days' end))
       <= (clock_timestamp() at time zone 'Asia/Taipei') then
    raise exception 'BOOKING_TIME_PASSED';
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.enforce_booking_participant_addon_companion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_participant_id uuid := coalesce(new.participant_id, old.participant_id);
