CREATE OR REPLACE FUNCTION public.fail_booking_receipt_request(p_receipt_id text, p_member_id uuid, p_actor_line_user_id text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_receipt public.booking_receipts%rowtype;
begin
  select * into v_receipt
  from public.booking_receipts
  where receipt_id=p_receipt_id and member_id=p_member_id
  for update;
  if not found then return; end if;
  if v_receipt.status in ('awaiting_review','bound') then return; end if;

  update public.booking_receipts
  set status='failed',failure_reason=left(coalesce(p_reason,''),120),updated_at=now()
  where id=v_receipt.id;

  insert into public.booking_receipt_cleanup_queue(object_path,reason)
  values(v_receipt.object_path,left(coalesce(p_reason,'failed'),120))
  on conflict(object_path) do nothing;

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  ) values(
    public.new_public_id('AUD'),p_actor_line_user_id,'member','user.booking.receipt.submit',
    'booking',v_receipt.booking_id::text,'failure',
    jsonb_build_object('receiptId',v_receipt.receipt_id,'reason',left(coalesce(p_reason,''),120))
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_accessible_receipt_request(p_receipt_id text, p_member_id uuid, p_actor_line_user_id text, p_actual_mime_type text, p_actual_size_bytes integer, p_sha256_hex text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v public.booking_receipts%rowtype;
begin
  -- Same member lock order as prepare/register serializes replacement and settlement.
  perform 1 from public.members where id=p_member_id and line_user_id=p_actor_line_user_id
    and status='active' and membership_status='active' for update;
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  select * into v from public.booking_receipts where receipt_id=p_receipt_id for update;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  if v.member_id<>p_member_id or v.submission_mode<>'accessible' then raise exception 'RECEIPT_NOT_OWNED'; end if;
  if v.status in ('awaiting_review','bound') then
    return jsonb_build_object('receiptId',v.receipt_id,'bookingId',v.booking_id,'status',v.status,'alreadyApplied',true);
  end if;
  if v.status<>'pending_upload' or v.booking_id is not null then raise exception 'RECEIPT_NOT_PENDING'; end if;
  if lower(coalesce(p_actual_mime_type,''))<>v.declared_mime_type then raise exception 'RECEIPT_MIME_MISMATCH'; end if;
  if p_actual_size_bytes is null or p_actual_size_bytes<>v.declared_size_bytes then raise exception 'RECEIPT_SIZE_MISMATCH'; end if;
  if lower(coalesce(p_sha256_hex,'')) !~ '^[a-f0-9]{64}$' then raise exception 'RECEIPT_INVALID_HASH'; end if;
  with replaced as (
    update public.booking_receipts set status='failed',failure_reason='snapshot-replaced',updated_at=now()
    where member_id=p_member_id and submission_mode='accessible' and booking_id is null and status='awaiting_review'
    returning object_path
  ) insert into public.booking_receipt_cleanup_queue(object_path,reason)
    select object_path,'snapshot-replaced' from replaced on conflict(object_path) do nothing;
  update public.booking_receipts set status='awaiting_review',actual_mime_type=p_actual_mime_type,
    actual_size_bytes=p_actual_size_bytes,sha256_hex=lower(p_sha256_hex),updated_at=now() where id=v.id;
  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
  values(public.new_public_id('AUD'),p_actor_line_user_id,'member','user.booking.receipt.accessible.submit',
    'receipt',p_receipt_id,'success',jsonb_build_object('nextState','awaiting_review'));
  return jsonb_build_object('receiptId',p_receipt_id,'status','awaiting_review','alreadyApplied',false);
end $function$

CREATE OR REPLACE FUNCTION public.finalize_booking_receipt_request(p_receipt_id text, p_member_id uuid, p_actor_line_user_id text, p_expected_booking_updated_at timestamp with time zone, p_actual_mime_type text, p_actual_size_bytes integer, p_sha256_hex text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_receipt public.booking_receipts%rowtype;
  v_booking public.bookings%rowtype;
begin
  select * into v_receipt
  from public.booking_receipts
  where receipt_id=p_receipt_id;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  if v_receipt.member_id<>p_member_id then raise exception 'RECEIPT_NOT_OWNED'; end if;

  select * into v_booking
  from public.bookings
  where id=v_receipt.booking_id
  for update;
  if not found or v_booking.member_id<>p_member_id then raise exception 'BOOKING_NOT_OWNED'; end if;

  select * into v_receipt
  from public.booking_receipts
  where receipt_id=p_receipt_id
  for update;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
  if v_receipt.member_id<>p_member_id then raise exception 'RECEIPT_NOT_OWNED'; end if;

  if v_receipt.status='bound' then
    return jsonb_build_object(
      'receiptId',v_receipt.receipt_id,
      'bookingId',v_booking.id,
      'status','bound',
      'alreadyApplied',true
    );
  end if;

  if v_receipt.status='awaiting_review' then
    return jsonb_build_object(
      'receiptId',v_receipt.receipt_id,
      'bookingId',v_booking.id,
      'status','awaiting_review',
      'alreadyApplied',true
    );
  end if;

  if v_receipt.status<>'pending_upload' then raise exception 'RECEIPT_NOT_PENDING'; end if;
  if v_booking.status<>'confirmed' then raise exception 'INVALID_BOOKING_TRANSITION'; end if;
  if v_booking.cancellation_requested_at is not null and v_booking.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;
  if p_expected_booking_updated_at is null or v_booking.updated_at<>p_expected_booking_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;

  if lower(coalesce(p_actual_mime_type,''))<>v_receipt.declared_mime_type then raise exception 'RECEIPT_MIME_MISMATCH'; end if;
  if p_actual_size_bytes is null or p_actual_size_bytes<1 or p_actual_size_bytes>5242880 then raise exception 'RECEIPT_FILE_TOO_LARGE'; end if;
  if p_actual_size_bytes<>v_receipt.declared_size_bytes then raise exception 'RECEIPT_SIZE_MISMATCH'; end if;
  if lower(coalesce(p_sha256_hex,'')) !~ '^[a-f0-9]{64}$' then raise exception 'RECEIPT_INVALID_HASH'; end if;

  with replaced as (
    update public.booking_receipts
    set status='failed',failure_reason='snapshot-replaced',updated_at=now()
    where booking_id=v_booking.id and status='awaiting_review' and id<>v_receipt.id
    returning object_path
  )
  insert into public.booking_receipt_cleanup_queue(object_path,reason)
  select object_path,'snapshot-replaced' from replaced
  on conflict(object_path) do nothing;

  update public.booking_receipts
  set actual_mime_type=lower(p_actual_mime_type),
      actual_size_bytes=p_actual_size_bytes,
      sha256_hex=lower(p_sha256_hex),
      status='awaiting_review',
      failure_reason='',
      bound_at=null,
      updated_at=now()
  where id=v_receipt.id;

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  ) values(
    public.new_public_id('AUD'),p_actor_line_user_id,'member','user.booking.receipt.submit',
    'booking',v_booking.id::text,'success',
    jsonb_build_object(
      'receiptId',v_receipt.receipt_id,
      'objectPath',v_receipt.object_path,
      'mimeType',lower(p_actual_mime_type),
      'sizeBytes',p_actual_size_bytes,
      'sha256',lower(p_sha256_hex),
      'nextState','awaiting_review'
    )
  );

  return jsonb_build_object(
    'receiptId',v_receipt.receipt_id,
    'bookingId',v_booking.id,
    'status','awaiting_review',
    'alreadyApplied',false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_snapshot_receipt_v2(p_receipt_id text, p_member_id uuid, p_actor_line_user_id text, p_actual_mime_type text, p_actual_size_bytes integer, p_sha256_hex text, p_location jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.booking_receipts%rowtype; result jsonb;
begin
 select * into r from public.booking_receipts where receipt_id=p_receipt_id;
 if not found or r.member_id<>p_member_id then raise exception 'RECEIPT_NOT_OWNED'; end if;
 if r.status not in ('awaiting_review','bound') then
 perform public.validate_snapshot_ticket_selection(p_member_id,r.requested_booking_id,r.requested_benefits,r.receipt_id);
 end if;
 return public.finalize_snapshot_receipt_request(p_receipt_id,p_member_id,p_actor_line_user_id,p_actual_mime_type,p_actual_size_bytes,p_sha256_hex,p_location);
end $function$

CREATE OR REPLACE FUNCTION public.finish_member_removal(p_actor text, p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare j member_removal_jobs%rowtype; m members%rowtype; bids uuid[]; r record;
begin
 if not exists(select 1 from admins where line_user_id=p_actor and role='admin' and status='active') then raise exception 'ADMIN_REQUIRED'; end if;
 select * into j from member_removal_jobs where id=p_job_id;
 if not found then raise exception 'REMOVAL_JOB_NOT_FOUND'; end if;
 perform pg_advisory_xact_lock(hashtextextended('member-removal:'||j.identity_hash,0));
 select * into j from member_removal_jobs where id=p_job_id for update;
 if not found then raise exception 'REMOVAL_JOB_NOT_FOUND'; end if;
 if j.state='complete' then return jsonb_build_object('jobId',j.id,'state','complete','alreadyApplied',true); end if;
 select * into m from members where id=j.member_id for update;
 if not found then raise exception 'REMOVAL_MEMBER_MISSING'; end if;
 if exists(select 1 from storage.objects where (bucket_id='booking-receipts' and name like m.id::text||'/%') or (bucket_id='e2e-failure-artifacts' and name=any(j.artifact_paths))) then raise exception 'REMOVAL_STORAGE_PENDING'; end if;
 perform set_config('membership.removal_job',j.id::text,true);
 select coalesce(array_agg(id),'{}'::uuid[]) into bids from bookings where member_id=m.id or service_recipient_member_id=m.id;
 -- The surviving side retains its asset and transaction reference, not deleted PII.
 update point_transfers set sender_member_id=null,request_id='removed-'||id::text where sender_member_id=m.id;
 update point_transfers set receiver_member_id=null where receiver_member_id=m.id;
 delete from point_transfers where sender_member_id is null and receiver_member_id is null;
 update friend_booking_rewards set actor_member_id=null where actor_member_id=m.id;
 update friend_booking_rewards set recipient_member_id=null where recipient_member_id=m.id;
 delete from friend_booking_rewards where actor_member_id is null and recipient_member_id is null;
 update point_entries set created_by='removed-member',note='會員關聯已移除',request_id=null where member_id<>m.id and (created_by=m.line_user_id or reference_id in (select transfer_id from point_transfers where sender_member_id is null or receiver_member_id is null));
 update service_time_entries set created_by='removed-member',note='會員關聯已移除',request_id=null where member_id<>m.id and created_by=m.line_user_id;
 delete from booking_ticket_usage_requests where member_id=m.id;
 delete from booking_benefit_selections where member_id=m.id;
 delete from scheduled_grant_messages where member_id=m.id;
 delete from booking_receipts where member_id=m.id;
 delete from booking_receipt_cleanup_queue where object_path like m.id::text||'/%';
 delete from fixed_ticket_grants where member_id=m.id;
 delete from event_ticket_claims where member_id=m.id;
 delete from point_tickets where member_id=m.id;
 delete from point_entries where member_id=m.id;
 delete from point_balances where member_id=m.id;
 delete from service_time_entries where member_id=m.id;
 delete from service_grant_requests where member_id=m.id;
 delete from booking_completion_settlements where member_id=m.id;
 delete from member_referrals where inviter_member_id=m.id or invitee_member_id=m.id;
 delete from member_friendships where member_a=m.id or member_b=m.id or requested_by=m.id;
 delete from test_login_sessions where member_id=m.id;
 delete from member_presence_sessions where member_id=m.id;
 delete from membership_consents where member_id=m.id;
 delete from membership_terms where e2e_member_id=m.id;
 -- Single-owner bookings disappear. Shared bookings survive without the removed
 -- side. Pending bookings for a removed service recipient are cancelled to prevent
 -- awarding that recipient's service to the surviving booker.
 delete from bookings where (member_id=m.id and (service_recipient_member_id is null or service_recipient_member_id=m.id)) or (member_id is null and service_recipient_member_id=m.id);
 update bookings set status='cancelled',cancellation_requested_at=coalesce(cancellation_requested_at,clock_timestamp()),
   cancellation_requested_by=coalesce(cancellation_requested_by,p_actor),cancellation_source_status=coalesce(cancellation_source_status,status),cancellation_reviewed_at=clock_timestamp(),
   cancellation_reviewed_by=p_actor,cancellation_decision='approved',cancelled_at=clock_timestamp(),cancelled_by=p_actor
 where id=any(bids) and status in ('pending','confirmed') and (service_recipient_member_id=m.id or (cancellation_requested_at is not null and cancellation_reviewed_at is null));
 update bookings set
   member_note='',admin_note='',contact_source='custom',contact_surname=null,contact_salutation=null,contact_phone=null,
   member_id=case when member_id=m.id then null else member_id end,
   service_recipient_member_id=case when service_recipient_member_id=m.id then null else service_recipient_member_id end
 where id=any(bids);
 -- Remove identity-bearing diagnostic payloads and deduplication responses.
 delete from idempotency_results where actor_line_user_id=m.line_user_id or result::text like '%'||m.line_user_id||'%' or result::text like '%'||m.id::text||'%';
 delete from audit_logs where actor_line_user_id=m.line_user_id or target_id in (m.line_user_id,m.id::text,m.member_code) or detail::text like '%'||m.line_user_id||'%' or detail::text like '%'||m.id::text||'%' or detail::text like '%'||m.member_code||'%';
 delete from booking_audit_events where actor_line_user_id=m.line_user_id or target_id=m.id::text or target_id=any(bids::text[]) or metadata::text like '%'||m.line_user_id||'%' or metadata::text like '%'||m.id::text||'%';
 delete from idempotency_results i where exists(select 1 from unnest(bids) bid where i.result::text like '%'||bid::text||'%');
 delete from api_rate_limits where principal_hash=encode(extensions.digest(m.line_user_id,'sha256'),'hex');
 -- Clear actor fields wherever schema inspection found member identity text. The
 -- target cannot be an administrator, so these are user-originated references.
 for r in select table_name,column_name from information_schema.columns where table_schema='public' and data_type='text' and column_name in ('created_by','updated_by','completed_by','confirmed_by','rejected_by','cancelled_by','redeemed_by','cancellation_requested_by','cancellation_reviewed_by') loop
   execute format('update public.%I set %I=$1 where %I=$2',r.table_name,r.column_name,r.column_name) using 'removed-member',m.line_user_id;
 end loop;
 delete from automation_test_runs where id=any(j.run_ids);
 delete from members where id=m.id;
 -- A missed RESTRICT relation aborts the transaction instead of partial success.
 update member_removal_jobs set member_id=null,run_ids='{}',artifact_paths='{}',state='complete',completed_at=clock_timestamp() where id=j.id;
 insert into audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
 values(new_public_id('AUD'),p_actor,'admin','MEMBER_REMOVAL_COMPLETE','removal_job',j.id::text,'success',jsonb_build_object('state','complete'));
 insert into realtime_events(scope,event_type) values('all','member.removal.complete');
 return jsonb_build_object('jobId',j.id,'state','complete','alreadyApplied',false);
end; $function$

CREATE OR REPLACE FUNCTION public.fixed_schedule_date(p_year integer, p_month integer, p_day integer)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_first date;
  v_last_day integer;
begin
  v_first := make_date(p_year, p_month, 1);
  v_last_day := extract(day from (v_first + interval '1 month - 1 day'))::integer;
  return make_date(p_year, p_month, least(greatest(p_day, 1), v_last_day));
end;
$function$

CREATE OR REPLACE FUNCTION public.fixed_ticket_notification_delivery(p_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare q public.scheduled_grant_messages%rowtype; g public.fixed_ticket_grants%rowtype;
  t public.fixed_ticket_templates%rowtype; m public.members%rowtype; e public.event_tickets%rowtype;
  today date := (now() at time zone 'Asia/Taipei')::date;
begin
  select * into q from public.scheduled_grant_messages where id=p_message_id;
  if not found then return jsonb_build_object('action','cancel','reason','NOTIFICATION_NOT_FOUND'); end if;
  if q.request_id not like 'FIXED-%' then return jsonb_build_object('action','send'); end if;
  select * into g from public.fixed_ticket_grants where id=q.fixed_ticket_grant_id;
  if not found or g.status <> 'issued' then return jsonb_build_object('action','cancel','reason','FIXED_GRANT_UNAVAILABLE'); end if;
  select * into t from public.fixed_ticket_templates where id=g.fixed_ticket_template_id;
  if not found or not t.notify_line or t.status <> 'active' or t.deleted_at is not null then
    return jsonb_build_object('action','cancel','reason','FIXED_NOTIFICATION_DISABLED');
  end if;
  select * into m from public.members where id=q.member_id;
  if not found or m.id <> g.member_id or m.line_user_id <> q.line_user_id or m.status <> 'active'
    or m.membership_status <> 'active' or m.is_test_account or not (public.current_tier_key(m.id)=any(t.allowed_tier_keys)) then
    return jsonb_build_object('action','cancel','reason','FIXED_MEMBER_INELIGIBLE');
  end if;
  select * into e from public.event_tickets where id=g.event_ticket_id;
  if not found or e.status <> 'active' or e.deleted_at is not null or e.starts_on > today or e.ends_on < today
    or not (public.current_tier_key(m.id)=any(e.allowed_tier_keys))
    or not exists(select 1 from public.event_ticket_claims c where c.claim_id=g.claim_id and c.member_id=m.id and c.event_ticket_id=e.id and c.status='claimed') then
    return jsonb_build_object('action','cancel','reason','FIXED_TICKET_UNAVAILABLE');
  end if;
  if q.status <> 'sending' then return jsonb_build_object('action','skip','reason','FIXED_NOTIFICATION_CHANGED'); end if;
  if q.scheduled_for > now() then return jsonb_build_object('action','defer','scheduledFor',q.scheduled_for); end if;
  return jsonb_build_object('action','send');
end; $function$

CREATE OR REPLACE FUNCTION public.grant_member_benefits(p_actor_line_user_id text, p_member_line_user_id text, p_request_id text, p_points jsonb, p_service_minutes integer, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member public.members%rowtype;
  v_item jsonb;
  v_card public.point_cards%rowtype;
  v_amount integer;
  v_now timestamptz := now();
  v_rows integer := 0;
  v_point_grant_count integer := 0;
  v_service_grant_applied boolean := false;
begin
  if length(coalesce(p_request_id,'')) < 16 or length(p_request_id) > 100 then
    raise exception 'INVALID_REQUEST_ID';
  end if;

  if p_points is not null and jsonb_typeof(p_points) <> 'array' then
    raise exception 'INVALID_POINT_AMOUNT';
  end if;

  if p_service_minutes is not null
     and (p_service_minutes < 1 or p_service_minutes > 1440) then
    raise exception 'INVALID_SERVICE_MINUTES';
  end if;

  if coalesce(jsonb_array_length(p_points),0) = 0
     and p_service_minutes is null then
    raise exception 'EMPTY_GRANT';
  end if;

  select * into v_member
  from public.members
  where line_user_id=p_member_line_user_id
  for update;

  if not found then
    raise exception 'MEMBER_NOT_FOUND';
  end if;

  if p_points is not null then
    for v_item in select value from jsonb_array_elements(p_points)
    loop
      begin
        v_amount := (v_item->>'amount')::integer;
      exception when others then
        raise exception 'INVALID_POINT_AMOUNT';
      end;
      if v_amount < 1 or v_amount > 100 then
        raise exception 'INVALID_POINT_AMOUNT';
      end if;

      if nullif(btrim(v_item->>'cardId'),'') is null then
        raise exception 'INVALID_POINT_AMOUNT';
      end if;

      select * into v_card
      from public.point_cards
      where card_id=v_item->>'cardId'
        and status='active'
        and (expiry_mode='unlimited' or expires_on >= (clock_timestamp() at time zone 'Asia/Taipei')::date)
      for update;

      if not found then
        raise exception 'POINT_CARD_NOT_AVAILABLE';
      end if;

      insert into public.point_entries(
        entry_id,member_id,point_card_id,amount,note,created_by,request_id,entry_type
      )
      values(
        public.new_public_id('PE'),v_member.id,v_card.id,v_amount,coalesce(p_note,''),
        p_actor_line_user_id,p_request_id,'grant'
      )
      on conflict(request_id,member_id,point_card_id)
      where request_id is not null and request_id <> ''
      do nothing;

      get diagnostics v_rows = row_count;

      if v_rows > 0 then
        v_point_grant_count := v_point_grant_count + 1;

        insert into public.point_balances(member_id,point_card_id,stamps,updated_at)
        values(v_member.id,v_card.id,v_amount,v_now)
        on conflict(member_id,point_card_id)
        do update
          set stamps=public.point_balances.stamps+excluded.stamps,
              updated_at=v_now;

        perform public.issue_eligible_point_tickets(v_member.id,v_card.id);
      end if;
    end loop;
  end if;

  if p_service_minutes is not null then
    insert into public.service_time_entries(
      entry_id,member_id,minutes,note,created_by,request_id
    )
    values(
      public.new_public_id('SE'),v_member.id,p_service_minutes,coalesce(p_note,''),
      p_actor_line_user_id,p_request_id
    )
    on conflict(request_id,member_id)
    where request_id is not null and request_id <> ''
    do nothing;

    get diagnostics v_rows = row_count;
    v_service_grant_applied := v_rows > 0;
  end if;

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  )
  values(
    public.new_public_id('AUD'),p_actor_line_user_id,'admin','admin.member-grants.add',
    'member',p_member_line_user_id,'success',
    jsonb_build_object(
      'requestId',p_request_id,
      'requestedPointCount',coalesce(jsonb_array_length(p_points),0),
      'appliedPointCount',v_point_grant_count,
      'requestedServiceMinutes',p_service_minutes,
      'serviceGrantApplied',v_service_grant_applied,
      'applied',(v_point_grant_count > 0 or v_service_grant_applied)
    )
  );

  return jsonb_build_object(
    'memberId',v_member.id,
    'lineUserId',v_member.line_user_id,
    'pointGrantCount',v_point_grant_count,
    'serviceGrantApplied',v_service_grant_applied,
    'applied',(v_point_grant_count > 0 or v_service_grant_applied)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_member_benefits_with_event_bonus(p_actor_line_user_id text, p_member_line_user_id text, p_request_id text, p_points jsonb, p_service_minutes integer, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member public.members%rowtype;
  v_item jsonb;
  v_card public.point_cards%rowtype;
  v_base_amount integer;
  v_effective_amount integer;
  v_now timestamptz := now();
  v_rows integer := 0;
  v_point_grant_count integer := 0;
  v_service_grant_applied boolean := false;
  v_current_minutes integer := 0;
  v_tier_key text := 'general';
  v_today date;
  v_bonus_total integer := 0;
  v_bonus_events jsonb := '[]'::jsonb;
  v_point_details jsonb := '[]'::jsonb;
  v_bonus_note text := '';
  v_point_count integer := 0;
  v_distinct_card_count integer := 0;
begin
  if length(coalesce(p_request_id,'')) < 16 or length(p_request_id) > 100 then
    raise exception 'INVALID_REQUEST_ID';
  end if;

  select * into v_member
  from public.members
  where line_user_id=p_member_line_user_id
  for update;

  if not found then
    raise exception 'MEMBER_NOT_FOUND';
  end if;

  v_today := (clock_timestamp() at time zone 'Asia/Taipei')::date;

  if p_points is not null then
    if jsonb_typeof(p_points) <> 'array' then
      raise exception 'INVALID_POINTS';
    end if;
    v_point_count := jsonb_array_length(p_points);
    if v_point_count > 20 then
      raise exception 'INVALID_POINTS';
    end if;
    select count(distinct value->>'cardId') into v_distinct_card_count
    from jsonb_array_elements(p_points);
    if v_point_count <> v_distinct_card_count then
      raise exception 'DUPLICATE_POINT_CARD';
    end if;
  end if;

  select coalesce(sum(minutes),0)::integer into v_current_minutes
  from public.service_time_entries
  where member_id=v_member.id;

  select coalesce(tier_key,'general') into v_tier_key
  from public.membership_tier_settings
  where required_service_minutes <= v_current_minutes
  order by required_service_minutes desc
  limit 1;

  v_tier_key := coalesce(v_tier_key,'general');

  select
    coalesce(sum(bonus_points),0)::integer,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'calendarItemId',calendar_item_id,
          'title',title,
          'bonusPoints',bonus_points
        ) order by starts_on, created_at
      ),
      '[]'::jsonb
    )
  into v_bonus_total, v_bonus_events
  from public.calendar_items
  where item_type='event'
    and status='active'
    and bonus_points_enabled=true
    and bonus_points > 0
    and starts_on <= v_today
    and coalesce(ends_on,starts_on) >= v_today
    and (
      coalesce(cardinality(allowed_tier_keys),0)=0
      or v_tier_key = any(allowed_tier_keys)
    );

  if v_bonus_total > 0 then
    select '活動加贈：' || string_agg(
      coalesce(value->>'title','活動') || ' +' || coalesce(value->>'bonusPoints','0') || ' 點',
      '、'
    )
    into v_bonus_note
    from jsonb_array_elements(v_bonus_events);
  end if;

  if p_points is not null and jsonb_typeof(p_points)='array' then
    for v_item in select value from jsonb_array_elements(p_points)
    loop
      begin
        v_base_amount := coalesce((v_item->>'amount')::integer,0);
      exception when others then
        raise exception 'INVALID_POINT_AMOUNT';
      end;

      if v_base_amount < 1 or v_base_amount > 100 then
        raise exception 'INVALID_POINT_AMOUNT';
      end if;

      select * into v_card
      from public.point_cards
      where card_id=v_item->>'cardId'
        and status='active'
        and (expiry_mode='unlimited' or expires_on >= v_today)
      for update;

      if not found then
        raise exception 'POINT_CARD_NOT_AVAILABLE';
      end if;

      v_effective_amount := v_base_amount + v_bonus_total;

      insert into public.point_entries(
        entry_id,member_id,point_card_id,amount,note,created_by,request_id,entry_type,reference_type,reference_id
      )
      values(
        public.new_public_id('PE'),v_member.id,v_card.id,v_effective_amount,
        trim(concat_ws('；',nullif(coalesce(p_note,''),''),nullif(v_bonus_note,''))),
        p_actor_line_user_id,p_request_id,'grant',
        case when v_bonus_total > 0 then 'calendar_bonus' else null end,
        case when v_bonus_total > 0 then 'multiple' else null end
      )
      on conflict(request_id,member_id,point_card_id)
      where request_id is not null and request_id <> ''
      do nothing;

      get diagnostics v_rows = row_count;

      v_point_details := v_point_details || jsonb_build_array(
        jsonb_build_object(
          'cardId',v_card.card_id,
          'cardTitle',v_card.title,
          'baseAmount',v_base_amount,
          'bonusAmount',v_bonus_total,
          'effectiveAmount',v_effective_amount,
          'applied',v_rows > 0
        )
      );

      if v_rows > 0 then
        v_point_grant_count := v_point_grant_count + 1;

        insert into public.point_balances(member_id,point_card_id,stamps,updated_at)
        values(v_member.id,v_card.id,v_effective_amount,v_now)
        on conflict(member_id,point_card_id)
        do update
          set stamps=public.point_balances.stamps+excluded.stamps,
              updated_at=v_now;

        perform public.issue_eligible_point_tickets(v_member.id,v_card.id);
      end if;
    end loop;
  end if;

  if coalesce(p_service_minutes,0) > 0 then
    if p_service_minutes < 1 or p_service_minutes > 1440 then
      raise exception 'INVALID_SERVICE_MINUTES';
    end if;

    insert into public.service_time_entries(
      entry_id,member_id,minutes,note,created_by,request_id
    )
    values(
      public.new_public_id('SE'),v_member.id,p_service_minutes,coalesce(p_note,''),
      p_actor_line_user_id,p_request_id
    )
    on conflict(request_id,member_id)
    where request_id is not null and request_id <> ''
    do nothing;

    get diagnostics v_rows = row_count;
    v_service_grant_applied := v_rows > 0;
  end if;

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  )
  values(
    public.new_public_id('AUD'),p_actor_line_user_id,'admin','admin.member-grants.add',
    'member',p_member_line_user_id,'success',
    jsonb_build_object(
      'requestId',p_request_id,
      'requestedPointCount',coalesce(jsonb_array_length(p_points),0),
      'appliedPointCount',v_point_grant_count,
      'requestedServiceMinutes',coalesce(p_service_minutes,0),
      'serviceGrantApplied',v_service_grant_applied,
      'memberTierBeforeGrant',v_tier_key,
      'calendarBonusTotalPerCard',v_bonus_total,
      'calendarBonusEvents',v_bonus_events,
      'pointDetails',v_point_details,
      'applied',(v_point_grant_count > 0 or v_service_grant_applied)
    )
  );

  return jsonb_build_object(
    'memberId',v_member.id,
    'lineUserId',v_member.line_user_id,
    'pointGrantCount',v_point_grant_count,
    'serviceGrantApplied',v_service_grant_applied,
    'memberTierBeforeGrant',v_tier_key,
    'bonusTotalPerCard',v_bonus_total,
    'bonusEvents',v_bonus_events,
    'pointDetails',v_point_details,
    'applied',(v_point_grant_count > 0 or v_service_grant_applied)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_service_member_benefits(p_actor text, p_member text, p_request text, p_items jsonb, p_expected_preview jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_member public.members%rowtype; v_previous public.service_grant_requests%rowtype;
  v_preview jsonb; v_result jsonb; v_points jsonb; v_note text;
begin
  if not exists(select 1 from public.admins where line_user_id=p_actor and role='admin' and status='active') then raise exception 'ADMIN_REQUIRED'; end if;
  if length(coalesce(p_request,''))<16 or length(p_request)>100 then raise exception 'INVALID_REQUEST_ID'; end if;
  perform pg_advisory_xact_lock(hashtextextended('service-grant:'||p_actor||':'||p_request,0));
  select * into v_previous from public.service_grant_requests where actor_line_user_id=p_actor and request_id=p_request;
  if found then
    if v_previous.items is distinct from p_items or not exists(select 1 from public.members where id=v_previous.member_id and line_user_id=p_member) then raise exception 'GRANT_REQUEST_CONFLICT'; end if;
    return v_previous.result || jsonb_build_object('applied',false,'alreadyApplied',true);
  end if;
  -- Hold configuration stable until all balance/ledger changes have committed.
  lock table public.booking_services,public.booking_service_types,public.booking_service_type_rewards,public.point_cards in share mode;
  select * into v_member from public.members where line_user_id=p_member for update;
  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;
  v_preview := public.preview_service_member_grant(p_actor,p_member,p_items);
  if p_expected_preview is distinct from v_preview then raise exception 'SERVICE_GRANT_PREVIEW_STALE'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('cardId',value->>'cardId','amount',(value->>'amount')::integer)),'[]') into v_points from jsonb_array_elements(v_preview->'points');
  select '依服務項目登記：'||string_agg(value->>'title'||' ×'||(value->>'quantity'),'、' order by value->>'serviceId') into v_note from jsonb_array_elements(v_preview->'items');
  v_result := public.grant_member_benefits(p_actor,p_member,'service:'||md5(p_actor||':'||p_request),v_points,nullif((v_preview->>'serviceMinutes')::integer,0),v_note);
  v_result := v_result || jsonb_build_object('preview',v_preview,'requestId',p_request);
  insert into public.service_grant_requests(actor_line_user_id,request_id,member_id,items,result) values(p_actor,p_request,v_member.id,p_items,v_result);
  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
    values(public.new_public_id('AUD'),p_actor,'admin','admin.service-grants.add','member',p_member,'success',jsonb_build_object('requestId',p_request,'preview',v_preview));
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_deleted_booking_service()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.deleted_at is not null then
    new.deleted_at := old.deleted_at;
    new.deleted_by := old.deleted_by;
    new.is_active := false;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_general_event_ticket_cross_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.benefit_kind='event' and new.status='pending' then
    -- A shared row lock serializes the general and snapshot entrypoints.
    perform 1 from public.event_ticket_claims c
      where c.member_id=new.member_id and c.claim_id=new.benefit_ref
      for update;
    if not found then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;

    if exists (
      select 1 from public.booking_receipts r
      where r.member_id=new.member_id
        and r.submission_mode='accessible'
        and r.status in ('pending_upload','awaiting_review')
        -- Admin snapshot settlement transfers its OWN receipt selection into
        -- the generated booking before the receipt transitions to bound.
        and r.receipt_id is distinct from nullif(current_setting('app.snapshot_receipt_id',true),'')
        and r.requested_benefits @> jsonb_build_array(
          jsonb_build_object('kind','event','id',new.benefit_ref)
        )
    ) then raise exception 'EVENT_TICKET_ALREADY_REGISTERED'; end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_snapshot_event_ticket_cross_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_claim_id text;
begin
  if new.submission_mode <> 'accessible'
     or new.status not in ('pending_upload','awaiting_review') then
    return new;
  end if;
  if jsonb_typeof(coalesce(new.requested_benefits,'[]'::jsonb)) <> 'array'
    then raise exception 'INVALID_BOOKING_BENEFITS'; end if;
  if exists (
    select 1 from jsonb_array_elements(coalesce(new.requested_benefits,'[]'::jsonb)) AS item(value)
    where item.value->>'kind'='event'
    group by item.value->>'id' having count(*) > 1
  ) then raise exception 'INVALID_BOOKING_BENEFITS'; end if;

  for v_claim_id in
    select distinct item.value->>'id' as ref
    from jsonb_array_elements(coalesce(new.requested_benefits,'[]'::jsonb)) AS item(value)
    where item.value->>'kind'='event'
    order by ref
  loop
    -- Lock before reading either reservation surface (no check/write race).
    perform 1 from public.event_ticket_claims c
      where c.member_id=new.member_id and c.claim_id=v_claim_id for update;
    if not found then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;

    if exists (
      select 1 from public.booking_benefit_selections s
      where s.member_id=new.member_id and s.benefit_kind='event'
        and s.benefit_ref=v_claim_id and s.status='pending'
    ) or exists (
      select 1 from public.booking_receipts r
      where r.member_id=new.member_id and r.id<>new.id
        and r.submission_mode='accessible'
        and r.status in ('pending_upload','awaiting_review')
        and r.requested_benefits @> jsonb_build_array(
          jsonb_build_object('kind','event','id',v_claim_id)
        )
    ) then raise exception 'EVENT_TICKET_ALREADY_REGISTERED'; end if;
  end loop;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.has_current_membership_terms_consent(p_member_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_member public.members%rowtype; v_terms public.membership_terms%rowtype; v_scope text := 'production';
begin
  select * into v_member from public.members where id=p_member_id;
  if not found then return true; end if;
  if v_member.is_test_account is true and exists(
    select 1 from public.membership_terms
     where scope='e2e' and e2e_member_id=v_member.id and status='active'
       and required and effective_at<=now()
  ) then v_scope := 'e2e'; end if;
  select * into v_terms from public.membership_terms
   where scope=v_scope and status='active'
     and (v_scope='production' or e2e_member_id=v_member.id)
     and required and effective_at<=now();
  if not found then return true; end if;
  if not v_terms.reconsent_existing then return true; end if;
  if v_member.is_test_account is not true
     and coalesce(v_member.joined_at,v_member.created_at) >= v_terms.activated_at then return true; end if;
  return exists(select 1 from public.membership_consents c where c.member_id=v_member.id and c.terms_id=v_terms.id);
end
$function$

CREATE OR REPLACE FUNCTION public.issue_eligible_point_tickets(p_member_id uuid, p_point_card_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_balance integer := 0;
  v_reward record;
  v_count integer := 0;
  v_existing integer := 0;
  v_allowed integer := 0;
begin
  -- Serialize competing grants and redemptions for this balance.
  select greatest(stamps,0) into v_balance
  from public.point_balances
  where member_id=p_member_id and point_card_id=p_point_card_id
  for update;
  if not found then return 0; end if;

  for v_reward in
    select r.id,r.threshold_stamps,t.id as template_id,t.ticket_type,t.title,
           t.description,t.usage_method,t.usage_instructions,t.prizes
    from public.point_card_rewards r
    join public.ticket_templates t on t.id=r.ticket_template_id
    where r.point_card_id=p_point_card_id
      and t.status='active'
      and r.threshold_stamps > 0
      and r.threshold_stamps <= v_balance
    order by r.threshold_stamps,r.id
  loop
    -- 20 is the existing booking selection payload limit. It also prevents
    -- unbounded ticket creation when a member has a very large balance.
    v_allowed := least(20, v_balance / v_reward.threshold_stamps);
    select count(*) into v_existing
    from public.point_tickets pt
    where pt.member_id=p_member_id
      and pt.point_card_id=p_point_card_id
      and pt.status='available'
      and pt.snapshot_reservation_copy_of is null
      and (pt.reward_id=v_reward.id or
        (pt.ticket_template_id=v_reward.template_id
          and pt.threshold_stamps=v_reward.threshold_stamps));
    while v_existing < v_allowed loop
      insert into public.point_tickets(
        ticket_id,member_id,point_card_id,reward_id,ticket_template_id,threshold_stamps,
        ticket_type,ticket_title,ticket_description,usage_method,usage_instructions,prizes
      ) values (
        public.new_public_id('PT'),p_member_id,p_point_card_id,v_reward.id,
        v_reward.template_id,v_reward.threshold_stamps,v_reward.ticket_type,v_reward.title,
        v_reward.description,v_reward.usage_method,v_reward.usage_instructions,v_reward.prizes
      );
      v_existing := v_existing + 1;
      v_count := v_count + 1;
    end loop;
  end loop;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_eligible_point_tickets_for_member(p_member_id uuid, p_point_card_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_point_card_id uuid;
  v_total integer := 0;
begin
  if p_member_id is null then
    raise exception 'MEMBER_NOT_FOUND';
  end if;

  if p_point_card_ids is null or coalesce(cardinality(p_point_card_ids), 0) = 0 then
    return 0;
  end if;

  if cardinality(p_point_card_ids) > 100 then
    raise exception 'TOO_MANY_POINT_CARDS';
  end if;

  for v_point_card_id in
    select distinct point_card_id
    from unnest(p_point_card_ids) as point_card_id
    where point_card_id is not null
  loop
    v_total := v_total + public.issue_eligible_point_tickets(p_member_id, v_point_card_id);
  end loop;

  return v_total;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_fixed_tickets(p_business_date date DEFAULT ((now() AT TIME ZONE 'Asia/Taipei'::text))::date, p_member_id uuid DEFAULT NULL::uuid, p_template_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_template public.fixed_ticket_templates%rowtype;
  v_member record;
  v_event public.event_tickets%rowtype;
  v_year integer;
  v_month integer;
  v_prev date;
  v_next date;
  v_candidate date;
  v_cycle_start date;
  v_cycle_end date;
  v_valid_until date;
  v_cycle_key text;
  v_event_cycle_key text;
  v_title text;
  v_event_public_id text;
  v_grant_id uuid;
  v_claim_id text;
  v_claim_count integer;
  v_issued integer := 0;
  v_queued integer := 0;
  v_templates integer := 0;
begin
  update public.event_ticket_claims c
  set status = 'expired', updated_at = now()
  from public.event_tickets e
  where c.event_ticket_id = e.id
    and e.fixed_ticket_template_id is not null
    and e.ends_on is not null
    and e.ends_on < p_business_date
    and c.status = 'claimed'
    and (p_template_id is null or e.fixed_ticket_template_id = p_template_id)
    and (p_member_id is null or c.member_id = p_member_id);

  update public.event_tickets
  set status = 'archived',
      updated_by = 'fixed-ticket-automation',
      updated_at = now()
  where fixed_ticket_template_id is not null
    and ends_on is not null
    and ends_on < p_business_date
    and status = 'active'
    and (p_template_id is null or fixed_ticket_template_id = p_template_id)
    and p_member_id is null;

  for v_template in
    select *
    from public.fixed_ticket_templates
    where status = 'active'
      and deleted_at is null
      and (p_template_id is null or id = p_template_id)
    order by created_at, id
  loop
    v_templates := v_templates + 1;
    v_year := extract(year from p_business_date)::integer;
    v_month := extract(month from p_business_date)::integer;

    if v_template.schedule_type = 'birthday_month' then
      v_cycle_start := date_trunc('month', p_business_date)::date;
      v_cycle_end := (date_trunc('month', p_business_date) + interval '1 month - 1 day')::date;
      v_event_cycle_key := 'birthday-month:' || to_char(v_cycle_start, 'YYYY-MM');
      v_cycle_key := 'birthday:' || extract(year from p_business_date)::integer::text;
    elsif v_template.schedule_type = 'weekly' then
      v_cycle_start := p_business_date - (((extract(isodow from p_business_date)::integer - v_template.schedule_weekday + 7) % 7))::integer;
      v_cycle_end := v_cycle_start + 6;
      v_cycle_key := 'week:' || to_char(v_cycle_start, 'IYYY-IW');
      v_event_cycle_key := v_cycle_key;
    elsif v_template.schedule_type = 'monthly' then
      v_candidate := public.fixed_schedule_date(v_year, v_month, v_template.schedule_day);
      if p_business_date < v_candidate then
        v_prev := (date_trunc('month', p_business_date) - interval '1 month')::date;
        v_cycle_start := public.fixed_schedule_date(
          extract(year from v_prev)::integer,
          extract(month from v_prev)::integer,
          v_template.schedule_day
        );
      else
        v_cycle_start := v_candidate;
      end if;
      v_next := (date_trunc('month', v_cycle_start) + interval '1 month')::date;
      v_cycle_end := public.fixed_schedule_date(
        extract(year from v_next)::integer,
        extract(month from v_next)::integer,
        v_template.schedule_day
      ) - 1;
      v_cycle_key := 'month:' || to_char(v_cycle_start, 'YYYY-MM');
      v_event_cycle_key := v_cycle_key;
    else
      v_candidate := public.fixed_schedule_date(v_year, v_template.schedule_month, v_template.schedule_day);
      if p_business_date < v_candidate then
        v_cycle_start := public.fixed_schedule_date(v_year - 1, v_template.schedule_month, v_template.schedule_day);
      else
        v_cycle_start := v_candidate;
      end if;
      v_cycle_end := public.fixed_schedule_date(
        extract(year from v_cycle_start)::integer + 1,
        v_template.schedule_month,
        v_template.schedule_day
      ) - 1;
      v_cycle_key := 'year:' || extract(year from v_cycle_start)::integer::text;
      v_event_cycle_key := v_cycle_key;
    end if;

    if v_template.expiry_mode = 'fixed_date' then
      v_valid_until := v_template.expiry_date;
    elsif v_template.expiry_mode = 'week_end' then
      v_valid_until := p_business_date + (7 - extract(isodow from p_business_date)::integer);
    elsif v_template.expiry_mode = 'days_after_issue' then
      v_valid_until := p_business_date + (v_template.expiry_days - 1);
    else
      v_valid_until := (date_trunc('month', v_cycle_start) + interval '1 month - 1 day')::date;
    end if;

    if v_valid_until is null or v_valid_until < p_business_date then
      continue;
    end if;

    v_title := replace(
      replace(v_template.title, '{year}', extract(year from v_cycle_start)::integer::text),
      '{month}', extract(month from v_cycle_start)::integer::text
    );
    v_event_public_id := 'FIXED-' || v_template.fixed_ticket_id || '-' || replace(replace(v_event_cycle_key, ':', '-'), '/', '-');

    insert into public.event_tickets(
      event_ticket_id,title,ticket_type,description,usage_method,usage_instructions,prizes,status,
      starts_on,ends_on,quota,accent,allowed_tier_keys,created_by,updated_by,activity_url,activity_link_name,
      fixed_ticket_template_id,fixed_cycle_key
    ) values (
      v_event_public_id,v_title,'coupon',v_template.description,v_template.usage_method,v_template.usage_instructions,
      '[]'::jsonb,'active',v_cycle_start,v_valid_until,v_template.quota,lower(v_template.accent),
      v_template.allowed_tier_keys,'fixed-ticket-automation','fixed-ticket-automation','','',v_template.id,v_event_cycle_key
    )
    on conflict (fixed_ticket_template_id, fixed_cycle_key)
      where fixed_ticket_template_id is not null and fixed_cycle_key is not null
    do update set
      title = excluded.title,
      description = excluded.description,
      usage_method = excluded.usage_method,
      usage_instructions = excluded.usage_instructions,
      status = 'active',
      starts_on = excluded.starts_on,
      ends_on = excluded.ends_on,
      quota = excluded.quota,
      accent = excluded.accent,
      allowed_tier_keys = excluded.allowed_tier_keys,
      updated_by = 'fixed-ticket-automation',
      updated_at = now(),
      deleted_at = null
    returning * into v_event;

    perform public.sync_fixed_ticket_calendar_item(v_template.id, v_event.id);

    for v_member in
      select m.id, m.line_user_id, m.display_name, m.birthday, m.is_test_account
      from public.members m
      where m.status = 'active'
        and m.membership_status = 'active'
        and (p_member_id is null or m.id = p_member_id)
        and (v_template.created_by not like 'qa:e2e:%' or coalesce(m.is_test_account, false))
        and (
          v_template.schedule_type <> 'birthday_month'
          or (m.birthday is not null and extract(month from m.birthday)::integer = extract(month from v_cycle_start)::integer)
        )
        and public.current_tier_key(m.id) = any(v_template.allowed_tier_keys)
      order by coalesce(m.joined_at, m.created_at), m.id
    loop
      if v_template.quota > 0 then
        select count(*)::integer into v_claim_count
        from public.event_ticket_claims
        where event_ticket_id = v_event.id;
        exit when v_claim_count >= v_template.quota;
      end if;

      v_grant_id := null;
      insert into public.fixed_ticket_grants(
        fixed_ticket_template_id,member_id,cycle_key,cycle_start,cycle_end,event_ticket_id,status
      ) values (
        v_template.id,v_member.id,v_cycle_key,v_cycle_start,v_cycle_end,v_event.id,'reserved'
      )
      on conflict (fixed_ticket_template_id, member_id, cycle_key) do nothing
      returning id into v_grant_id;

      if v_grant_id is null then continue; end if;

      v_claim_id := public.new_public_id('EC');
      insert into public.event_ticket_claims(
        claim_id,event_ticket_id,member_id,ticket_type,ticket_title,ticket_description,
        usage_method,usage_instructions,prizes,status,claimed_at
      ) values (
        v_claim_id,v_event.id,v_member.id,'coupon',v_event.title,v_event.description,
        v_event.usage_method,v_event.usage_instructions,'[]'::jsonb,'claimed',now()
      )
      on conflict (event_ticket_id, member_id) do nothing;

      select c.claim_id into v_claim_id
      from public.event_ticket_claims c
      where c.event_ticket_id = v_event.id
        and c.member_id = v_member.id
      limit 1;

      if v_claim_id is null then
        update public.fixed_ticket_grants
        set status = 'failed',
            notification_error = 'CLAIM_CREATE_FAILED',
            updated_at = now()
        where id = v_grant_id;
        continue;
      end if;

      update public.fixed_ticket_grants
      set claim_id = v_claim_id,
          status = 'issued',
          notification_error = '',
          updated_at = now()
      where id = v_grant_id;
      v_issued := v_issued + 1;

      if v_template.notify_line and not coalesce(v_member.is_test_account, false) then
        insert into public.scheduled_grant_messages(
          schedule_id,request_id,member_id,line_user_id,scheduled_for,message_text,status,created_by,fixed_ticket_grant_id,notification_business_date
        ) values (
          'FIXED-' || v_template.fixed_ticket_id || '-' || replace(v_cycle_key, ':', '-') || '-' || v_member.id::text,
          'FIXED-' || v_template.fixed_ticket_id || '-' || replace(v_cycle_key, ':', '-') || '-' || v_member.id::text,
          v_member.id,
          v_member.line_user_id,
          greatest(now(), (p_business_date + coalesce(v_template.notify_time, (now() at time zone 'Asia/Taipei')::time)) at time zone 'Asia/Taipei'),
          (case when v_template.schedule_type = 'birthday_month' then '🎂 ' else '🎁 ' end) ||
          coalesce(nullif(v_member.display_name, ''), '會員') || '，你已獲得「' || v_event.title || '」' || E'\n\n' ||
          v_event.description || E'\n\n' ||
          '使用期限：' || to_char(v_cycle_start, 'YYYY/MM/DD') || ' ～ ' || to_char(v_valid_until, 'YYYY/MM/DD'),
          'pending',
          'fixed-ticket-automation',
          v_grant_id,
          p_business_date
        )
        on conflict (request_id) do nothing;
        if found then v_queued := v_queued + 1; end if;
      end if;

      insert into public.audit_logs(
        audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
      ) values (
        public.new_public_id('AUD'),
        'system',
        'system',
        'fixed_ticket.issue',
        'member',
        v_member.line_user_id,
        'success',
        jsonb_build_object(
          'fixedTicketId',v_template.fixed_ticket_id,
          'scheduleType',v_template.schedule_type,
          'expiryMode',v_template.expiry_mode,
          'expiryDays',v_template.expiry_days,
          'cycleKey',v_cycle_key,
          'eventCycleKey',v_event_cycle_key,
          'cycleStart',v_cycle_start,
          'cycleEnd',v_cycle_end,
          'validUntil',v_valid_until,
          'eventTicketId',v_event.event_ticket_id,
          'claimId',v_claim_id
        )
      );
    end loop;
  end loop;

  return jsonb_build_object(
    'businessDate',p_business_date,
    'templatesChecked',v_templates,
    'issued',v_issued,
    'queued',v_queued
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_membership_join_ticket(p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member public.members%rowtype;
  v_event public.event_tickets%rowtype;
  v_existing_claim public.event_ticket_claims%rowtype;
  v_today date := (clock_timestamp() at time zone 'Asia/Taipei')::date;
  v_tier text;
  v_claim_count integer := 0;
  v_claim_id text;
begin
  select * into v_member
  from public.members
  where id = p_member_id
  for update;

  if not found
     or v_member.status <> 'active'
     or v_member.membership_status <> 'active' then
    return jsonb_build_object(
      'issued', false,
      'alreadyApplied', false,
      'reason', 'member_not_active'
    );
  end if;

  select * into v_event
  from public.event_tickets
  where ticket_type = 'membership_join'
    and status = 'active'
    and deleted_at is null
    and (starts_on is null or starts_on <= v_today)
    and (ends_on is null or ends_on >= v_today)
  order by created_at desc
  limit 1
  for update;

  if not found then
    return jsonb_build_object(
      'issued', false,
      'alreadyApplied', false,
      'reason', 'not_configured'
    );
  end if;

  select * into v_existing_claim
  from public.event_ticket_claims
  where event_ticket_id = v_event.id
    and member_id = v_member.id
  for update;

  if found then
    return jsonb_build_object(
      'issued', true,
      'alreadyApplied', true,
      'reason', 'already_issued',
      'claimId', v_existing_claim.claim_id,
      'eventTicketId', v_event.event_ticket_id
    );
  end if;

  v_tier := public.current_tier_key(v_member.id);
  if v_tier is null or not (v_tier = any(v_event.allowed_tier_keys)) then
    return jsonb_build_object(
      'issued', false,
      'alreadyApplied', false,
      'reason', 'tier_not_allowed',
      'eventTicketId', v_event.event_ticket_id
    );
  end if;

  if v_event.quota > 0 then
    select count(*)::integer into v_claim_count
    from public.event_ticket_claims
    where event_ticket_id = v_event.id;

    if v_claim_count >= v_event.quota then
      return jsonb_build_object(
        'issued', false,
        'alreadyApplied', false,
        'reason', 'sold_out',
        'eventTicketId', v_event.event_ticket_id
      );
    end if;
  end if;

  v_claim_id := public.new_public_id('EC');
  insert into public.event_ticket_claims(
    claim_id,
    event_ticket_id,
    member_id,
    ticket_type,
    ticket_title,
    ticket_description,
    usage_method,
    usage_instructions,
    prizes,
    status,
    claimed_at
  ) values (
    v_claim_id,
    v_event.id,
    v_member.id,
    'membership_join',
    v_event.title,
    v_event.description,
    v_event.usage_method,
    v_event.usage_instructions,
    v_event.prizes,
    'claimed',
    now()
  );

  insert into public.audit_logs(
    audit_id,
    actor_line_user_id,
    actor_role,
    action,
    target_type,
    target_id,
    result,
    detail
  ) values (
    public.new_public_id('AUD'),
    null,
    'system',
    'system.member.membership-join-ticket.issue',
    'member',
    v_member.line_user_id,
    'success',
    jsonb_build_object(
      'memberId', v_member.id,
      'claimId', v_claim_id,
      'eventTicketId', v_event.event_ticket_id,
      'ticketType', 'membership_join'
    )
  );

  insert into public.realtime_events(scope,event_type)
  values ('event','member.membership-join-ticket-issued');

  return jsonb_build_object(
    'issued', true,
    'alreadyApplied', false,
    'reason', 'issued',
    'claimId', v_claim_id,
    'eventTicketId', v_event.event_ticket_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.lookup_point_transfer_receiver(p_sender_line_user_id text, p_receiver_member_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sender public.members%rowtype;
  v_receiver public.members%rowtype;
begin
  select * into v_sender
  from public.members
  where line_user_id=p_sender_line_user_id
    and status='active'
    and membership_status='active';
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  select * into v_receiver
  from public.members
  where upper(member_code)=upper(btrim(coalesce(p_receiver_member_code,'')))
    and status='active'
    and membership_status='active';
  if not found then raise exception 'TRANSFER_RECEIVER_NOT_FOUND'; end if;
  if v_sender.id=v_receiver.id then raise exception 'TRANSFER_SELF_NOT_ALLOWED'; end if;

  return jsonb_build_object(
    'memberCode',v_receiver.member_code,
    'displayName',coalesce(v_receiver.display_name,'')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_admin_booking_notifications_read(p_admin_line_user_id text, p_through_notification_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_latest bigint := 0;
  v_target bigint := 0;
begin
  select coalesce(max(id), 0) into v_latest
  from public.admin_booking_notifications;

  v_target := least(
    v_latest,
    greatest(coalesce(p_through_notification_id, v_latest), 0)
  );

  insert into public.admin_booking_notification_reads(
    admin_line_user_id, last_read_notification_id, updated_at
  )
  values (p_admin_line_user_id, v_target, now())
  on conflict (admin_line_user_id)
  do update set
    last_read_notification_id = greatest(
      public.admin_booking_notification_reads.last_read_notification_id,
      excluded.last_read_notification_id
    ),
    updated_at = now();

  return public.admin_booking_notification_summary(p_admin_line_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.member_cancel_snapshot_event_ticket_request(p_line_user_id text, p_receipt_id text, p_ticket_id text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_member_id uuid;
  v_receipt public.booking_receipts%rowtype;
  v_benefits jsonb;
  v_verified jsonb;
  v_updated_at timestamptz;
begin
  if p_receipt_id is null or p_receipt_id !~ '^BR-[a-fA-F0-9]{32}$'
     or p_ticket_id is null or p_ticket_id !~ '^EC-[a-fA-F0-9]{32}$'
     or p_expected_updated_at is null then
    raise exception 'INVALID_INPUT';
  end if;
  -- Match the member -> receipt lock ordering of the review workflow.
  select id into v_member_id
    from public.members
    where line_user_id = p_line_user_id and status = 'active'
      and membership_status = 'active'
    for update;
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  select * into v_receipt from public.booking_receipts
    where receipt_id = p_receipt_id and member_id = v_member_id
      and submission_mode = 'accessible'
    for update;
  if not found then raise exception 'RECEIPT_NOT_OWNED'; end if;
  if v_receipt.status <> 'awaiting_review' then
    raise exception 'RECEIPT_NOT_PENDING';
  end if;

  -- Repeated clicks may safely return a no-op, without ever restoring a ticket.
  if not exists (
    select 1 from jsonb_array_elements(v_receipt.requested_benefits) item
    where item->>'kind' = 'event' and item->>'id' = p_ticket_id
  ) then
    return jsonb_build_object('receiptId',p_receipt_id,'ticketId',p_ticket_id,
      'updatedAt',v_receipt.updated_at,'alreadyApplied',true);
  end if;
  if v_receipt.updated_at is distinct from p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;

  select coalesce(jsonb_agg(entry.item order by entry.ordinality),'[]'::jsonb)
    into v_benefits
    from jsonb_array_elements(v_receipt.requested_benefits) with ordinality as entry(item,ordinality)
    where not (entry.item->>'kind' = 'event' and entry.item->>'id' = p_ticket_id);
  select coalesce(jsonb_agg(entry.item order by entry.ordinality),'[]'::jsonb)
    into v_verified
    from jsonb_array_elements(v_receipt.snapshot_location_verified_tickets)
      with ordinality as entry(item,ordinality)
    where not (entry.item->>'kind' = 'event' and entry.item->>'id' = p_ticket_id);

  update public.booking_receipts
    set requested_benefits = v_benefits,
        snapshot_location_verified_tickets = v_verified,
        updated_at = clock_timestamp()
    where id = v_receipt.id and status = 'awaiting_review'
    returning updated_at into v_updated_at;
  if not found then raise exception 'RECEIPT_NOT_PENDING'; end if;

  insert into public.audit_logs(
    audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
  ) values (
    public.new_public_id('AUD'),p_line_user_id,'member',
    'SNAPSHOT_EVENT_TICKET_CANCELLED','receipt',p_receipt_id,'success',
    jsonb_build_object('ticketId',p_ticket_id)
  );
  insert into public.realtime_events(scope,event_type)
    values ('event','user.event.snapshot-ticket.cancel'),
           ('member','user.event.snapshot-ticket.cancel'),
           ('admin','user.event.snapshot-ticket.cancel');

  return jsonb_build_object('receiptId',p_receipt_id,'ticketId',p_ticket_id,
    'updatedAt',v_updated_at,'cancelled',true,'alreadyApplied',false);
end;
$function$

