CREATE OR REPLACE FUNCTION public.member_friend_action(p_actor text, p_operation text, p_code text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 m public.members%rowtype; f public.members%rowtype; relation public.member_friendships%rowtype;
 friends jsonb; received jsonb;
begin
 select * into m from public.members where line_user_id=p_actor and status='active' and membership_status='active';
 if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;
 if p_operation='list' then
  select coalesce(jsonb_agg(jsonb_build_object('memberCode',o.member_code,'displayName',left(o.display_name,1)||'○',
    'status',r.status,'incoming',r.requested_by<>m.id) order by r.updated_at desc),'[]') into friends
  from public.member_friendships r join public.members o on o.id=case when r.member_a=m.id then r.member_b else r.member_a end
  where m.id in(r.member_a,r.member_b) and o.status='active' and o.membership_status='active'
    and (r.status in('pending','accepted') or (r.status='blocked' and r.requested_by=m.id));
  select coalesce(jsonb_agg(x.summary order by x.booking_date desc),'[]') into received from (
    select b.booking_date,jsonb_build_object('bookingDate',b.booking_date,'startTime',left(b.start_time::text,5),
      'serviceTitle',(select string_agg(i.service_title,'、' order by i.created_at) from public.booking_items i where i.booking_id=b.id and i.service_id<>'00000000-0000-4000-8000-000000000010'::uuid),
      'statusLabel',case b.status when 'pending' then '待確認' when 'confirmed' then '已確認' when 'completed' then '已完成' when 'cancelled' then '已取消' else '未成立' end) summary
    from public.bookings b where b.service_recipient_member_id=m.id order by b.booking_date desc limit 20
  ) x;
  return jsonb_build_object('friends',friends,'receivedBookings',received);
 end if;
 select * into f from public.members where (upper(member_code)=upper(btrim(p_code)) or upper(invite_code)=upper(btrim(p_code)))
   and status='active' and membership_status='active' and is_test_account=m.is_test_account;
 if not found then raise exception 'FRIEND_NOT_FOUND'; end if;
 if f.id=m.id then raise exception 'SELF_FRIEND_NOT_ALLOWED'; end if;
 if p_operation='lookup' then return jsonb_build_object('memberCode',f.member_code,'displayName',left(f.display_name,1)||'○'); end if;
 perform pg_advisory_xact_lock(hashtextextended('friend:'||least(m.id,f.id)::text||':'||greatest(m.id,f.id)::text,0));
 select * into relation from public.member_friendships where member_a=least(m.id,f.id) and member_b=greatest(m.id,f.id) for update;
 if relation.status='blocked' and relation.requested_by<>m.id then raise exception 'FRIEND_BLOCKED'; end if;
 if p_operation='request' then
  if relation.status='blocked' then raise exception 'FRIEND_BLOCKED'; end if;
  if relation.status in('pending','accepted') then return jsonb_build_object('status',relation.status,'alreadyApplied',true); end if;
  insert into public.member_friendships(member_a,member_b,requested_by,status) values(least(m.id,f.id),greatest(m.id,f.id),m.id,'pending')
   on conflict(member_a,member_b) do update set requested_by=m.id,status='pending',updated_at=now();
 elsif p_operation='accept' then
  if relation.status='accepted' then return jsonb_build_object('status','accepted','alreadyApplied',true); end if;
  if relation.status is distinct from 'pending' or relation.requested_by=m.id then raise exception 'FRIEND_ACCEPT_DENIED'; end if;
  update public.member_friendships set status='accepted',updated_at=now() where id=relation.id;
 elsif p_operation in('remove','block') then
  if relation.id is null then raise exception 'FRIEND_NOT_FOUND'; end if;
  update public.member_friendships set status=case when p_operation='block' then 'blocked' else 'removed' end,
    requested_by=case when p_operation='block' then m.id else requested_by end,updated_at=now() where id=relation.id;
 else raise exception 'INVALID_FRIEND_OPERATION'; end if;
 insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
 values(public.new_public_id('AUD'),p_actor,'member','FRIEND_'||upper(p_operation),'member',f.id::text,'success',jsonb_build_object('memberCode',f.member_code));
 perform public.emit_realtime_invalidation(array['member','booking'],'friend.changed');
 return jsonb_build_object('status',case p_operation when 'request' then 'pending' when 'accept' then 'accepted' when 'block' then 'blocked' else 'removed' end);
end $function$

CREATE OR REPLACE FUNCTION public.member_login_claim(p_line_user_id text, p_browser_hash text, p_token_hash text, p_issued_at_ms bigint, p_mode text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current_session public.member_login_sessions%ROWTYPE;
DECLARE outcome text := 'resumed';
BEGIN
  IF length(p_line_user_id) < 2 OR length(p_line_user_id) > 120
    OR p_browser_hash !~ '^[a-f0-9]{64}$'
    OR p_token_hash !~ '^[a-f0-9]{64}$'
    OR p_issued_at_ms IS NULL OR p_issued_at_ms <= 0
    OR p_mode NOT IN ('login', 'resume') THEN
    RAISE EXCEPTION 'invalid login claim';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('member-removal:'||pg_catalog.encode(extensions.digest(p_line_user_id,'sha256'),'hex'),0));
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_line_user_id, 161083));
  SELECT * INTO current_session FROM public.member_login_sessions
    WHERE line_user_id = p_line_user_id FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.member_login_sessions (line_user_id,browser_hash,latest_token_iat_ms)
    VALUES (p_line_user_id,p_browser_hash,p_issued_at_ms);
    outcome := 'claimed';
  ELSIF current_session.browser_hash IS DISTINCT FROM p_browser_hash THEN
    IF p_mode <> 'login' OR p_issued_at_ms <= current_session.latest_token_iat_ms THEN
      RETURN 'session_replaced';
    END IF;
    DELETE FROM public.member_login_token_grants WHERE line_user_id = p_line_user_id;
    UPDATE public.member_login_sessions
    SET browser_hash = p_browser_hash, latest_token_iat_ms = p_issued_at_ms,
        generation = generation + 1, claimed_at = now(), updated_at = now()
    WHERE line_user_id = p_line_user_id;
    outcome := 'replaced';
  ELSE
    UPDATE public.member_login_sessions
      SET latest_token_iat_ms = greatest(latest_token_iat_ms,p_issued_at_ms),updated_at=now()
      WHERE line_user_id = p_line_user_id;
  END IF;
  INSERT INTO public.member_login_token_grants(token_hash,line_user_id)
  VALUES (p_token_hash,p_line_user_id)
  ON CONFLICT (token_hash) DO NOTHING;
  IF outcome = 'replaced' THEN
    INSERT INTO public.realtime_events(scope,event_type) VALUES('all','member.login.replaced');
  END IF;
  RETURN outcome;
END;
$function$

CREATE OR REPLACE FUNCTION public.member_login_logout(p_line_user_id text, p_token_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_line_user_id,161083));
  IF NOT EXISTS (
    SELECT 1 FROM public.member_login_token_grants
    WHERE line_user_id=p_line_user_id AND token_hash=p_token_hash
  ) THEN RETURN false; END IF;
  DELETE FROM public.member_login_token_grants WHERE line_user_id=p_line_user_id;
  UPDATE public.member_login_sessions
    SET browser_hash=NULL,updated_at=now()
    WHERE line_user_id=p_line_user_id;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.member_receipt_upload_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare owner_id uuid;
begin
 if new.bucket_id<>'booking-receipts' then return new; end if;
 if split_part(new.name,'/',1) !~ '^[a-f0-9-]{36}$' then raise exception 'RECEIPT_OWNER_REQUIRED'; end if;
 owner_id:=split_part(new.name,'/',1)::uuid;
 perform 1 from members where id=owner_id and status='active' for key share;
 if not found or exists(select 1 from member_removal_jobs where member_id=owner_id and state='deleting') then raise exception 'MEMBER_REMOVED'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.member_removal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare value uuid; col text; record_json jsonb:=to_jsonb(new); j uuid;
begin
  foreach col in array tg_argv loop
    value := nullif(record_json->>col,'')::uuid;
    if value is null then continue; end if;
    perform 1 from members where id=value for key share;
    select id into j from member_removal_jobs where member_id=value and state='deleting';
    if j is not null and coalesce(current_setting('membership.removal_job',true),'')<>j::text then
      raise exception 'MEMBER_REMOVED';
    end if;
  end loop;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.member_removal_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare j uuid; removed_before timestamptz; job_state text;
begin
 perform pg_advisory_xact_lock(hashtextextended('member-removal:'||encode(extensions.digest(new.line_user_id,'sha256'),'hex'),0));
 select id,revoked_before,state into j,removed_before,job_state from member_removal_jobs where identity_hash=encode(extensions.digest(new.line_user_id,'sha256'),'hex');
 if j is not null and coalesce(current_setting('membership.removal_job',true),'')<>j::text then
  if job_state='deleting' or not exists(select 1 from member_login_sessions where line_user_id=new.line_user_id and latest_token_iat_ms > extract(epoch from removed_before)*1000) then raise exception 'MEMBER_REMOVED'; end if;
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.member_removal_storage_paths(p_actor text, p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare mid uuid; paths text[];
begin
 if not exists(select 1 from admins where line_user_id=p_actor and role='admin' and status='active') then raise exception 'ADMIN_REQUIRED'; end if;
 select member_id,artifact_paths into mid,paths from member_removal_jobs where id=p_job_id and state='deleting';
 if mid is null then return '[]'::jsonb; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('bucket',bucket_id,'path',name)) from (select bucket_id,name from storage.objects where (bucket_id='booking-receipts' and name like mid::text||'/%') or (bucket_id='e2e-failure-artifacts' and name=any(paths)) limit 100) s),'[]'::jsonb);
end; $function$

CREATE OR REPLACE FUNCTION public.member_ticket_booking_options(p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare result jsonb; t record;
begin
 result:=public.member_ticket_booking_options_with_booking(p_member_id);
 if exists(select 1 from public.members where id=p_member_id and status='active' and membership_status='active') then
 for t in select 'points'::text kind,ticket_id ref from public.point_tickets where member_id=p_member_id and status='available'
 union all select 'event',claim_id from public.event_ticket_claims where member_id=p_member_id and status='claimed' loop
 if not public.ticket_has_service_requirement(p_member_id,t.kind,t.ref) and not exists(select 1 from public.booking_benefit_selections s where s.member_id=p_member_id and s.benefit_kind=t.kind and s.benefit_ref=t.ref and s.status='pending') then
 result:=jsonb_set(result,array[t.kind,t.ref],coalesce(result#>array[t.kind,t.ref],'[]'::jsonb)||
 jsonb_build_array(jsonb_build_object('bookingId','no-booking','bookingDate','','startTime','','title','不綁定預約，直接使用票券')));
 end if;
 end loop;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.member_update_booking_benefits_request(p_line_user_id text, p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_request_id text, p_benefits jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  b public.bookings%rowtype;
  m public.members%rowtype;
  replay public.booking_benefit_change_requests%rowtype;
  normalized jsonb;
  answer jsonb;
  max_points int;
  max_events int;
begin
  if p_request_id is null or p_request_id !~ '^BSEL-[A-Za-z0-9-]{8,95}$'
    then raise exception 'INVALID_REQUEST_ID'; end if;
  if p_benefits is null or jsonb_typeof(p_benefits)<>'array'
    then raise exception 'INVALID_BOOKING_BENEFITS'; end if;
  if jsonb_array_length(p_benefits)>20 or exists(
    select 1 from jsonb_array_elements(p_benefits) v
    where jsonb_typeof(v)<>'object' or coalesce(v->>'kind','') not in ('points','event')
      or coalesce(length(v->>'id'),0) not between 1 and 160
  ) then raise exception 'INVALID_BOOKING_BENEFITS'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('kind',v->>'kind','id',v->>'id') order by v->>'kind',v->>'id'),'[]')
    into normalized from jsonb_array_elements(p_benefits) v;
  if (select count(*) from (select distinct v->>'kind',v->>'id' from jsonb_array_elements(normalized) v) x)
    <>jsonb_array_length(normalized) then raise exception 'INVALID_BOOKING_BENEFITS'; end if;

  -- Same booking -> member lock order as final completion. Identity is supplied by
  -- the authenticated Edge handler; browser roles cannot execute this RPC.
  select * into b from public.bookings where id=p_booking_id for update;
  if not found then raise exception 'BOOKING_NOT_OWNED'; end if;
  select * into m from public.members where id=b.member_id and line_user_id=p_line_user_id for update;
  if not found then raise exception 'BOOKING_NOT_OWNED'; end if;
  if m.status<>'active' or m.membership_status<>'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  select * into replay from public.booking_benefit_change_requests
    where member_id=m.id and request_id=p_request_id;
  if found then
    if replay.booking_id<>p_booking_id or replay.selections<>normalized then raise exception 'REQUEST_ID_CONFLICT'; end if;
    return replay.result || jsonb_build_object('alreadyApplied',true);
  end if;
  if b.status not in ('pending','confirmed') or b.completed_at is not null or b.receipt_submission_id is not null
    then raise exception 'BOOKING_NOT_EDITABLE'; end if;
  if b.cancellation_requested_at is not null and b.cancellation_reviewed_at is null
    then raise exception 'BOOKING_CANCELLATION_PENDING'; end if;
  if p_expected_updated_at is null or b.updated_at<>p_expected_updated_at
    then raise exception 'BOOKING_CONFLICT'; end if;
  -- Already redeemed benefits remain immutable; caller sends only pending intent.
  if exists(select 1 from jsonb_array_elements(normalized) v
    join public.booking_benefit_selections s on s.booking_id=b.id
      and s.benefit_kind=v->>'kind' and s.benefit_ref=v->>'id'
    where s.status in ('redeemed','applied')) then raise exception 'BOOKING_BENEFIT_ALREADY_USED'; end if;
  select max_tickets_per_redemption into max_points from public.point_card_settings where id=1;
  select max_tickets_per_day into max_events from public.event_ticket_settings where id=1;
  if coalesce(max_points,1)>0 and
    (select count(*) from jsonb_array_elements(normalized) v where v->>'kind'='points')+
    (select count(*) from public.booking_benefit_selections where booking_id=b.id and benefit_kind='points' and status='redeemed')>coalesce(max_points,1)
    then raise exception 'BOOKING_POINT_TICKET_LIMIT_EXCEEDED'; end if;
  if coalesce(max_events,1)>0 and
    (select count(*) from jsonb_array_elements(normalized) v where v->>'kind'='event')+
    (select count(*) from public.booking_benefit_selections where booking_id=b.id and benefit_kind='event' and status='redeemed')>coalesce(max_events,1)
    then raise exception 'BOOKING_EVENT_TICKET_LIMIT_EXCEEDED'; end if;
  if exists(select 1 from jsonb_array_elements(normalized) v
    where not public.booking_ticket_matches_services(b.id,m.id,v->>'kind',v->>'id'))
    then raise exception 'BOOKING_BENEFIT_SERVICE_REQUIRED'; end if;
  perform public.replace_booking_benefit_selections_request(b.id,m.id,normalized ||
    coalesce((select jsonb_agg(jsonb_build_object('kind',benefit_kind,'id',benefit_ref))
      from public.booking_benefit_selections where booking_id=b.id and benefit_kind='calendar' and status='pending'),'[]'));
  -- Do not silently discard a stale/incompatible checkbox payload.
  if (select count(*) from public.booking_benefit_selections where booking_id=b.id
      and status='pending' and benefit_kind in ('points','event'))<>jsonb_array_length(normalized)
    then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;
  update public.bookings set updated_at=clock_timestamp() where id=b.id returning * into b;
  answer:=jsonb_build_object('bookingId',b.id,'updatedAt',b.updated_at,'requestId',p_request_id,'alreadyApplied',false);
  insert into public.booking_benefit_change_requests(member_id,request_id,booking_id,selections,result)
    values(m.id,p_request_id,b.id,normalized,answer);
  -- Audit failure rolls back the selection change and replay entry together.
  insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
    values(p_line_user_id,'member','BOOKING_BENEFITS_UPDATED','booking',b.id::text,'success',
      jsonb_build_object('requestId',p_request_id,'selectedCount',jsonb_array_length(normalized),'ticketTitles',coalesce((select jsonb_agg(left(title_snapshot,100) order by benefit_kind,benefit_ref) from public.booking_benefit_selections where booking_id=b.id and status='pending' and benefit_kind in ('points','event')),'[]')));
  return answer;
end $function$

CREATE OR REPLACE FUNCTION public.notify_admin_config_realtime_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_scopes text[];
  v_event_type text := 'admin.db.' || tg_table_name || '.' || lower(tg_op);
begin
  case tg_table_name
    when 'membership_tier_settings' then
      v_scopes := array['member', 'points', 'event', 'calendar', 'admin'];
    when 'point_cards' then
      v_scopes := array['points', 'admin'];
    when 'point_card_rewards' then
      v_scopes := array['points', 'admin'];
    when 'ticket_templates' then
      v_scopes := array['points', 'admin'];
    when 'event_tickets' then
      v_scopes := array['event', 'admin'];
    when 'calendar_items' then
      v_scopes := array['calendar', 'member', 'admin'];
    when 'grant_message_presets' then
      v_scopes := array['admin'];
    else
      v_scopes := array['admin'];
  end case;

  perform public.emit_realtime_invalidation(v_scopes, v_event_type);
  return null;
end;
$function$

