CREATE OR REPLACE FUNCTION public.operation_audit_safe_detail(p_action text, p_type text, p_target text, p_meta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare answer jsonb:='{}'; fields jsonb; t public.point_transfers%rowtype; v_title text;
begin
 if jsonb_typeof(p_meta)<>'object' then p_meta:='{}'; end if;
 if p_action in ('MEMBER_PROFILE_UPDATED','user.member.profile.save','admin.member.update','ADMIN_MEMBER_UPDATE') then
  select coalesce(jsonb_agg(v),'[]') into fields from jsonb_array_elements(case when jsonb_typeof(p_meta->'profileFields')='array' then p_meta->'profileFields' else '[]' end) v
  where v#>>'{}' in ('birthday','phone','surname','salutation','display_name','status','membership_status');
  answer:=answer||jsonb_build_object('profileFields',fields);
 end if;
 if p_action='user.pointcard.transfer' then
  select * into t from public.point_transfers where transfer_id=p_target;
  if found then
   answer:=answer||jsonb_build_object('amount',t.amount,'sender',(select left(member_code,3)||'…'||right(member_code,3) from public.members where id=t.sender_member_id),'receiver',(select left(member_code,3)||'…'||right(member_code,3) from public.members where id=t.receiver_member_id),'cardTitle',(select left(title,120) from public.point_cards where id=t.point_card_id));
  end if;
 end if;
 if p_action='BOOKING_BENEFITS_UPDATED' and jsonb_typeof(p_meta->'ticketTitles')='array' then
  select string_agg(left(value#>>'{}',100),'、') into v_title from jsonb_array_elements(p_meta->'ticketTitles') x(value) where jsonb_typeof(value)='string';
  if v_title is not null then answer:=answer||jsonb_build_object('ticketTitle',left(v_title,300)); end if;
 elsif p_type='booking' and p_action ~ '^(BOOKING_|SNAPSHOT_)' then
  select string_agg(distinct left(s.title_snapshot,100),'、') into v_title from public.booking_benefit_selections s where booking_id::text=p_target and benefit_kind in ('points','event');
  if v_title is not null then answer:=answer||jsonb_build_object('ticketTitle',left(v_title,300)); end if;
 end if;
 if p_type in ('point_ticket_batch','event_claim_batch') then
  if p_type='point_ticket_batch' then
   select string_agg(distinct left(ticket_title,100),'、') into v_title from public.point_tickets where ticket_id in
    (select value from jsonb_array_elements_text(case when jsonb_typeof(p_meta->'ticketIds')='array' then p_meta->'ticketIds' else '[]' end));
  else
   select string_agg(distinct left(ticket_title,100),'、') into v_title from public.event_ticket_claims where claim_id in
    (select value from jsonb_array_elements_text(case when jsonb_typeof(p_meta->'claimIds')='array' then p_meta->'claimIds' else '[]' end));
  end if;
  if v_title is not null then answer:=answer||jsonb_build_object('ticketTitle',left(v_title,300)); end if;
 end if;
 if p_action in ('SNAPSHOT_POINT_TICKET_CANCELLED','SNAPSHOT_EVENT_TICKET_CANCELLED') then
  select left(ticket_title,120) into v_title from public.point_tickets where ticket_id=p_meta->>'ticketId';
  if v_title is null then select left(ticket_title,120) into v_title from public.event_ticket_claims where claim_id=p_meta->>'ticketId'; end if;
  if v_title is not null then answer:=answer||jsonb_build_object('ticketTitle',v_title); end if;
 end if;
 if p_type in ('point_ticket','ticket','event_ticket_claim','event_claim') then
  select left(ticket_title,120) into v_title from public.point_tickets where ticket_id=p_target;
  if v_title is null then select left(ticket_title,120) into v_title from public.event_ticket_claims where claim_id=p_target; end if;
  if v_title is not null then answer:=answer||jsonb_build_object('ticketTitle',v_title); end if;
 end if;
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.pick_lottery_prize(p_prizes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_roll numeric := random()*100;
  v_cursor numeric := 0;
  v_item jsonb;
  v_last jsonb := null;
begin
  if jsonb_typeof(p_prizes) <> 'array' or jsonb_array_length(p_prizes)=0 then
    return jsonb_build_object('prizeTitle','未設定獎項','prizeDescription','');
  end if;
  for v_item in select value from jsonb_array_elements(p_prizes)
  loop
    v_last := v_item;
    v_cursor := v_cursor + greatest(0,coalesce((v_item->>'winRate')::numeric,0));
    if v_roll < v_cursor then return v_item - 'winRate'; end if;
  end loop;
  return coalesce(v_last - 'winRate',jsonb_build_object('prizeTitle','未設定獎項','prizeDescription',''));
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_accessible_receipt_request(p_member_id uuid, p_request_id text, p_object_path text, p_mime_type text, p_size_bytes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v public.booking_receipts%rowtype;
begin
  perform 1 from public.members where id=p_member_id and status='active' and membership_status='active' for update;
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if coalesce(p_request_id,'') !~ '^[A-Za-z0-9_-]{8,120}$' then raise exception 'INVALID_REQUEST_ID'; end if;
  if p_mime_type is null or p_mime_type not in ('image/jpeg','image/png','image/webp','image/heic','image/heif') then raise exception 'RECEIPT_INVALID_MIME'; end if;
  if p_size_bytes is null or p_size_bytes not between 1 and 5242880 then raise exception 'RECEIPT_FILE_TOO_LARGE'; end if;
  if p_object_path is null or p_object_path not like p_member_id::text||'/accessible/%' then raise exception 'RECEIPT_INVALID_PATH'; end if;
  select * into v from public.booking_receipts where member_id=p_member_id and request_id=p_request_id for update;
  if found then
    if v.submission_mode<>'accessible' or v.declared_mime_type<>p_mime_type or v.declared_size_bytes<>p_size_bytes then raise exception 'REQUEST_ID_CONFLICT'; end if;
    if v.status not in ('pending_upload','awaiting_review','bound') then raise exception 'RECEIPT_NOT_PENDING'; end if;
    return jsonb_build_object('receiptId',v.receipt_id,'objectPath',v.object_path,'status',v.status,'alreadyPrepared',true);
  end if;
  with replaced as (
    update public.booking_receipts set status='failed',failure_reason='upload-replaced',updated_at=now()
    where member_id=p_member_id and submission_mode='accessible' and booking_id is null and status='pending_upload'
    returning object_path
  ) insert into public.booking_receipt_cleanup_queue(object_path,reason)
    select object_path,'upload-replaced' from replaced on conflict(object_path) do nothing;
  insert into public.booking_receipts(receipt_id,member_id,request_id,object_path,declared_mime_type,declared_size_bytes,submission_mode)
  values(public.new_public_id('BR'),p_member_id,p_request_id,p_object_path,p_mime_type,p_size_bytes,'accessible') returning * into v;
  return jsonb_build_object('receiptId',v.receipt_id,'objectPath',v.object_path,'status',v.status);
end $function$

CREATE OR REPLACE FUNCTION public.prepare_booking_receipt_request(p_booking_id uuid, p_member_id uuid, p_request_id text, p_object_path text, p_mime_type text, p_size_bytes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_existing public.booking_receipts%rowtype;
  v_receipt public.booking_receipts%rowtype;
begin
  p_request_id:=btrim(coalesce(p_request_id,''));
  p_object_path:=btrim(coalesce(p_object_path,''));
  p_mime_type:=lower(btrim(coalesce(p_mime_type,'')));

  if p_request_id !~ '^[A-Za-z0-9_-]{8,120}$' then raise exception 'INVALID_REQUEST_ID'; end if;
  if p_mime_type not in ('image/jpeg','image/png','image/webp','image/heic','image/heif') then raise exception 'RECEIPT_INVALID_MIME'; end if;
  if p_size_bytes is null or p_size_bytes<1 or p_size_bytes>5242880 then raise exception 'RECEIPT_FILE_TOO_LARGE'; end if;
  if p_object_path not like p_member_id::text||'/'||p_booking_id::text||'/%' then raise exception 'RECEIPT_INVALID_PATH'; end if;

  select * into v_booking
  from public.bookings
  where id=p_booking_id
  for update;
  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if v_booking.member_id<>p_member_id then raise exception 'BOOKING_NOT_OWNED'; end if;
  if v_booking.status<>'confirmed' then raise exception 'INVALID_BOOKING_TRANSITION'; end if;
  if v_booking.cancellation_requested_at is not null and v_booking.cancellation_reviewed_at is null then
    raise exception 'BOOKING_CANCELLATION_PENDING';
  end if;

  select * into v_existing
  from public.booking_receipts
  where member_id=p_member_id and request_id=p_request_id
  for update;
  if found then
    if v_existing.booking_id<>p_booking_id
       or v_existing.declared_mime_type<>p_mime_type
       or v_existing.declared_size_bytes<>p_size_bytes then
      raise exception 'REQUEST_ID_CONFLICT';
    end if;
    if v_existing.status not in ('pending_upload','awaiting_review','bound') then
      raise exception 'RECEIPT_NOT_PENDING';
    end if;
    return jsonb_build_object(
      'receiptId',v_existing.receipt_id,
      'objectPath',v_existing.object_path,
      'status',v_existing.status,
      'alreadyPrepared',true,
      'replacedExisting',false
    );
  end if;

  select * into v_existing
  from public.booking_receipts
  where booking_id=p_booking_id and status='bound'
  for update;
  if found then raise exception 'BOOKING_ALREADY_COMPLETED_WITH_RECEIPT'; end if;

  -- Keep the submitted snapshot visible until its replacement validates.
  -- Each attempt gets a new row and object, so an old finalize/upload cannot
  -- act on the replacement. A booking lock serializes competing prepares.
  select * into v_existing
  from public.booking_receipts
  where booking_id=p_booking_id and status='pending_upload'
  for update;
  if found then
    update public.booking_receipts
    set status='failed',failure_reason='upload-replaced',updated_at=now()
    where id=v_existing.id;
    insert into public.booking_receipt_cleanup_queue(object_path,reason)
    values(v_existing.object_path,'upload-replaced')
    on conflict(object_path) do nothing;
  end if;

  insert into public.booking_receipts(
    receipt_id,booking_id,member_id,request_id,object_path,declared_mime_type,declared_size_bytes
  ) values(
    public.new_public_id('BR'),p_booking_id,p_member_id,p_request_id,p_object_path,p_mime_type,p_size_bytes
  )
  returning * into v_receipt;

  return jsonb_build_object(
    'receiptId',v_receipt.receipt_id,
    'objectPath',v_receipt.object_path,
    'status',v_receipt.status,
    'alreadyPrepared',false,
    'replacedExisting',false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_e2e_event_redemption_day(p_member_id uuid, p_fixture_tag text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_day_start timestamptz := ((now() at time zone 'Asia/Taipei')::date::timestamp at time zone 'Asia/Taipei'); v_moved integer;
begin
  if p_fixture_tag is null or p_fixture_tag !~ '^[A-F0-9]{16}$' then raise exception 'INVALID_QA_FIXTURE'; end if;
  perform 1 from public.members where id=p_member_id and is_test_account is true and status='active' and membership_status='active' for update;
  if not found then raise exception 'TEST_ACCOUNT_REQUIRED'; end if;
  if not exists(select 1 from public.event_tickets where created_by='qa-ui:'||p_member_id::text||':'||p_fixture_tag
    and event_ticket_id like 'QA-UI-EVT-%' and deleted_at is null) then raise exception 'QA_FIXTURE_NOT_OWNED'; end if;
  update public.event_ticket_claims c set used_at=v_day_start-interval '1 second',updated_at=now()
  from public.event_tickets e
  where c.event_ticket_id=e.id and c.member_id=p_member_id and c.status='used'
    and c.used_at >= v_day_start
    and c.used_at < v_day_start+interval '1 day'
    and e.event_ticket_id like 'QA-UI-EVT-%'
    and e.created_by ~ ('^qa-ui:'||p_member_id::text||':[A-F0-9]{16}$');
  get diagnostics v_moved=row_count;
  return jsonb_build_object('qaHistoryMoved',v_moved,'fixtureDate',(v_day_start at time zone 'Asia/Taipei')::date,'productionLimitUnchanged',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_e2e_membership_terms_fixture(p_member_id uuid, p_actor text, p_fixture_tag text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member public.members%rowtype;
  v_terms public.membership_terms%rowtype;
  v_version text := 'E2E-20261005-1';
  v_created boolean := false;
begin
  if not public.is_qa_test_provenance(p_actor)
     or p_fixture_tag is null
     or upper(p_fixture_tag) !~ '^[A-F0-9]{16}$' then
    raise exception 'INVALID_QA_FIXTURE';
  end if;
  perform pg_advisory_xact_lock(hashtext(p_member_id::text), 20260928);
  select * into v_member from public.members where id=p_member_id for update;
  if not found or v_member.is_test_account is not true or v_member.status <> 'active' then
    raise exception 'TEST_ACCOUNT_REQUIRED';
  end if;
  select * into v_terms
    from public.membership_terms
   where scope='e2e' and e2e_member_id=p_member_id and status='active'
   for update;
  if found and v_terms.version <> v_version then
    update public.membership_terms
       set status='archived',updated_by=p_actor,updated_at=clock_timestamp()
     where id=v_terms.id;
    v_terms := null;
  end if;
  if v_terms.id is null then
    insert into public.membership_terms(
      scope,e2e_member_id,version,title,summary,body,status,required,effective_at,
      reconsent_existing,activated_at,created_by,updated_by
    ) values (
      'e2e',p_member_id,v_version,'E2E 會員申請條款',
      'E2E 測試帳號專用會員申請條款，不影響正式會員或其他測試帳號。',
      '此條款僅供 MemberWebsocket-dev E2E 驗證會員申請、版本確認、未同意拒絕與同意紀錄生命週期。',
      'active',true,clock_timestamp()-interval '1 minute',
      true,clock_timestamp(),p_actor,p_actor
    )
    returning * into v_terms;
    v_created := true;
  end if;
  delete from public.membership_consents where member_id=p_member_id and terms_id=v_terms.id;
  return jsonb_build_object(
    'id',v_terms.id,'memberId',v_terms.e2e_member_id,'version',v_terms.version,
    'title',v_terms.title,'summary',v_terms.summary,'body',v_terms.body,
    'required',v_terms.required,'scope',v_terms.scope,'created',v_created
  );
end
$function$

CREATE OR REPLACE FUNCTION public.prepare_snapshot_receipt_v2(p_member_id uuid, p_request_id text, p_object_path text, p_mime_type text, p_size_bytes integer, p_location jsonb, p_benefits jsonb, p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb; requested jsonb; r public.booking_receipts%rowtype;
 item jsonb; kind text; ref text; locs jsonb; needed boolean;
 verified jsonb:='[]'::jsonb; fix jsonb:=null;
begin
 perform public.require_snapshot_location(p_location);
 if jsonb_typeof(p_benefits) is distinct from 'array'
   or jsonb_array_length(p_benefits)>20 then raise exception 'INVALID_BOOKING_BENEFITS'; end if;
 result:=public.prepare_accessible_receipt_request(p_member_id,p_request_id,p_object_path,p_mime_type,p_size_bytes);
 select * into r from public.booking_receipts where receipt_id=result->>'receiptId' for update;
 if coalesce((result->>'alreadyPrepared')::boolean,false) then
   requested:=public.validate_snapshot_ticket_selection(p_member_id,p_booking_id,p_benefits,r.receipt_id);
   if r.requested_benefits<>requested or r.requested_booking_id is distinct from p_booking_id then raise exception 'REQUEST_ID_CONFLICT'; end if;
 else
   for item in select value from jsonb_array_elements(p_benefits) loop
     kind:=item->>'kind'; ref:=item->>'id'; needed:=false; locs:=null;
     if kind='points' then
       select t.requires_location,t.redemption_locations into needed,locs
       from public.point_tickets t where t.member_id=p_member_id and t.ticket_id=ref;
     elsif kind='event' then
       select e.requires_location,e.redemption_locations into needed,locs
       from public.event_ticket_claims c join public.event_tickets e on e.id=c.event_ticket_id
       where c.member_id=p_member_id and c.claim_id=ref;
     end if;
     if coalesce(needed,false) then
       if p_location is null or jsonb_typeof(p_location)<>'object'
          or jsonb_typeof(p_location->'latitude') is distinct from 'number'
          or jsonb_typeof(p_location->'longitude') is distinct from 'number'
          or jsonb_typeof(p_location->'accuracy') is distinct from 'number'
          or jsonb_typeof(p_location->'timestamp') is distinct from 'number'
       then raise exception 'BOOKING_BENEFIT_LOCATION_REQUIRED'; end if;
       if fix is null then
         fix:=jsonb_build_object('latitude',p_location->'latitude',
           'longitude',p_location->'longitude','accuracy',p_location->'accuracy',
           'observedAt',to_timestamp((p_location->>'timestamp')::double precision/1000));
       end if;
       perform public.verify_ticket_redemption_locations(locs,fix);
       verified:=verified||jsonb_build_array(jsonb_build_object('kind',kind,'id',ref));
     end if;
   end loop;
   update public.booking_receipts set snapshot_location_verified_tickets=verified where id=r.id;
   requested:=public.validate_snapshot_ticket_selection(p_member_id,p_booking_id,p_benefits,r.receipt_id);
   update public.booking_receipts set requested_benefits=requested,requested_booking_id=p_booking_id where id=r.id;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.prevent_booking_on_active_holiday()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.receipt_submission_id is not null and exists (
    select 1 from public.booking_receipts r
    where r.receipt_id=new.receipt_submission_id and r.member_id=new.member_id
      and r.submission_mode='accessible' and r.status in ('awaiting_review','bound')
  ) then return new; end if;
  if exists (
    select 1
    from public.calendar_items
    where item_type = 'holiday'
      and status = 'active'
      and starts_on <= new.booking_date
      and coalesce(ends_on, starts_on) >= new.booking_date
  ) then
    raise exception 'BOOKING_HOLIDAY';
  end if;
  return new;
end;
$function$

