CREATE OR REPLACE FUNCTION public.redeem_member_tickets_for_booking_request(p_line_user_id text, p_booking_id uuid, p_kind text, p_refs text[], p_request_id text, p_location jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype; v_member public.members%rowtype;
  v_previous public.booking_ticket_usage_requests%rowtype; v_refs text[]; v_ref text; v_result jsonb;
begin
  perform 1 from public.booking_settings where id=1 for share;
  if p_kind not in ('points','event') or p_kind is null or coalesce(cardinality(p_refs),0) not between 1 and 50
    or exists(select 1 from unnest(p_refs) ref where ref is null or btrim(ref)='' or length(ref)>160)
    or (select count(distinct ref) from unnest(p_refs) ref)<>cardinality(p_refs) then raise exception 'INVALID_TICKET_BATCH'; end if;
  if p_request_id is null or p_request_id!~'^[A-Za-z0-9_-]{8,120}$' then raise exception 'INVALID_REQUEST_ID'; end if;
  select array_agg(ref order by ref) into v_refs from unnest(p_refs) ref;
  -- Match completion/edit lock order: booking, member, tickets, then balances/inventory.
  select * into v_booking from public.bookings where id=p_booking_id for update;
  select * into v_member from public.members where line_user_id=p_line_user_id for update;
  if not found or v_member.status<>'active' or v_member.membership_status<>'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if p_booking_id is not null and (v_booking.id is null or v_booking.member_id<>v_member.id) then raise exception 'BOOKING_NOT_OWNED'; end if;
  select * into v_previous from public.booking_ticket_usage_requests where member_id=v_member.id and request_id=p_request_id;
  if found then
    if v_previous.booking_id is distinct from p_booking_id or v_previous.benefit_kind<>p_kind or v_previous.ticket_refs<>v_refs then raise exception 'REQUEST_ID_CONFLICT'; end if;
    return v_previous.result||jsonb_build_object('alreadyApplied',true);
  end if;
  if p_booking_id is not null and (v_booking.status<>'confirmed' or v_booking.completed_at is not null) then raise exception 'BOOKING_TICKET_CONFIRMATION_REQUIRED'; end if;
  if v_booking.cancellation_requested_at is not null and v_booking.cancellation_reviewed_at is null then raise exception 'BOOKING_CANCELLATION_PENDING'; end if;

  if p_kind='points' then
    perform 1 from public.point_tickets where member_id=v_member.id and ticket_id=any(v_refs) order by ticket_id for update;
  else
    perform 1 from public.event_ticket_claims where member_id=v_member.id and claim_id=any(v_refs) order by claim_id for update;
  end if;
  if exists(select 1 from public.booking_benefit_selections s where s.member_id=v_member.id and s.benefit_kind=p_kind and s.benefit_ref=any(v_refs) and s.status='pending') then
    raise exception 'BOOKING_BENEFIT_RESERVED';
  end if;
  foreach v_ref in array v_refs loop
    if (p_booking_id is null and public.ticket_has_service_requirement(v_member.id,p_kind,v_ref))
      then raise exception 'BOOKING_TICKET_CONFIRMATION_REQUIRED'; end if;
    if (p_booking_id is not null and not public.booking_ticket_matches_services(p_booking_id,v_member.id,p_kind,v_ref))
  then raise exception 'BOOKING_BENEFIT_SERVICE_REQUIRED'; end if;
  end loop;

  if p_kind='points' then
    v_result:=public.redeem_point_tickets_with_location(p_line_user_id,v_refs,'BTU_'||md5(v_member.id::text||p_request_id),p_location);
  else
    v_result:=public.redeem_event_tickets_with_location(p_line_user_id,v_refs,'BTU_'||md5(v_member.id::text||p_request_id),p_location);
  end if;
  foreach v_ref in array v_refs loop
    if p_booking_id is null then continue; end if;
    insert into public.booking_benefit_selections(booking_id,member_id,benefit_kind,benefit_ref,title_snapshot,status,redeemed_at,redeemed_by,result)
    values(p_booking_id,v_member.id,p_kind,v_ref,coalesce(
      case when p_kind='points' then (select ticket_title from public.point_tickets where ticket_id=v_ref and member_id=v_member.id)
        else (select ticket_title from public.event_ticket_claims where claim_id=v_ref and member_id=v_member.id) end,''),
      'redeemed',now(),p_line_user_id,v_result)
    on conflict(booking_id,benefit_kind,benefit_ref) do update set status='redeemed',redeemed_at=excluded.redeemed_at,redeemed_by=excluded.redeemed_by,result=excluded.result
      where booking_benefit_selections.status='cancelled';
  end loop;
  insert into public.booking_ticket_usage_requests values(v_member.id,p_request_id,p_booking_id,p_kind,v_refs,v_result,now());
  insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
    values(p_line_user_id,'member','BOOKING_TICKETS_REDEEMED',case when p_booking_id is null then 'ticket_batch' else 'booking' end,coalesce(p_booking_id::text,p_request_id),'success',jsonb_build_object('kind',p_kind,'refs',v_refs,'requestId',p_request_id));
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_point_ticket(p_line_user_id text, p_ticket_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member public.members%rowtype;
  v_ticket public.point_tickets%rowtype;
  v_card public.point_cards%rowtype;
  v_balance public.point_balances%rowtype;
  v_result jsonb := null;
  v_entry_id uuid;
begin
  select * into v_member from public.members
  where line_user_id=p_line_user_id and membership_status='active' and status='active';
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  select * into v_ticket from public.point_tickets
  where ticket_id=p_ticket_id and member_id=v_member.id for update;
  if not found then raise exception 'TICKET_NOT_FOUND'; end if;
  if v_ticket.status='used' then
    return jsonb_build_object('ticketId',v_ticket.ticket_id,'alreadyUsed',true);
  end if;
  if v_ticket.status <> 'available' then raise exception 'TICKET_NOT_AVAILABLE'; end if;

  select * into v_card from public.point_cards where id=v_ticket.point_card_id for update;
  if not found or v_card.status <> 'active' then raise exception 'POINT_CARD_NOT_AVAILABLE'; end if;
  if v_card.expiry_mode='date' and v_card.expires_on < (clock_timestamp() at time zone 'Asia/Taipei')::date then
    raise exception 'POINT_CARD_EXPIRED';
  end if;

  select * into v_balance from public.point_balances
  where member_id=v_member.id and point_card_id=v_ticket.point_card_id for update;
  if not found or v_balance.stamps < v_ticket.threshold_stamps then raise exception 'INSUFFICIENT_POINTS'; end if;

  if v_ticket.ticket_type='lottery' then v_result := public.pick_lottery_prize(v_ticket.prizes); end if;

  update public.point_balances
  set stamps=stamps-v_ticket.threshold_stamps,updated_at=now()
  where member_id=v_member.id and point_card_id=v_ticket.point_card_id;

  insert into public.point_entries(entry_id,member_id,point_card_id,amount,note,created_by,request_id,entry_type,reference_type,reference_id)
  values(public.new_public_id('PE'),v_member.id,v_ticket.point_card_id,-v_ticket.threshold_stamps,'票券核銷',v_member.line_user_id,
    'redeem:'||v_ticket.ticket_id,'redeem','point_ticket',v_ticket.ticket_id)
  returning id into v_entry_id;

  update public.point_tickets
  set status='used',used_at=now(),result=v_result,points_spent=v_ticket.threshold_stamps,redeem_entry_id=v_entry_id,updated_at=now()
  where id=v_ticket.id;

  perform public.issue_eligible_point_tickets(v_member.id,v_ticket.point_card_id);

  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
  values(public.new_public_id('AUD'),v_member.line_user_id,'member','user.pointcard.ticket.redeem','point_ticket',v_ticket.ticket_id,'success',
    jsonb_build_object('pointsSpent',v_ticket.threshold_stamps));

  return jsonb_build_object('ticketId',v_ticket.ticket_id,'balanceCardId',v_card.card_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_point_ticket_with_location(p_line_user_id text, p_ticket_id text, p_location jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member_id uuid;
  v_ticket public.point_tickets%rowtype;
begin
  select id into v_member_id
  from public.members
  where line_user_id = p_line_user_id
    and membership_status = 'active'
    and status = 'active';

  if found then
    select * into v_ticket
    from public.point_tickets
    where ticket_id = p_ticket_id
      and member_id = v_member_id;

    if found and v_ticket.status = 'available' and v_ticket.requires_location then
      perform public.verify_ticket_redemption_locations(v_ticket.redemption_locations,p_location);
    end if;
  end if;

  return public.redeem_point_ticket(p_line_user_id,p_ticket_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_point_tickets(p_line_user_id text, p_ticket_ids text[], p_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member public.members%rowtype;
  v_ticket public.point_tickets%rowtype;
  v_card public.point_cards%rowtype;
  v_balance public.point_balances%rowtype;
  v_result jsonb := null;
  v_entry_id uuid;
  v_selected_count integer := 0;
  v_total_points integer := 0;
  v_processed integer := 0;
  v_global_max_tickets integer := 1;
  v_points_by_card jsonb := '{}'::jsonb;
  v_existing jsonb;
begin
  if p_request_id is null or p_request_id !~ '^[A-Za-z0-9_-]{8,120}$' then raise exception 'INVALID_REQUEST_ID'; end if;
  if p_ticket_ids is null or cardinality(p_ticket_ids) < 1 or cardinality(p_ticket_ids) > 50 then raise exception 'INVALID_TICKET_BATCH'; end if;
  if exists(select 1 from unnest(p_ticket_ids) as selected(ticket_id) where nullif(btrim(selected.ticket_id),'') is null) then raise exception 'INVALID_TICKET_BATCH'; end if;
  if (select count(distinct selected.ticket_id) from unnest(p_ticket_ids) as selected(ticket_id)) <> cardinality(p_ticket_ids) then raise exception 'INVALID_TICKET_BATCH'; end if;

  select max_tickets_per_redemption into v_global_max_tickets
  from public.point_card_settings
  where id = 1;
  v_global_max_tickets := coalesce(v_global_max_tickets, 1);
  if v_global_max_tickets > 0 and cardinality(p_ticket_ids) > v_global_max_tickets then raise exception 'TICKET_BATCH_LIMIT_EXCEEDED'; end if;

  select * into v_member from public.members
  where line_user_id=p_line_user_id and membership_status='active' and status='active';
  if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  select detail into v_existing
  from public.audit_logs
  where actor_line_user_id=v_member.line_user_id
    and action='user.pointcard.tickets.redeem'
    and target_type='point_ticket_batch'
    and target_id=p_request_id
    and result='success'
  order by created_at desc
  limit 1;
  if found then
    return coalesce(v_existing,'{}'::jsonb) || jsonb_build_object('requestId',p_request_id,'alreadyApplied',true);
  end if;

  perform 1 from public.point_tickets pt
  where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids)
  order by pt.ticket_id
  for update;

  select count(*) into v_selected_count from public.point_tickets pt
  where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids);
  if v_selected_count <> cardinality(p_ticket_ids) then raise exception 'TICKET_NOT_FOUND'; end if;
  if exists(select 1 from public.point_tickets pt where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids) and pt.status <> 'available') then
    raise exception 'TICKET_NOT_AVAILABLE';
  end if;

  perform 1 from public.point_cards pc
  where pc.id in (select pt.point_card_id from public.point_tickets pt where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids))
  order by pc.id
  for update;

  for v_card in
    select pc.* from public.point_cards pc
    where pc.id in (select pt.point_card_id from public.point_tickets pt where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids))
    order by pc.id
  loop
    if v_card.status <> 'active' then raise exception 'POINT_CARD_NOT_AVAILABLE'; end if;
    if v_card.expiry_mode='date' and v_card.expires_on < (clock_timestamp() at time zone 'Asia/Taipei')::date then raise exception 'POINT_CARD_EXPIRED'; end if;

    select coalesce(sum(pt.threshold_stamps),0)::integer
      into v_total_points
    from public.point_tickets pt
    where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids) and pt.point_card_id=v_card.id;

    select * into v_balance from public.point_balances
    where member_id=v_member.id and point_card_id=v_card.id
    for update;
    if not found or v_balance.stamps < v_total_points then raise exception 'INSUFFICIENT_POINTS'; end if;
  end loop;

  for v_ticket in
    select pt.* from public.point_tickets pt
    where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids)
    order by pt.point_card_id,pt.ticket_id
  loop
    v_result := null;
    if v_ticket.ticket_type='lottery' then v_result := public.pick_lottery_prize(v_ticket.prizes); end if;

    update public.point_balances
    set stamps=stamps-v_ticket.threshold_stamps,updated_at=now()
    where member_id=v_member.id and point_card_id=v_ticket.point_card_id;

    insert into public.point_entries(entry_id,member_id,point_card_id,amount,note,created_by,request_id,entry_type,reference_type,reference_id)
    values(public.new_public_id('PE'),v_member.id,v_ticket.point_card_id,-v_ticket.threshold_stamps,'票券批次核銷',v_member.line_user_id,
      p_request_id||':'||v_ticket.ticket_id,'redeem','point_ticket',v_ticket.ticket_id)
    returning id into v_entry_id;

    update public.point_tickets
    set status='used',used_at=now(),result=v_result,points_spent=v_ticket.threshold_stamps,redeem_entry_id=v_entry_id,updated_at=now()
    where id=v_ticket.id;
    v_processed := v_processed + 1;
  end loop;

  for v_card in
    select pc.* from public.point_cards pc
    where pc.id in (select pt.point_card_id from public.point_tickets pt where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids))
    order by pc.id
  loop
    perform public.issue_eligible_point_tickets(v_member.id,v_card.id);
  end loop;

  select coalesce(jsonb_object_agg(totals.card_id,totals.points_spent),'{}'::jsonb)
    into v_points_by_card
  from (
    select pc.card_id,sum(pt.threshold_stamps)::integer as points_spent
    from public.point_tickets pt join public.point_cards pc on pc.id=pt.point_card_id
    where pt.member_id=v_member.id and pt.ticket_id=any(p_ticket_ids)
    group by pc.card_id
  ) totals;

  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
  values(public.new_public_id('AUD'),v_member.line_user_id,'member','user.pointcard.tickets.redeem','point_ticket_batch',p_request_id,'success',
    jsonb_build_object('requestId',p_request_id,'ticketIds',to_jsonb(p_ticket_ids),'ticketCount',v_processed,'pointsByCard',v_points_by_card,'globalMaxTicketsPerRedemption',v_global_max_tickets,'alreadyApplied',false));

  return jsonb_build_object('requestId',p_request_id,'ticketIds',to_jsonb(p_ticket_ids),'ticketCount',v_processed,'pointsByCard',v_points_by_card,'globalMaxTicketsPerRedemption',v_global_max_tickets,'alreadyApplied',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.reevaluate_fixed_tickets_for_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member_id uuid;
begin
  v_member_id := case when tg_op = 'DELETE' then old.member_id else new.member_id end;
  if v_member_id is not null then
    perform public.issue_fixed_tickets(
      (clock_timestamp() at time zone 'Asia/Taipei')::date,
      v_member_id,
      null
    );
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_accessible_receipt_with_benefits_request(p_receipt_id text, p_expected_receipt_updated_at timestamp with time zone, p_actor text, p_booking_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_benefits jsonb, p_admin_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r public.booking_receipts%rowtype;
  b public.bookings%rowtype;
  m public.members%rowtype;
  s public.booking_services%rowtype;
  settings public.booking_settings%rowtype;
  item jsonb;
  minutes integer;
  quantity integer;
  total integer := 0;
  participant uuid;
  store_id constant uuid := '00000000-0000-4000-8000-000000000010';
  store public.booking_services%rowtype;
  start_at timestamp;
  settlement jsonb;
begin
  perform 1 from public.admins where line_user_id = p_actor and role = 'admin' and status = 'active';
  if not found then raise exception 'ADMIN_REQUIRED'; end if;

  p_benefits := coalesce(p_benefits, '[]'::jsonb);
  if jsonb_typeof(p_benefits) <> 'array' or jsonb_array_length(p_benefits) > 20 then
    raise exception 'INVALID_BOOKING_BENEFITS';
  end if;

  select * into r from public.booking_receipts where receipt_id = p_receipt_id;
  if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;

  select * into m from public.members where id = r.member_id for update;
  if m.status <> 'active' or m.membership_status <> 'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;

  select * into r from public.booking_receipts where receipt_id = p_receipt_id for update;
  if r.submission_mode <> 'accessible' then raise exception 'RECEIPT_NOT_PENDING'; end if;

  if r.status = 'bound' then
    select jsonb_build_object(
      'bookingId', booking_id,
      'serviceMinutes', service_minutes,
      'rewards', reward_details
    )
      into settlement
    from public.booking_completion_settlements
    where booking_id = r.booking_id;

    return jsonb_build_object(
      'bookingId', r.booking_id,
      'receiptId', r.receipt_id,
      'settlement', settlement,
      'alreadyApplied', true
    );
  end if;

  if r.status <> 'awaiting_review' or r.booking_id is not null then raise exception 'RECEIPT_NOT_PENDING'; end if;
  if p_expected_receipt_updated_at is null or r.updated_at <> p_expected_receipt_updated_at then raise exception 'BOOKING_CONFLICT'; end if;

  if p_booking_id is not null then
    select * into b from public.bookings where id = p_booking_id for update;
    if not found or b.member_id <> r.member_id then raise exception 'BOOKING_NOT_OWNED'; end if;
    if b.status not in ('confirmed', 'completed') then raise exception 'INVALID_BOOKING_TRANSITION'; end if;
    if b.end_at > (clock_timestamp() at time zone 'Asia/Taipei') then raise exception 'BOOKING_NOT_FINISHED_YET'; end if;
    if exists(
      select 1
      from public.booking_receipts
      where booking_id = b.id
        and status in ('pending_upload', 'awaiting_review', 'bound')
    ) then
      raise exception 'BOOKING_ALREADY_COMPLETED_WITH_RECEIPT';
    end if;
  else
    if p_booking_date is null or p_start_time is null or extract(second from p_start_time) <> 0 then
      raise exception 'INVALID_BOOKING_SLOT';
    end if;
    if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 20 then
      raise exception 'INVALID_BOOKING_ITEMS';
    end if;
    if (select count(distinct x->>'serviceId') from jsonb_array_elements(p_items) x) <> jsonb_array_length(p_items) then
      raise exception 'INVALID_BOOKING_ITEMS';
    end if;

    select * into settings from public.booking_settings where id = 1 for share;
    if settings.require_primary_technician and settings.primary_technician_id is null then raise exception 'BOOKING_PRIMARY_TECHNICIAN_MISSING'; end if;
    if settings.primary_technician_id is not null then
    perform 1 from public.booking_technicians where id = settings.primary_technician_id and is_active;
    if not found then raise exception 'BOOKING_PRIMARY_TECHNICIAN_MISSING'; end if;
    end if;

    select * into store
    from public.booking_services
    where id = store_id and is_active and deleted_at is null;
    if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;

    for item in select value from jsonb_array_elements(p_items) loop
      select * into s
      from public.booking_services
      where id = (item->>'serviceId')::uuid
        and is_active
        and deleted_at is null
        and id <> store_id
      for share;
      if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;

      minutes := (item->>'minutes')::integer;
      quantity := (item->>'quantity')::integer;
      if minutes is null or minutes not between 1 and 720 or quantity is null or quantity not between 1 and 20 then
        raise exception 'INVALID_BOOKING_ITEMS';
      end if;
      total := total + minutes * quantity;
    end loop;

    total := total + store.duration_minutes;
    if total not between 1 and 1439 then raise exception 'INVALID_BOOKING_DURATION'; end if;

    start_at := p_booking_date + p_start_time
      + case
          when settings.work_end_time < settings.work_start_time and p_start_time < settings.work_end_time
            then interval '1 day'
          else interval '0 days'
        end;
    if start_at + make_interval(mins => total) > (clock_timestamp() at time zone 'Asia/Taipei') then
      raise exception 'BOOKING_NOT_FINISHED_YET';
    end if;

    insert into public.bookings(
      request_id, service_id, member_id, booking_date, start_time, end_time, status,
      total_duration_minutes, technician_id, party_size, confirmed_by, confirmed_at, receipt_submission_id,
      contact_source, contact_surname, contact_salutation, contact_phone
    )
    values(
      'receipt-register:' || r.id::text,
      (p_items->0->>'serviceId')::uuid,
      r.member_id,
      p_booking_date,
      p_start_time,
      (p_start_time + make_interval(mins => total))::time,
      'confirmed',
      total,
      settings.primary_technician_id,
      1,
      p_actor,
      now(),
      r.receipt_id,
      'member',
      m.surname,
      m.salutation,
      m.phone
    )
    returning * into b;

    insert into public.booking_participants(booking_id, position, technician_id)
    values(b.id, 1, settings.primary_technician_id)
    returning id into participant;

    for item in select value from jsonb_array_elements(p_items) loop
      select * into s from public.booking_services where id = (item->>'serviceId')::uuid;

      insert into public.booking_items(
        booking_id, service_id, service_title, unit_duration_minutes, quantity,
        unit_price_amount, service_type, counts_toward_membership
      )
      values(
        b.id, s.id, s.title, (item->>'minutes')::integer, (item->>'quantity')::integer,
        s.price_amount, s.service_type, s.counts_toward_membership
      );

      insert into public.booking_participant_items(
        participant_id, service_id, service_title, unit_duration_minutes, unit_price_amount, quantity
      )
      values(
        participant, s.id, s.title, (item->>'minutes')::integer, s.price_amount, (item->>'quantity')::integer
      );
    end loop;

    insert into public.booking_items(
      booking_id, service_id, service_title, unit_duration_minutes, quantity,
      unit_price_amount, service_type, counts_toward_membership
    )
    values(b.id, store.id, store.title, store.duration_minutes, 1, store.price_amount, store.service_type, false);

    insert into public.booking_participant_items(
      participant_id, service_id, service_title, unit_duration_minutes, unit_price_amount, quantity
    )
    values(participant, store.id, store.title, store.duration_minutes, store.price_amount, 1);
  end if;

  if b.status = 'confirmed' then
    perform public.replace_booking_benefit_selections_request(
      b.id,
      r.member_id,
      p_benefits
    );
  elsif jsonb_array_length(p_benefits) > 0 then
    raise exception 'BOOKING_NOT_EDITABLE';
  end if;

  update public.booking_receipts set booking_id = b.id where id = r.id;

  if b.status = 'completed' then
    select jsonb_build_object(
      'bookingId', booking_id,
      'serviceMinutes', service_minutes,
      'rewards', reward_details
    )
      into settlement
    from public.booking_completion_settlements
    where booking_id = b.id;
    if settlement is null then raise exception 'BOOKING_COMPLETION_REQUIRES_SETTLEMENT'; end if;
    update public.booking_receipts
    set status = 'bound', bound_at = now(), updated_at = now()
    where id = r.id;
  else
    settlement := public.admin_confirm_booking_receipt_request(
      b.id,
      b.updated_at,
      p_actor,
      left(coalesce(p_admin_note, ''), 500)
    )->'settlement';
  end if;

  insert into public.audit_logs(
    audit_id, actor_line_user_id, actor_role, action, target_type, target_id, result, detail
  )
  values(
    public.new_public_id('AUD'),
    p_actor,
    'admin',
    'admin.booking.receipt.register',
    'booking',
    b.id::text,
    'success',
    jsonb_build_object(
      'receiptId', r.receipt_id,
      'linkedExisting', p_booking_id is not null,
      'benefitCount', jsonb_array_length(p_benefits)
    )
  );

  return jsonb_build_object(
    'bookingId', b.id,
    'receiptId', r.receipt_id,
    'settlement', settlement,
    'alreadyApplied', false
  );
end
$function$

CREATE OR REPLACE FUNCTION public.register_snapshot_receipt_v2(p_receipt_id text, p_expected_receipt_updated_at timestamp with time zone, p_actor text, p_booking_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_benefits jsonb, p_admin_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.booking_receipts%rowtype;
 v_item jsonb; v_ref text; v_new_id text; v_selection_id uuid; v_future_booking_id uuid;
begin
 if not exists(select 1 from public.admins where line_user_id=p_actor and role='admin' and status='active') then raise exception 'ADMIN_REQUIRED'; end if;
 if p_booking_id is not null then perform 1 from public.bookings where id=p_booking_id for update; end if;
 select * into r from public.booking_receipts where receipt_id=p_receipt_id;
 if not found then raise exception 'RECEIPT_NOT_FOUND'; end if;
 perform set_config('app.snapshot_receipt_id',r.receipt_id,true);
 perform 1 from public.members where id=r.member_id for update;
 select * into r from public.booking_receipts where receipt_id=p_receipt_id for update;
 perform 1 from public.booking_settings where id=1 for share;
 if r.status='awaiting_review' and jsonb_array_length(coalesce(p_benefits,'[]'::jsonb))>0 then
   -- Snapshot receipts are retrospective; admin reviews actual services later.
   -- Keep ownership, validity, point budget and ticket limits enforced.
   perform public.validate_snapshot_ticket_selection(r.member_id,null,p_benefits,r.receipt_id);
   -- Validate optimistic version BEFORE modifying future reservations.
   if r.updated_at is distinct from p_expected_receipt_updated_at then
     raise exception 'BOOKING_CONFLICT';
   end if;
   for v_item in select value from jsonb_array_elements(p_benefits) loop
     if v_item->>'kind'<>'points' then continue; end if;
     v_ref:=v_item->>'id';
     v_selection_id:=null;
     v_future_booking_id:=null;
     select s.id,s.booking_id into v_selection_id,v_future_booking_id
     from public.booking_benefit_selections s
     where s.member_id=r.member_id and s.benefit_kind='points'
       and s.benefit_ref=v_ref and s.status='pending'
     for update;
     if not found then continue; end if;
     perform 1 from public.bookings b
     where b.id=v_future_booking_id and b.member_id=r.member_id
       and b.status in ('pending','confirmed') and b.completed_at is null
       and b.start_at>(clock_timestamp() at time zone 'Asia/Taipei')
     for update;
     if not found then raise exception 'BOOKING_BENEFIT_RESERVED'; end if;
     -- Keep the issued ticket for today's reviewed snapshot. Rebind the
     -- later booking to a distinct issued instance of the same reward.
     -- Both debit the same balance, but the validator already proved
     -- that today's spend is covered on top of all reserved points.
     v_new_id:=public.new_public_id('PT');
     insert into public.point_tickets(
       ticket_id,member_id,point_card_id,reward_id,ticket_template_id,
       threshold_stamps,ticket_type,ticket_title,ticket_description,
       usage_method,usage_instructions,prizes,requires_location,
       redemption_locations,snapshot_reservation_copy_of
     )
     select v_new_id,t.member_id,t.point_card_id,t.reward_id,t.ticket_template_id,
       t.threshold_stamps,t.ticket_type,t.ticket_title,t.ticket_description,
       t.usage_method,t.usage_instructions,t.prizes,t.requires_location,
       t.redemption_locations,t.ticket_id
     from public.point_tickets t
     where t.member_id=r.member_id and t.ticket_id=v_ref and t.status='available'
     for update;
     if not found then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;
     update public.booking_benefit_selections
     set benefit_ref=v_new_id
     where id=v_selection_id and member_id=r.member_id
       and benefit_kind='points' and benefit_ref=v_ref and status='pending';
     if not found then raise exception 'BOOKING_CONFLICT'; end if;
     insert into public.audit_logs(
       audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail
     ) values (
       public.new_public_id('AUD'),p_actor,'admin',
       'admin.booking.receipt.snapshot.reservation-rebind',
       'booking_benefit_selection',v_selection_id::text,'success',
       jsonb_build_object('receiptId',r.receipt_id,'futureBookingId',v_future_booking_id,
         'snapshotTicketId',v_ref,'futureTicketId',v_new_id)
     );
   end loop;
 end if;
 return public.register_accessible_receipt_with_benefits_request(p_receipt_id,p_expected_receipt_updated_at,p_actor,p_booking_id,p_booking_date,p_start_time,p_items,p_benefits,p_admin_note);
end $function$

CREATE OR REPLACE FUNCTION public.reorder_point_cards(p_actor_line_user_id text, p_orders jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_item jsonb; v_expected timestamptz;
begin
  if jsonb_typeof(p_orders) <> 'array' then raise exception 'INVALID_CARD_ORDERS'; end if;
  for v_item in select value from jsonb_array_elements(p_orders)
  loop
    v_expected := nullif(v_item->>'expectedUpdatedAt','')::timestamptz;
    if not exists(select 1 from public.point_cards where card_id=v_item->>'cardId' for update) then raise exception 'POINT_CARD_NOT_FOUND'; end if;
    if v_expected is not null and not exists(select 1 from public.point_cards where card_id=v_item->>'cardId' and updated_at=v_expected) then raise exception 'CONFLICT'; end if;
  end loop;
  for v_item in select value from jsonb_array_elements(p_orders)
  loop
    update public.point_cards set sort_order=(v_item->>'sortOrder')::integer,updated_by=p_actor_line_user_id,updated_at=now()
    where card_id=v_item->>'cardId';
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.replace_booking_benefit_selections_request(p_booking_id uuid, p_member_id uuid, p_selections jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_item jsonb;
  v_kind text;
  v_ref text;
  v_title text;
  v_today date := (clock_timestamp() at time zone 'Asia/Taipei')::date;
  v_tier text;
  v_birthday date;
  v_point record;
  v_event record;
  v_calendar record;
begin
  select * into v_booking
  from public.bookings
  where id=p_booking_id and member_id=p_member_id
  for update;

  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if v_booking.status not in ('pending','confirmed') then raise exception 'BOOKING_NOT_EDITABLE'; end if;

  p_selections := coalesce(p_selections,'[]'::jsonb);
  if jsonb_typeof(p_selections) <> 'array' or jsonb_array_length(p_selections) > 20 then
    raise exception 'INVALID_BOOKING_BENEFITS';
  end if;

  if exists (
    select 1
    from (
      select lower(btrim(value->>'kind')) as kind, btrim(value->>'id') as ref, count(*) as qty
      from jsonb_array_elements(p_selections)
      group by 1,2
      having count(*) > 1
    ) duplicated
  ) then
    raise exception 'INVALID_BOOKING_BENEFITS';
  end if;

  perform public.reconcile_booking_ticket_services(p_booking_id);
  select coalesce(jsonb_agg(item),'[]'::jsonb) into p_selections
  from jsonb_array_elements(p_selections) item
  where not exists(select 1 from public.booking_benefit_selections s
    where s.booking_id=p_booking_id and s.member_id=p_member_id
      and s.benefit_kind=lower(btrim(item->>'kind')) and s.benefit_ref=btrim(item->>'id')
      and s.status='cancelled' and s.result->>'cancellationReason'='booking_services_changed'
      and not public.booking_ticket_matches_services(p_booking_id,p_member_id,s.benefit_kind,s.benefit_ref));

  delete from public.booking_benefit_selections
  where booking_id=p_booking_id and status='pending';

  v_tier := public.current_tier_key(p_member_id);
  select birthday into v_birthday from public.members where id=p_member_id;

  for v_item in select value from jsonb_array_elements(p_selections)
  loop
    v_kind := lower(btrim(coalesce(v_item->>'kind','')));
    v_ref := btrim(coalesce(v_item->>'id',''));
    if v_kind not in ('points','event','calendar') or v_ref = '' or length(v_ref) > 160 then
      raise exception 'INVALID_BOOKING_BENEFITS';
    end if;

    v_title := '';

    if v_kind='points' then
      select
        pt.ticket_title,
        pc.title as card_title,
        pt.status as ticket_status,
        pt.requires_location,
        pc.status as card_status,
        pc.expiry_mode,
        pc.expires_on
      into v_point
      from public.point_tickets pt
      join public.point_cards pc on pc.id=pt.point_card_id
      where pt.member_id=p_member_id and pt.ticket_id=v_ref
      for update of pt,pc;

      if not found or v_point.ticket_status <> 'available' or v_point.card_status <> 'active' then
        raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
      end if;
      if v_point.expiry_mode='date' and (v_point.expires_on is null or v_point.expires_on < v_today) then
        raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
      end if;
      v_title := concat_ws(
        '｜',
        nullif(btrim(coalesce(v_point.card_title,'')),''),
        coalesce(nullif(btrim(coalesce(v_point.ticket_title,'')),''),'集點卡票券')
      );

    elsif v_kind='event' then
      select
        c.ticket_title,
        c.status as claim_status,
        e.status as event_status,
        e.deleted_at,
        e.starts_on,
        e.ends_on,
        e.allowed_tier_keys,
        e.requires_location
      into v_event
      from public.event_ticket_claims c
      join public.event_tickets e on e.id=c.event_ticket_id
      where c.member_id=p_member_id and c.claim_id=v_ref
      for update of c,e;

      if not found or v_event.claim_status <> 'claimed'
         or v_event.event_status <> 'active' or v_event.deleted_at is not null then
        raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
      end if;
      if v_event.starts_on is not null and v_today < v_event.starts_on then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;
      if v_event.ends_on is not null and v_today > v_event.ends_on then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;
      if coalesce(cardinality(v_event.allowed_tier_keys),0) > 0 and not coalesce(v_tier = any(v_event.allowed_tier_keys),false) then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;
      v_title := coalesce(v_event.ticket_title,'活動票券');

    else
      select ci.* into v_calendar
      from public.calendar_items ci
      where ci.calendar_item_id=v_ref and ci.item_type='event';

      if not found then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;
      if v_calendar.starts_on > v_booking.booking_date
         or coalesce(v_calendar.ends_on,v_calendar.starts_on) < v_booking.booking_date then
        raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
      end if;
      if cardinality(v_calendar.allowed_tier_keys) > 0
         and not (v_tier = any(v_calendar.allowed_tier_keys)) then
        raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
      end if;
      if coalesce(v_calendar.audience_type,'all')='birthday_month' then
        if v_calendar.status <> 'targeted'
           or v_birthday is null
           or extract(month from v_birthday)::int <> v_calendar.audience_month then
          raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
        end if;
      elsif v_calendar.status <> 'active' then
        raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE';
      end if;
      v_title := coalesce(v_calendar.title,'會員活動');
    end if;

    insert into public.booking_benefit_selections(
      booking_id,member_id,benefit_kind,benefit_ref,title_snapshot,status
    ) values (
      p_booking_id,p_member_id,v_kind,v_ref,left(v_title,200),'pending'
    ) on conflict (booking_id,benefit_kind,benefit_ref) do update
      set status='pending',selected_at=now(),title_snapshot=excluded.title_snapshot,result=null
      where booking_benefit_selections.status='cancelled';
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.replace_completed_booking_items(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_participants jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  b public.bookings%rowtype;
  cfg public.booking_settings%rowtype;
  participant public.booking_participants%rowtype;
  service public.booking_services%rowtype;
  person jsonb;
  item jsonb;
  v_service_id uuid;
  primary_service_id uuid;
  v_quantity integer;
  v_position integer;
  seen_positions integer[] := '{}';
  seen_services uuid[];
  participant_count integer;
  store_minutes integer;
  minutes integer;
  max_minutes integer := 0;
  total_minutes integer;
  v_end_time time;
  before_items jsonb; before_booking_items jsonb;
begin
  if not exists (
    select 1 from public.admins as a
    where a.line_user_id = p_actor and a.role = 'admin' and a.status = 'active'
  ) then raise exception 'ADMIN_REQUIRED'; end if;

  select bk.* into b from public.bookings as bk where bk.id = p_booking_id for update;
  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if p_expected_updated_at is null or b.updated_at <> p_expected_updated_at then raise exception 'BOOKING_CONFLICT'; end if;
  if b.status<>'completed' then raise exception 'BOOKING_NOT_EDITABLE'; end if;
  if b.cancellation_requested_at is not null and b.cancellation_reviewed_at is null then raise exception 'BOOKING_CANCELLATION_PENDING'; end if;

  select bs.* into cfg from public.booking_settings as bs where bs.id = 1 for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;

  select count(*) into participant_count
  from public.booking_participants as bp_count
  where bp_count.booking_id = b.id;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
  if participant_count < 1 or participant_count <> b.party_size or jsonb_array_length(p_participants) <> participant_count then
    raise exception 'INVALID_BOOKING_PARTICIPANTS';
  end if;

  select coalesce(jsonb_agg(to_jsonb(bpi_before) order by bp_before.position,bpi_before.service_id),'[]'::jsonb)
  into before_items
  from public.booking_participant_items as bpi_before
  join public.booking_participants as bp_before on bp_before.id = bpi_before.participant_id
  where bp_before.booking_id = b.id;

  select jsonb_agg(to_jsonb(i)) into before_booking_items from public.booking_items i where i.booking_id=b.id;
  select sum(bi_store.unit_duration_minutes * bi_store.quantity)::integer
  into store_minutes
  from public.booking_items as bi_store
  where bi_store.booking_id = b.id
    and bi_store.service_id = '00000000-0000-4000-8000-000000000010'::uuid;
  if store_minutes is null then raise exception 'INVALID_BOOKING_ITEMS'; end if;

  for person in select j.value from jsonb_array_elements(p_participants) as j(value) loop
    if coalesce(person->>'position','') !~ '^[1-9][0-9]?$' then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
    v_position := (person->>'position')::integer;
    if v_position = any(seen_positions) then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
    seen_positions := array_append(seen_positions,v_position);

    select bp.* into participant
    from public.booking_participants as bp
    where bp.booking_id = b.id and bp.position = v_position
    for update;
    if not found then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;

    if jsonb_typeof(person->'items') is distinct from 'array' then raise exception 'INVALID_BOOKING_ITEMS'; end if;
    if jsonb_array_length(person->'items') not between 0 and 20 then raise exception 'INVALID_BOOKING_ITEMS'; end if;

    minutes := 0;
    seen_services := '{}';
    delete from public.booking_participant_items as bpi_delete
    where bpi_delete.participant_id = participant.id;

    for item in select j.value from jsonb_array_elements(person->'items') as j(value) loop
      begin v_service_id := (item->>'serviceId')::uuid;
      exception when invalid_text_representation then raise exception 'INVALID_BOOKING_ITEMS'; end;
      if v_service_id is null then raise exception 'INVALID_BOOKING_ITEMS'; end if;
      if coalesce(item->>'quantity','') !~ '^[12]$' then raise exception 'INVALID_BOOKING_QUANTITY'; end if;
      v_quantity := (item->>'quantity')::integer;
      if v_service_id = '00000000-0000-4000-8000-000000000010'::uuid then raise exception 'BOOKING_SYSTEM_SERVICE_IMMUTABLE'; end if;
      if v_service_id = any(seen_services) then raise exception 'DUPLICATE_BOOKING_SERVICE'; end if;
      seen_services := array_append(seen_services,v_service_id);

      select bs.* into service
      from public.booking_services as bs
      where bs.id = v_service_id and (bs.deleted_at is null or exists(select 1 from jsonb_array_elements(before_items) old where old->>'service_id'=v_service_id::text))
      for share;
      if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;

      if primary_service_id is null then primary_service_id := service.id; end if;
      if item ? 'minutes' and (jsonb_typeof(item->'minutes')<>'number' or (item->>'minutes')!~'^[1-9][0-9]*$' or (item->>'minutes')::integer>720) then raise exception 'INVALID_BOOKING_ITEMS'; end if;
      select coalesce((old->>'unit_price_amount')::integer,service.price_amount),coalesce(old->>'service_title',service.title) into service.price_amount,service.title from (select (select value from jsonb_array_elements(before_items) where value->>'participant_id'=participant.id::text and value->>'service_id'=service.id::text limit 1) old) snapshot;
      service.duration_minutes:=coalesce((item->>'minutes')::integer,service.duration_minutes);
      minutes := minutes + service.duration_minutes * v_quantity;

      insert into public.booking_participant_items(participant_id,service_id,service_title,unit_duration_minutes,unit_price_amount,quantity)
      values(participant.id,service.id,service.title,service.duration_minutes,service.price_amount,v_quantity);
    end loop;

    max_minutes := greatest(max_minutes,minutes);
    if minutes < 0 or minutes >= 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;

    if false then
      insert into public.booking_participant_reservations(participant_id,booking_id,technician_id,booking_date,start_time,end_time,is_active)
      values(participant.id,b.id,participant.technician_id,b.booking_date,b.start_time,b.start_time + make_interval(mins => minutes),true)
      on conflict (participant_id) do update set end_time = excluded.end_time, updated_at = now();
    end if;
  end loop;

  total_minutes := max_minutes + store_minutes;
  if total_minutes not between 1 and 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;
  v_end_time := b.start_time + make_interval(mins => total_minutes);
  if false and not public.booking_slot_fits(b.booking_date,b.start_time,total_minutes,cfg.work_start_time,cfg.work_end_time,cfg.slot_interval_minutes) then
    raise exception 'INVALID_BOOKING_SLOT';
  end if;

  delete from public.booking_items as bi_delete
  where bi_delete.booking_id = b.id
    and bi_delete.service_id <> '00000000-0000-4000-8000-000000000010'::uuid;

  insert into public.booking_items(booking_id,service_id,service_title,unit_duration_minutes,unit_price_amount,quantity,service_type,counts_toward_membership)
  select b.id,bpi.service_id,max(bpi.service_title),max(bpi.unit_duration_minutes),max(bpi.unit_price_amount),sum(bpi.quantity)::smallint,
         coalesce((select old->>'service_type' from jsonb_array_elements(before_booking_items) old where old->>'service_id'=bpi.service_id::text limit 1),bs.service_type),coalesce((select (old->>'counts_toward_membership')::boolean from jsonb_array_elements(before_booking_items) old where old->>'service_id'=bpi.service_id::text limit 1),bs.counts_toward_membership)
  from public.booking_participant_items as bpi
  join public.booking_participants as bp on bp.id = bpi.participant_id
  join public.booking_services as bs on bs.id = bpi.service_id
  where bp.booking_id = b.id
  group by bpi.service_id,coalesce((select old->>'service_type' from jsonb_array_elements(before_booking_items) old where old->>'service_id'=bpi.service_id::text limit 1),bs.service_type),coalesce((select (old->>'counts_toward_membership')::boolean from jsonb_array_elements(before_booking_items) old where old->>'service_id'=bpi.service_id::text limit 1),bs.counts_toward_membership);

  update public.bookings as bk
  set service_id = coalesce(primary_service_id,b.service_id),total_duration_minutes = total_minutes,end_time = v_end_time
  where bk.id = b.id
  returning bk.* into b;

  insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata,created_at)
  values(p_actor,'admin','BOOKING_ITEMS_UPDATED','booking',b.id::text,'success',
    jsonb_build_object('previousParticipantItems',before_items,'participants',p_participants,'totalDurationMinutes',total_minutes),b.updated_at);

  return b;
exception when exclusion_violation then raise exception 'BOOKING_SLOT_TAKEN';
end;
$function$

CREATE OR REPLACE FUNCTION public.request_booking_cancellation(p_booking_id uuid, p_member_id uuid, p_actor text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_now timestamptz := now();
  v_today date := (clock_timestamp() at time zone 'Asia/Taipei')::date;
  v_local_time time := (clock_timestamp() at time zone 'Asia/Taipei')::time;
begin
  select * into v_booking
  from public.bookings
  where id = p_booking_id
    and member_id = p_member_id
  for update;

  if not found then
    raise exception 'BOOKING_NOT_FOUND';
  end if;

  if v_booking.cancellation_requested_at is not null
     and v_booking.cancellation_reviewed_at is null then
    return jsonb_build_object(
      'bookingId', v_booking.id,
      'status', v_booking.status,
      'baseStatus', v_booking.status,
      'updatedAt', v_booking.updated_at,
      'alreadyRequested', true
    );
  end if;

  if v_booking.status not in ('pending','confirmed') then
    raise exception 'BOOKING_NOT_CANCELLABLE';
  end if;

  if v_booking.start_at <= (clock_timestamp() at time zone 'Asia/Taipei') then
    raise exception 'BOOKING_TIME_PASSED';
  end if;

  if p_expected_updated_at is not null and v_booking.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;

  update public.bookings
  set cancellation_requested_at = v_now,
      cancellation_requested_by = p_actor,
      cancellation_source_status = v_booking.status,
      cancellation_reviewed_at = null,
      cancellation_reviewed_by = null,
      cancellation_decision = null
  where id = v_booking.id
    and member_id = p_member_id
    and status = v_booking.status
    and updated_at = v_booking.updated_at
  returning * into v_booking;

  if not found then
    raise exception 'BOOKING_CONFLICT';
  end if;

  return jsonb_build_object(
    'bookingId', v_booking.id,
    'status', v_booking.status,
    'baseStatus', v_booking.status,
    'updatedAt', v_booking.updated_at,
    'alreadyRequested', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.require_snapshot_location(p_location jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_required boolean;
  v_locations jsonb;
  v_lat double precision;
  v_lng double precision;
  v_accuracy double precision;
  v_time numeric;
  loc jsonb;
  lat double precision;
  lng double precision;
  radius double precision;
  distance double precision;
begin
  -- Serialize location edits with receipt preparation and finalization.
  select snapshot_location_required,snapshot_locations into v_required,v_locations
    from public.booking_settings where id=1 for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  if not v_required then return; end if;
  if jsonb_typeof(v_locations) <> 'array' or jsonb_array_length(v_locations)=0 then
    raise exception 'SNAPSHOT_LOCATION_NOT_CONFIGURED';
  end if;
  if p_location is null or jsonb_typeof(p_location)<>'object'
     or jsonb_typeof(p_location->'latitude') is distinct from 'number'
     or jsonb_typeof(p_location->'longitude') is distinct from 'number'
     or jsonb_typeof(p_location->'accuracy') is distinct from 'number'
     or jsonb_typeof(p_location->'timestamp') is distinct from 'number'
     then raise exception 'SNAPSHOT_LOCATION_REQUIRED'; end if;
  v_lat := (p_location->>'latitude')::double precision;
  v_lng := (p_location->>'longitude')::double precision;
  v_accuracy := (p_location->>'accuracy')::double precision;
  v_time := (p_location->>'timestamp')::numeric;
  if not (v_lat between -90 and 90) or not (v_lng between -180 and 180)
     or not (v_accuracy between 0 and 2000)
     or v_time < extract(epoch from clock_timestamp())*1000-120000
     or v_time > extract(epoch from clock_timestamp())*1000+30000
     then raise exception 'SNAPSHOT_LOCATION_INVALID'; end if;
  for loc in select value from jsonb_array_elements(v_locations) loop
    lat := (loc->>'latitude')::double precision;
    lng := (loc->>'longitude')::double precision;
    radius := (loc->>'radiusMeters')::double precision;
    distance := 6371000.0*2.0*asin(sqrt(least(1.0,
      power(sin(radians(v_lat-lat)/2.0),2)
      +cos(radians(lat))*cos(radians(v_lat))
       *power(sin(radians(v_lng-lng)/2.0),2))));
    -- Reject inaccurate fixes rather than permitting a broad GPS accuracy
    -- circle to satisfy a small business-configured geofence.
    if distance <= radius and v_accuracy <= radius then return; end if;
  end loop;
  raise exception 'SNAPSHOT_LOCATION_OUT_OF_RANGE';
end $function$

CREATE OR REPLACE FUNCTION public.review_booking_cancellation(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
  v_now timestamptz := now();
  v_source_status text;
begin
  if p_decision not in ('approved','rejected') then
    raise exception 'INVALID_CANCELLATION_DECISION';
  end if;

  select * into v_booking
  from public.bookings
  where id = p_booking_id
  for update;

  if not found then
    raise exception 'BOOKING_NOT_FOUND';
  end if;

  if p_expected_updated_at is null or v_booking.updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_CONFLICT';
  end if;

  if v_booking.cancellation_requested_at is null
     or v_booking.cancellation_reviewed_at is not null then
    raise exception 'CANCELLATION_NOT_PENDING';
  end if;

  if v_booking.status not in ('pending','confirmed')
     or v_booking.status <> v_booking.cancellation_source_status then
    raise exception 'BOOKING_CONFLICT';
  end if;

  v_source_status := v_booking.cancellation_source_status;

  if p_decision = 'approved' then
    update public.bookings
    set status = 'cancelled',
        cancelled_by = p_actor,
        cancelled_at = v_now,
        cancellation_reviewed_at = v_now,
        cancellation_reviewed_by = p_actor,
        cancellation_decision = 'approved'
    where id = v_booking.id
      and status = v_booking.status
      and updated_at = v_booking.updated_at
    returning * into v_booking;
  else
    update public.bookings
    set cancellation_requested_at = null,
        cancellation_requested_by = null,
        cancellation_source_status = null,
        cancellation_reviewed_at = v_now,
        cancellation_reviewed_by = p_actor,
        cancellation_decision = 'rejected'
    where id = v_booking.id
      and status = v_booking.status
      and updated_at = v_booking.updated_at
    returning * into v_booking;
  end if;

  if not found then
    raise exception 'BOOKING_CONFLICT';
  end if;

  return jsonb_build_object(
    'bookingId', v_booking.id,
    'status', v_booking.status,
    'sourceStatus', v_source_status,
    'decision', p_decision,
    'updatedAt', v_booking.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_deleted_fixed_ticket_benefits()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now timestamptz := coalesce(new.deleted_at, now());
  v_cancelled_claims integer := 0;
  v_archived_events integer := 0;
  v_cancelled_messages integer := 0;
  v_prefix text := 'FIXED-' || new.fixed_ticket_id || '-';
begin
  if old.deleted_at is not null or new.deleted_at is null then
    return new;
  end if;

  update public.event_ticket_claims as claim
  set status = 'cancelled',
      updated_at = v_now
  from public.event_tickets as ticket
  where claim.event_ticket_id = ticket.id
    and ticket.fixed_ticket_template_id = new.id
    and claim.status = 'claimed';
  get diagnostics v_cancelled_claims = row_count;

  update public.scheduled_grant_messages
  set status = 'cancelled',
      last_error = 'fixed_ticket_deleted',
      updated_at = v_now
  where created_by = 'fixed-ticket-automation'
    and status in ('pending', 'failed')
    and left(request_id, char_length(v_prefix)) = v_prefix;
  get diagnostics v_cancelled_messages = row_count;

  update public.event_tickets
  set status = 'archived',
      deleted_at = coalesce(deleted_at, v_now),
      updated_by = coalesce(nullif(new.updated_by, ''), 'fixed-ticket-automation'),
      updated_at = v_now
  where fixed_ticket_template_id = new.id
    and deleted_at is null;
  get diagnostics v_archived_events = row_count;

  insert into public.audit_logs(
    audit_id, actor_line_user_id, actor_role, action, target_type, target_id, result, detail
  ) values (
    public.new_public_id('AUD'),
    coalesce(nullif(new.updated_by, ''), 'system'),
    case when coalesce(new.updated_by, '') = 'fixed-ticket-automation' then 'system' else 'admin' end,
    'fixed_ticket.delete.revoke_benefits',
    'fixed_ticket_template',
    new.fixed_ticket_id,
    'success',
    jsonb_build_object(
      'cancelledClaims', v_cancelled_claims,
      'archivedEventTickets', v_archived_events,
      'cancelledMessages', v_cancelled_messages
    )
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_booking_service_type(p_type_id uuid, p_name text, p_reward_minutes_per_point integer DEFAULT NULL::integer, p_reward_point_card_id uuid DEFAULT NULL::uuid, p_actor text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_type_id uuid;
  v_old_name text;
  v_name text := btrim(coalesce(p_name, ''));
  v_actor text := coalesce(nullif(btrim(coalesce(p_actor, '')), ''), 'system');
  v_sort_order integer;
  v_card public.point_cards%rowtype;
begin
  if char_length(v_name) not between 1 and 80 then
    raise exception 'INVALID_SERVICE_TYPE_NAME';
  end if;

  if (p_reward_minutes_per_point is null) <> (p_reward_point_card_id is null) then
    raise exception 'INVALID_BOOKING_REWARD_RULE';
  end if;

  if p_reward_minutes_per_point is not null
     and (p_reward_minutes_per_point < 1 or p_reward_minutes_per_point > 10080) then
    raise exception 'INVALID_BOOKING_REWARD_MINUTES';
  end if;

  if p_reward_point_card_id is not null then
    select * into v_card
    from public.point_cards
    where id = p_reward_point_card_id
    for update;

    if not found
       or v_card.status <> 'active'
       or (v_card.expiry_mode <> 'unlimited'
           and (v_card.expires_on is null
                or v_card.expires_on < (clock_timestamp() at time zone 'Asia/Taipei')::date)) then
      raise exception 'BOOKING_REWARD_POINT_CARD_UNAVAILABLE';
    end if;
  end if;

  if p_type_id is null then
    if exists (
      select 1 from public.booking_service_types
      where lower(btrim(name)) = lower(v_name)
    ) then
      raise exception 'DUPLICATE_SERVICE_TYPE';
    end if;

    select coalesce(max(sort_order), -1) + 1
      into v_sort_order
    from public.booking_service_types;

    insert into public.booking_service_types(name, sort_order)
    values (v_name, least(1000, v_sort_order))
    returning id into v_type_id;
  else
    select name into v_old_name
    from public.booking_service_types
    where id = p_type_id
    for update;

    if not found then
      raise exception 'BOOKING_SERVICE_TYPE_NOT_FOUND';
    end if;

    if exists (
      select 1 from public.booking_service_types
      where id <> p_type_id
        and lower(btrim(name)) = lower(v_name)
    ) then
      raise exception 'DUPLICATE_SERVICE_TYPE';
    end if;

    update public.booking_service_types
    set name = v_name,
        updated_at = now()
    where id = p_type_id;

    if lower(btrim(v_old_name)) <> lower(v_name) then
      update public.booking_services
      set service_type = v_name,
          description = '__TYPE__:' || v_name
      where coalesce(counts_toward_membership, true) = true
        and lower(btrim(coalesce(service_type, ''))) = lower(btrim(v_old_name));

      update public.booking_items bi
      set service_type = v_name
      from public.bookings b
      where b.id = bi.booking_id
        and b.status in ('pending', 'confirmed')
        and lower(btrim(coalesce(bi.service_type, ''))) = lower(btrim(v_old_name));

      update public.booking_participant_items bpi
      set service_type = v_name
      from public.booking_participants bp
      join public.bookings b on b.id = bp.booking_id
      where bpi.participant_id = bp.id
        and b.status in ('pending', 'confirmed')
        and lower(btrim(coalesce(bpi.service_type, ''))) = lower(btrim(v_old_name));
    end if;

    v_type_id := p_type_id;
  end if;

  if p_reward_minutes_per_point is null then
    delete from public.booking_service_type_rewards
    where service_type_id = v_type_id;
  else
    insert into public.booking_service_type_rewards(
      service_type_id, point_card_id, minutes_per_point,
      created_by, updated_by, created_at, updated_at
    )
    values (
      v_type_id, p_reward_point_card_id, p_reward_minutes_per_point,
      v_actor, v_actor, now(), now()
    )
    on conflict (service_type_id) do update
    set point_card_id = excluded.point_card_id,
        minutes_per_point = excluded.minutes_per_point,
        updated_by = excluded.updated_by,
        updated_at = now();
  end if;

  return (
    select jsonb_build_object(
      'id', t.id,
      'name', t.name,
      'sortOrder', t.sort_order,
      'rewardMinutesPerPoint', r.minutes_per_point,
      'rewardPointCardId', r.point_card_id,
      'rewardPointCardTitle', c.title,
      'createdAt', t.created_at,
      'updatedAt', t.updated_at
    )
    from public.booking_service_types t
    left join public.booking_service_type_rewards r on r.service_type_id = t.id
    left join public.point_cards c on c.id = r.point_card_id
    where t.id = v_type_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_booking_settings_with_service_types(p_work_start_time time without time zone, p_work_end_time time without time zone, p_min_advance_days integer, p_max_advance_days integer, p_service_types text[], p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_current_updated_at timestamptz;
begin
  select updated_at
    into v_current_updated_at
  from public.booking_settings
  where id = 1
  for update;

  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;

  if p_expected_updated_at is not null
     and v_current_updated_at <> p_expected_updated_at then
    raise exception 'BOOKING_SETTINGS_CONFLICT';
  end if;

  if p_work_end_time <= p_work_start_time
     or extract(epoch from (p_work_end_time - p_work_start_time)) < 1800 then
    raise exception 'INVALID_WORK_HOURS';
  end if;

  if p_min_advance_days < 0 or p_min_advance_days > 365 then
    raise exception 'INVALID_ADVANCE_DAYS';
  end if;

  if p_max_advance_days < 0 or p_max_advance_days > 365 then
    raise exception 'INVALID_MAX_ADVANCE_DAYS';
  end if;

  if p_max_advance_days > 0 and p_max_advance_days < p_min_advance_days then
    raise exception 'INVALID_ADVANCE_WINDOW';
  end if;

  update public.booking_settings
  set work_start_time = p_work_start_time,
      work_end_time = p_work_end_time,
      min_advance_days = p_min_advance_days,
      max_advance_days = p_max_advance_days,
      updated_by = nullif(btrim(coalesce(p_actor, '')), '')
  where id = 1;

  perform p_service_types;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_booking_shared_settings_v3(p_work_start_time time without time zone, p_work_end_time time without time zone, p_slot_interval_minutes integer, p_min_advance_days integer, p_max_advance_days integer, p_booking_notice text, p_store_service_minutes integer, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor text DEFAULT NULL::text)
 RETURNS booking_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_before public.booking_settings%rowtype;
  v_after public.booking_settings%rowtype;
  v_notice text := coalesce(p_booking_notice,'');
  v_store constant uuid := '00000000-0000-4000-8000-000000000010'::uuid;
begin
  if not exists (select 1 from public.admins where line_user_id = p_actor and role = 'admin' and status = 'active') then
    raise exception 'ADMIN_REQUIRED';
  end if;
  select * into v_before from public.booking_settings where id = 1 for update;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  if p_expected_updated_at is not null and v_before.updated_at <> p_expected_updated_at then raise exception 'BOOKING_SETTINGS_CONFLICT'; end if;
  if p_work_start_time is null or p_work_end_time is null or p_work_start_time = p_work_end_time
     or extract(second from p_work_start_time) <> 0 or extract(second from p_work_end_time) <> 0
     or extract(minute from p_work_start_time)::integer % 5 <> 0 or extract(minute from p_work_end_time)::integer % 5 <> 0 then
    raise exception 'INVALID_WORK_HOURS';
  end if;
  if p_slot_interval_minutes is null or p_slot_interval_minutes not between 5 and 120 or p_slot_interval_minutes % 5 <> 0 then
    raise exception 'INVALID_SLOT_INTERVAL';
  end if;
  if p_min_advance_days is null or p_min_advance_days not between 0 and 365 then raise exception 'INVALID_ADVANCE_DAYS'; end if;
  if p_max_advance_days is null or p_max_advance_days not between 0 and 365 then raise exception 'INVALID_MAX_ADVANCE_DAYS'; end if;
  if p_max_advance_days > 0 and p_max_advance_days < p_min_advance_days then raise exception 'INVALID_ADVANCE_WINDOW'; end if;
  if char_length(v_notice) > 2000 then raise exception 'INVALID_BOOKING_NOTICE'; end if;
  if p_store_service_minutes is null or p_store_service_minutes not between 1 and 720 then raise exception 'INVALID_STORE_SERVICE_MINUTES'; end if;
  perform 1 from public.booking_services where id = v_store and deleted_at is null for update;
  if not found then raise exception 'BOOKING_STORE_SERVICE_MISSING'; end if;

  update public.booking_settings set work_start_time = p_work_start_time, work_end_time = p_work_end_time,
    slot_interval_minutes = p_slot_interval_minutes, min_advance_days = p_min_advance_days,
    max_advance_days = p_max_advance_days, booking_notice = v_notice,
    updated_by = nullif(btrim(coalesce(p_actor,'')),'') where id = 1 returning * into v_after;
  update public.booking_services set duration_minutes = p_store_service_minutes, updated_at = clock_timestamp()
    where id = v_store and deleted_at is null;

  insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
    values (nullif(btrim(coalesce(p_actor,'')),''),'admin','BOOKING_SETTINGS_UPDATED','booking_settings','1','success',
      jsonb_build_object('before',jsonb_build_object('workStartTime',v_before.work_start_time,'workEndTime',v_before.work_end_time,
        'slotIntervalMinutes',v_before.slot_interval_minutes,'minAdvanceDays',v_before.min_advance_days,'maxAdvanceDays',v_before.max_advance_days),
        'after',jsonb_build_object('workStartTime',v_after.work_start_time,'workEndTime',v_after.work_end_time,
        'slotIntervalMinutes',v_after.slot_interval_minutes,'minAdvanceDays',v_after.min_advance_days,'maxAdvanceDays',v_after.max_advance_days)));
  return v_after;
end $function$

CREATE OR REPLACE FUNCTION public.save_booking_shared_settings_v5(p_work_start_time time without time zone, p_work_end_time time without time zone, p_slot_interval_minutes integer, p_min_advance_days integer, p_max_advance_days integer, p_booking_notice text, p_store_service_minutes integer, p_reminder_enabled boolean, p_reminder_time time without time zone, p_expected_updated_at timestamp with time zone, p_actor text, p_snapshot_location_required boolean)
 RETURNS booking_settings
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_before public.booking_settings%rowtype; v_after public.booking_settings%rowtype;
begin
  select * into v_before from public.booking_settings where id=1 for update;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  -- v4/v3 validate the active administrator and stale version within this transaction.
  perform public.save_booking_shared_settings_v4(
    p_work_start_time,p_work_end_time,p_slot_interval_minutes,p_min_advance_days,
    p_max_advance_days,p_booking_notice,p_store_service_minutes,p_reminder_enabled,
    p_reminder_time,p_expected_updated_at,p_actor
  );
  update public.booking_settings set snapshot_location_required=
    coalesce(p_snapshot_location_required,v_before.snapshot_location_required)
    where id=1 returning * into v_after;
  if v_before.snapshot_location_required is distinct from v_after.snapshot_location_required then
    insert into public.booking_audit_events
      (actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
    values(p_actor,'admin','SNAPSHOT_LOCATION_POLICY_UPDATED','booking_settings','1','success',
      jsonb_build_object('before',v_before.snapshot_location_required,'after',v_after.snapshot_location_required));
  end if;
  return v_after;
end $function$

CREATE OR REPLACE FUNCTION public.save_booking_shared_settings_v6(p_work_start_time time without time zone, p_work_end_time time without time zone, p_slot_interval_minutes integer, p_min_advance_days integer, p_max_advance_days integer, p_booking_notice text, p_store_service_minutes integer, p_reminder_enabled boolean, p_reminder_time time without time zone, p_expected_updated_at timestamp with time zone, p_actor text, p_snapshot_location_required boolean, p_ticket_booking_required boolean)
 RETURNS booking_settings
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare old_value boolean; result public.booking_settings%rowtype;
begin
 select ticket_booking_required into old_value from public.booking_settings where id=1 for update;
 perform public.save_booking_shared_settings_v5(p_work_start_time,p_work_end_time,p_slot_interval_minutes,
 p_min_advance_days,p_max_advance_days,p_booking_notice,p_store_service_minutes,p_reminder_enabled,
 p_reminder_time,p_expected_updated_at,p_actor,p_snapshot_location_required);
 update public.booking_settings set ticket_booking_required=coalesce(p_ticket_booking_required,old_value)
 where id=1 returning * into result;
 if old_value is distinct from result.ticket_booking_required then
 insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
 values(p_actor,'admin','TICKET_BOOKING_POLICY_UPDATED','booking_settings','1','success',
 jsonb_build_object('before',old_value,'after',result.ticket_booking_required));
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.save_booking_shared_settings_v7(p_work_start_time time without time zone, p_work_end_time time without time zone, p_slot_interval_minutes integer, p_min_advance_days integer, p_max_advance_days integer, p_booking_notice text, p_store_service_minutes integer, p_reminder_enabled boolean, p_reminder_time time without time zone, p_expected_updated_at timestamp with time zone, p_actor text, p_snapshot_location_required boolean, p_ticket_booking_required boolean, p_snapshot_locations jsonb)
 RETURNS booking_settings
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  old_settings public.booking_settings%rowtype;
  result public.booking_settings%rowtype;
  loc jsonb;
  lat numeric;
  lng numeric;
  radius integer;
  label text;
begin
  select * into old_settings from public.booking_settings where id=1 for update;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  if p_snapshot_locations is null or jsonb_typeof(p_snapshot_locations) <> 'array'
     or jsonb_array_length(p_snapshot_locations) > 20 then
    raise exception 'SNAPSHOT_LOCATION_CONFIG_INVALID';
  end if;
  for loc in select value from jsonb_array_elements(p_snapshot_locations) loop
    if jsonb_typeof(loc) <> 'object'
       or jsonb_typeof(loc->'latitude') is distinct from 'number'
       or jsonb_typeof(loc->'longitude') is distinct from 'number'
       or jsonb_typeof(loc->'radiusMeters') is distinct from 'number'
       or jsonb_typeof(loc->'name') is distinct from 'string'
       then raise exception 'SNAPSHOT_LOCATION_CONFIG_INVALID'; end if;
    lat := (loc->>'latitude')::numeric;
    lng := (loc->>'longitude')::numeric;
    radius := (loc->>'radiusMeters')::integer;
    label := btrim(loc->>'name');
    if lat not between -90 and 90 or lng not between -180 and 180
       or radius not between 50 and 2000
       or (loc->>'radiusMeters')::numeric <> radius
       or length(label) not between 1 and 100
       then raise exception 'SNAPSHOT_LOCATION_CONFIG_INVALID'; end if;
  end loop;
  if coalesce(p_snapshot_location_required,old_settings.snapshot_location_required)
     and jsonb_array_length(p_snapshot_locations)=0 then
    raise exception 'SNAPSHOT_LOCATION_NOT_CONFIGURED';
  end if;
  -- This routine performs admin authorization, optimistic lock and all existing settings validation.
  perform public.save_booking_shared_settings_v6(
    p_work_start_time,p_work_end_time,p_slot_interval_minutes,
    p_min_advance_days,p_max_advance_days,p_booking_notice,p_store_service_minutes,
    p_reminder_enabled,p_reminder_time,p_expected_updated_at,p_actor,
    p_snapshot_location_required,p_ticket_booking_required
  );
  update public.booking_settings set snapshot_locations=p_snapshot_locations
  where id=1 returning * into result;
  if old_settings.snapshot_locations is distinct from result.snapshot_locations then
    insert into public.booking_audit_events
      (actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
    values (p_actor,'admin','SNAPSHOT_LOCATIONS_UPDATED','booking_settings','1','success',
      jsonb_build_object('beforeCount',jsonb_array_length(old_settings.snapshot_locations),
                         'afterCount',jsonb_array_length(result.snapshot_locations)));
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.save_calendar_item_with_bonus(p_actor_line_user_id text, p_calendar_item jsonb, p_expected_updated_at text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb := coalesce(p_calendar_item, '{}'::jsonb);
  v_type text := coalesce(v_item->>'itemType','');
  v_enabled boolean := coalesce((v_item->>'bonusPointsEnabled')::boolean,false);
  v_points integer := coalesce((v_item->>'bonusPoints')::integer,0);
  v_result jsonb;
  v_id text;
begin
  if v_type <> 'event' then
    v_enabled := false;
    v_points := 0;
  elsif v_enabled then
    if v_points < 1 or v_points > 100 then
      raise exception 'INVALID_EVENT_BONUS_POINTS';
    end if;
  else
    v_points := 0;
  end if;

  v_result := public.apply_calendar_batch(
    p_actor_line_user_id,
    jsonb_build_array(
      jsonb_build_object(
        'action','save',
        'calendarItem',v_item - 'bonusPointsEnabled' - 'bonusPoints',
        'expectedUpdatedAt',coalesce(p_expected_updated_at,'')
      )
    )
  );

  v_id := coalesce(v_result#>>'{0,calendarItemId}','');
  if v_id = '' then
    raise exception 'CALENDAR_ITEM_NOT_FOUND';
  end if;

  update public.calendar_items
  set bonus_points_enabled=v_enabled,
      bonus_points=v_points,
      updated_by=p_actor_line_user_id,
      updated_at=now()
  where calendar_item_id=v_id;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_member_profile_audited(p_actor text, p_expected_updated_at timestamp with time zone, p_fields jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m public.members%rowtype; fields jsonb;
begin
 select * into m from public.members where line_user_id=p_actor and status='active' and membership_status='active' for update;
 if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;
 if p_fields is null or jsonb_typeof(p_fields)<>'object' or exists(select 1 from jsonb_object_keys(p_fields) k where k not in ('birthday','phone','surname','salutation')) then raise exception 'INVALID_PROFILE_FIELDS'; end if;
 if p_fields ? 'birthday' and (p_fields->>'birthday' is null or (p_fields->>'birthday')::date>(clock_timestamp() at time zone 'Asia/Taipei')::date) then raise exception 'INVALID_PROFILE_FIELDS'; end if;
 if p_fields ? 'phone' and coalesce(p_fields->>'phone','') !~ '^\+[1-9][0-9]{7,14}$' then raise exception 'INVALID_PROFILE_FIELDS'; end if;
 if p_fields ? 'surname' and coalesce(length(btrim(p_fields->>'surname')),0) not between 1 and 40 then raise exception 'INVALID_PROFILE_FIELDS'; end if;
 if p_fields ? 'salutation' and coalesce(p_fields->>'salutation','') not in ('mr','ms') then raise exception 'INVALID_PROFILE_FIELDS'; end if;
 select coalesce(jsonb_agg(k order by k),'[]') into fields from jsonb_each_text(p_fields) x(k,v)
 where v is distinct from (to_jsonb(m)->>k);
 if jsonb_array_length(fields)=0 then return to_jsonb(m); end if;
 if p_expected_updated_at is null or m.updated_at<>p_expected_updated_at then raise exception 'PROFILE_CONFLICT'; end if;
 update public.members set birthday=case when p_fields ? 'birthday' then (p_fields->>'birthday')::date else birthday end,
 phone=case when p_fields ? 'phone' then p_fields->>'phone' else phone end,
 surname=case when p_fields ? 'surname' then btrim(p_fields->>'surname') else surname end,
 salutation=case when p_fields ? 'salutation' then p_fields->>'salutation' else salutation end,updated_at=clock_timestamp()
 where id=m.id returning * into m;
 insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
 values(public.new_public_id('AUD'),p_actor,'member','MEMBER_PROFILE_UPDATED','member',m.id::text,'success',jsonb_build_object('profileFields',fields));
 return to_jsonb(m);
end $function$

CREATE OR REPLACE FUNCTION public.save_point_card(p_actor_line_user_id text, p_card jsonb, p_expected_updated_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_card_id text := nullif(trim(p_card->>'cardId'),'');
  v_id uuid;
  v_now timestamptz := now();
  v_reward jsonb;
  v_template_id uuid;
  v_threshold integer;
  v_reward_row_id uuid;
  v_matched_reward_ids uuid[] := array[]::uuid[];
  v_style_key text := lower(trim(coalesce(nullif(p_card->>'pointCardStyleKey',''), nullif(p_card->>'styleKey',''), '')));
begin
  v_style_key := case v_style_key
    when 'forest' then 'lagoon'
    when 'midnight' then 'skyline'
    when 'ocean' then 'denim'
    when 'sunset' then 'coral'
    when 'lavender' then 'violet'
    when 'rose' then 'berry'
    when 'gold' then 'citrus'
    when 'platinum' then 'cocoa'
    when 'mint' then 'lime'
    when 'cherry' then 'peach'
    else v_style_key
  end;

  if v_style_key not in ('citrus','coral','lagoon','skyline','violet','berry','cocoa','lime','denim','peach') then
    raise exception 'INVALID_POINT_CARD_STYLE';
  end if;

  if v_card_id is null then
    v_card_id := public.new_public_id('PC');
    insert into public.point_cards(
      card_id,title,status,accent,style_key,expiry_mode,expires_on,sort_order,usage_method,usage_instructions,benefit_description,
      created_by,updated_by
    ) values(
      v_card_id,trim(p_card->>'title'),p_card->>'status',p_card->>'accent',v_style_key,p_card->>'expiryMode',
      nullif(p_card->>'expiresOn','')::date,coalesce((select max(sort_order)+1 from public.point_cards),0),
      coalesce(p_card->>'usageMethod',''),coalesce(p_card->>'usageInstructions',''),coalesce(p_card->>'benefitDescription',''),
      p_actor_line_user_id,p_actor_line_user_id
    ) returning id into v_id;
  else
    select id into v_id from public.point_cards where card_id=v_card_id for update;
    if not found then raise exception 'POINT_CARD_NOT_FOUND'; end if;
    if p_expected_updated_at is not null and not exists(select 1 from public.point_cards where id=v_id and updated_at=p_expected_updated_at) then
      raise exception 'CONFLICT';
    end if;
    update public.point_cards set
      title=trim(p_card->>'title'),status=p_card->>'status',accent=p_card->>'accent',style_key=v_style_key,
      expiry_mode=p_card->>'expiryMode',expires_on=nullif(p_card->>'expiresOn','')::date,
      usage_method=coalesce(p_card->>'usageMethod',''),usage_instructions=coalesce(p_card->>'usageInstructions',''),
      benefit_description=coalesce(p_card->>'benefitDescription',''),
      updated_by=p_actor_line_user_id,updated_at=v_now
    where id=v_id;
  end if;

  if jsonb_typeof(p_card->'rewards')='array' then
    for v_reward in select value from jsonb_array_elements(p_card->'rewards')
    loop
      begin
        v_threshold := (v_reward->>'thresholdStamps')::integer;
      exception when others then
        raise exception 'INVALID_REWARD_THRESHOLD';
      end;
      if v_threshold < 1 or v_threshold > 100 then raise exception 'INVALID_REWARD_THRESHOLD'; end if;

      select id into v_template_id
      from public.ticket_templates
      where ticket_template_id=v_reward->>'ticketTemplateId';
      if not found then raise exception 'TICKET_TEMPLATE_NOT_FOUND'; end if;

      v_reward_row_id := null;
      select r.id into v_reward_row_id
      from public.point_card_rewards r
      where r.point_card_id=v_id and r.threshold_stamps=v_threshold and not (r.id = any(v_matched_reward_ids))
      limit 1 for update;

      if v_reward_row_id is null then
        select r.id into v_reward_row_id
        from public.point_card_rewards r
        where r.point_card_id=v_id and r.ticket_template_id=v_template_id and not (r.id = any(v_matched_reward_ids))
        order by r.threshold_stamps limit 1 for update;
      end if;

      if v_reward_row_id is null then
        insert into public.point_card_rewards(
          reward_id,point_card_id,threshold_stamps,ticket_template_id
        )
        values(
          public.new_public_id('RW'),v_id,v_threshold,v_template_id
        )
        returning id into v_reward_row_id;
      else
        update public.point_card_rewards
        set threshold_stamps=v_threshold,
            ticket_template_id=v_template_id,
            updated_at=v_now
        where id=v_reward_row_id;
      end if;
      v_matched_reward_ids := array_append(v_matched_reward_ids,v_reward_row_id);
    end loop;
  end if;

  if cardinality(v_matched_reward_ids)=0 then
    delete from public.point_card_rewards where point_card_id=v_id;
  else
    delete from public.point_card_rewards where point_card_id=v_id and not (id = any(v_matched_reward_ids));
  end if;

  insert into public.audit_logs(audit_id,actor_line_user_id,actor_role,action,target_type,target_id,result,detail)
  values(public.new_public_id('AUD'),p_actor_line_user_id,'admin','admin.pointcards.save','point_card',v_card_id,'success',
    jsonb_build_object(
      'stableRewardIdentity',true,
      'rewardCount',cardinality(v_matched_reward_ids),
      'styleKey',v_style_key,
      'bookingServiceRuleAtRewardNode',true
    ));
  return v_card_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_point_card_service_items(p_actor_line_user_id text, p_card jsonb, p_expected_updated_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_card_id text;
  v_card_uuid uuid;
  v_reward jsonb;
  v_threshold integer;
  v_reward_id uuid;
  v_required_service_ids uuid[] := '{}'::uuid[];
  v_required_service_match_mode text := 'any';
  v_requested_count integer := 0;
begin
  v_card_id := public.save_point_card(p_actor_line_user_id, p_card, p_expected_updated_at);

  select id into v_card_uuid
  from public.point_cards
  where card_id = v_card_id;

  if v_card_uuid is null then
    raise exception 'POINT_CARD_NOT_FOUND';
  end if;

  if jsonb_typeof(p_card->'rewards') = 'array' then
    for v_reward in select value from jsonb_array_elements(p_card->'rewards')
    loop
      begin
        v_threshold := (v_reward->>'thresholdStamps')::integer;
      exception when others then
        raise exception 'INVALID_REWARD_THRESHOLD';
      end;

      v_required_service_ids := '{}'::uuid[];
      v_required_service_match_mode := case
        when lower(btrim(coalesce(v_reward->>'requiredServiceMatchMode', 'any'))) = 'all' then 'all'
        else 'any'
      end;
      v_requested_count := 0;

      if v_reward ? 'requiredServiceIds' and v_reward->'requiredServiceIds' is not null then
        if jsonb_typeof(v_reward->'requiredServiceIds') <> 'array'
           or jsonb_array_length(v_reward->'requiredServiceIds') > 20 then
          raise exception 'INVALID_REQUIRED_SERVICE_IDS';
        end if;

        select count(distinct btrim(value))
          into v_requested_count
        from jsonb_array_elements_text(v_reward->'requiredServiceIds')
        where btrim(value) <> '';

        select coalesce(array_agg(bs.id order by bs.created_at, bs.id), '{}'::uuid[])
          into v_required_service_ids
        from public.booking_services bs
        where bs.deleted_at is null
          and bs.id <> '00000000-0000-4000-8000-000000000010'::uuid
          and exists (
            select 1
            from jsonb_array_elements_text(v_reward->'requiredServiceIds') requested(value)
            where btrim(requested.value) = bs.id::text
          );

        if cardinality(v_required_service_ids) <> v_requested_count then
          raise exception 'INVALID_REQUIRED_SERVICE_IDS';
        end if;
      end if;

      select id into v_reward_id
      from public.point_card_rewards
      where point_card_id = v_card_uuid and threshold_stamps = v_threshold
      limit 1;

      if v_reward_id is null then
        raise exception 'INVALID_REWARD_THRESHOLD';
      end if;

      update public.point_card_rewards
      set required_service_ids = v_required_service_ids,
          required_service_match_mode = v_required_service_match_mode,
          updated_at = now()
      where id = v_reward_id;
    end loop;
  end if;

  return v_card_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_tier_settings(p_actor_line_user_id text, p_settings jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb;
  v_expected timestamptz;
  v_previous integer := -1;
  v_value integer;
  v_key text;
  v_style text;
  v_index integer := 0;
  v_expected_key text;
  v_label text;
begin
  if jsonb_typeof(p_settings) <> 'array' or jsonb_array_length(p_settings) <> 4 then
    raise exception 'INVALID_TIER_SETTINGS';
  end if;

  for v_item in select value from jsonb_array_elements(p_settings)
  loop
    v_index := v_index + 1;
    v_expected_key := (array['general','silver','gold','platinum'])[v_index];
    v_key := v_item->>'tierKey';
    v_style := v_item->>'styleKey';

    if v_key is distinct from v_expected_key then
      raise exception 'INVALID_TIER_SETTINGS';
    end if;

    v_value := (v_item->>'requiredServiceMinutes')::integer;
    if v_index = 1 then
      if v_value <> 0 then raise exception 'INVALID_TIER_SETTINGS'; end if;
    elsif v_value <= v_previous then
      raise exception 'INVALID_TIER_SETTINGS';
    end if;
    if v_value < 0 or v_value > 10000000 then
      raise exception 'INVALID_TIER_SETTINGS';
    end if;
    v_previous := v_value;

    if v_style not in ('forest','midnight','ocean','sunset','lavender','rose','gold','platinum','mint','cherry') then
      raise exception 'INVALID_TIER_SETTINGS';
    end if;

    v_expected := nullif(v_item->>'expectedUpdatedAt','')::timestamptz;
    if v_expected is not null and not exists(
      select 1
      from public.membership_tier_settings
      where tier_key = v_key and updated_at = v_expected
    ) then
      raise exception 'CONFLICT';
    end if;

    v_label := case v_key
      when 'general' then '一般會員'
      when 'silver' then '銀級會員'
      when 'gold' then '金級會員'
      when 'platinum' then '白金會員'
    end;

    insert into public.membership_tier_settings(
      tier_key, tier_label, required_service_minutes, style_key, updated_by, updated_at
    )
    values(
      v_key, v_label, v_value, v_style, p_actor_line_user_id, now()
    )
    on conflict (tier_key) do update set
      tier_label = excluded.tier_label,
      required_service_minutes = excluded.required_service_minutes,
      style_key = excluded.style_key,
      updated_by = excluded.updated_by,
      updated_at = excluded.updated_at;
  end loop;

  insert into public.audit_logs(
    audit_id, actor_line_user_id, actor_role, action, target_type, target_id, result
  )
  values(
    public.new_public_id('AUD'),
    p_actor_line_user_id,
    'admin',
    'admin.member-tiers.save',
    'membership_tiers',
    'all',
    'success'
  );
end;
$function$

