CREATE OR REPLACE FUNCTION public.update_booking_bundle_with_contact(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_items jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT ''::text, p_contact_salutation text DEFAULT ''::text, p_contact_phone text DEFAULT ''::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_member public.members%rowtype;
  v_before public.bookings%rowtype;
  v_booking public.bookings%rowtype;
  v_source text := lower(btrim(coalesce(p_contact_source, '')));
  v_surname text;
  v_salutation text;
  v_phone text;
  v_replay boolean := false;
begin
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;

  select * into v_before from public.bookings where id = p_booking_id and member_id = p_member_id;
  if not found then raise exception 'BOOKING_NOT_EDITABLE'; end if;
  v_replay := v_before.request_id = p_request_id;

  if v_source = 'member' then
    v_surname := btrim(coalesce(v_member.surname, ''));
    v_salutation := lower(btrim(coalesce(v_member.salutation, '')));
    v_phone := regexp_replace(btrim(coalesce(v_member.phone, '')), '[()[:space:]-]', '', 'g');
  elsif v_source = 'custom' then
    v_surname := btrim(coalesce(p_contact_surname, ''));
    v_salutation := lower(btrim(coalesce(p_contact_salutation, '')));
    v_phone := regexp_replace(btrim(coalesce(p_contact_phone, '')), '[()[:space:]-]', '', 'g');
  else
    raise exception 'INVALID_BOOKING_CONTACT_SOURCE';
  end if;

  if char_length(v_surname) < 1 or char_length(v_surname) > 40 then raise exception 'INVALID_BOOKING_CONTACT_SURNAME'; end if;
  if v_salutation not in ('mr','ms') then raise exception 'INVALID_BOOKING_CONTACT_SALUTATION'; end if;
  if v_phone !~ '^\+?[0-9]{8,15}$' then raise exception 'INVALID_BOOKING_CONTACT_PHONE'; end if;

  v_booking := public.update_booking_bundle_request(
    p_booking_id, p_expected_updated_at, p_actor, p_request_id, p_member_id,
    p_booking_date, p_start_time, p_items, p_member_note
  );

  if v_replay then
    if v_booking.contact_source <> v_source
       or coalesce(v_booking.contact_surname, '') <> v_surname
       or coalesce(v_booking.contact_salutation, '') <> v_salutation
       or coalesce(v_booking.contact_phone, '') <> v_phone then
      raise exception 'REQUEST_ID_CONFLICT';
    end if;
    return v_booking;
  end if;

  update public.bookings
  set contact_source = v_source,
      contact_surname = v_surname,
      contact_salutation = v_salutation,
      contact_phone = v_phone
  where id = v_booking.id
  returning * into v_booking;

  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_group_booking_request(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_technician_id uuid, p_participants jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT NULL::text, p_contact_salutation text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_settings public.booking_settings%rowtype;
  v_member public.members%rowtype;
  v_existing public.bookings%rowtype;
  v_booking public.bookings%rowtype;
  v_technician public.booking_technicians%rowtype;
  v_service public.booking_services%rowtype;
  v_store public.booking_services%rowtype;
  v_participant jsonb;
  v_item jsonb;
  v_participant_id uuid;
  v_service_id uuid;
  v_primary_service_id uuid;
  v_seen uuid[];
  v_quantity integer;
  v_party_size integer;
  v_position integer := 0;
  v_total_duration integer := 0;
  v_participant_duration integer := 0;
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_local_time time := (now() at time zone 'Asia/Taipei')::time;
  v_end_time time;
begin
  if p_request_id is null or char_length(btrim(p_request_id)) < 12 or char_length(p_request_id) > 100 then raise exception 'INVALID_REQUEST_ID'; end if;
  select * into v_existing from public.bookings where id=p_booking_id and member_id=p_member_id for update;
  if not found then raise exception 'BOOKING_NOT_EDITABLE'; end if;
  if v_existing.request_id = p_request_id then return v_existing; end if;
  if p_expected_updated_at is null or v_existing.updated_at <> p_expected_updated_at then raise exception 'BOOKING_CONFLICT'; end if;
  if v_existing.status not in ('pending','confirmed') or v_existing.booking_date + v_existing.start_time <= (clock_timestamp() at time zone 'Asia/Taipei') then raise exception 'BOOKING_NOT_EDITABLE'; end if;

  select * into v_member from public.members where id=p_member_id;
  if not found then raise exception 'MEMBER_NOT_FOUND'; end if;
  if coalesce(v_member.membership_status,'') <> 'active' then raise exception 'MEMBERSHIP_REQUIRED'; end if;
  if coalesce(v_member.status,'') <> 'active' then raise exception 'MEMBER_DISABLED'; end if;
  select * into v_settings from public.booking_settings where id=1 for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;
  v_party_size := jsonb_array_length(p_participants);
  if v_party_size < 1 or v_party_size > v_settings.max_party_size then raise exception 'INVALID_PARTY_SIZE'; end if;
  select * into v_technician from public.booking_technicians where id=p_technician_id for share;
  if not found then raise exception 'BOOKING_TECHNICIAN_NOT_FOUND'; end if;
  if not v_technician.is_active then raise exception 'BOOKING_TECHNICIAN_DISABLED'; end if;

  for v_participant in select value from jsonb_array_elements(p_participants) loop
    v_participant_duration := 0;
    if jsonb_typeof(v_participant->'items') <> 'array' or jsonb_array_length(v_participant->'items') < 1 or jsonb_array_length(v_participant->'items') > 20 then raise exception 'INVALID_BOOKING_ITEMS'; end if;
    v_seen := array[]::uuid[];
    for v_item in select value from jsonb_array_elements(v_participant->'items') loop
      begin v_service_id := (v_item->>'serviceId')::uuid; v_quantity := coalesce((v_item->>'quantity')::integer,1); exception when others then raise exception 'INVALID_BOOKING_ITEMS'; end;
      if v_service_id = '00000000-0000-4000-8000-000000000010' then raise exception 'INVALID_BOOKING_ITEMS'; end if;
      if v_quantity < 1 or v_quantity > 2 then raise exception 'INVALID_BOOKING_QUANTITY'; end if;
      if v_service_id = any(v_seen) then raise exception 'DUPLICATE_BOOKING_SERVICE'; end if;
      v_seen := array_append(v_seen,v_service_id);
      select * into v_service from public.booking_services where id=v_service_id for share;
      if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
      if not v_service.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;
      if v_primary_service_id is null then v_primary_service_id := v_service_id; end if;
      v_participant_duration := v_participant_duration + (v_service.duration_minutes * v_quantity);
    end loop;
    v_total_duration := greatest(v_total_duration, v_participant_duration);
  end loop;

  select * into v_store from public.booking_services where id='00000000-0000-4000-8000-000000000010' for share;
  if not found then raise exception 'BOOKING_SERVICE_NOT_FOUND'; end if;
  if not v_store.is_active then raise exception 'BOOKING_SERVICE_DISABLED'; end if;
  v_total_duration := v_total_duration + v_store.duration_minutes;
  if v_total_duration < 1 or v_total_duration > 1440 then raise exception 'INVALID_BOOKING_DURATION'; end if;
  if p_booking_date < public.booking_business_date(clock_timestamp() at time zone 'Asia/Taipei',v_settings.work_start_time,v_settings.work_end_time) + coalesce(v_settings.min_advance_days,0) then raise exception 'BOOKING_TOO_EARLY'; end if;
  if public.booking_slot_start_at(p_booking_date,p_start_time,v_settings.work_start_time,v_settings.work_end_time) <= (clock_timestamp() at time zone 'Asia/Taipei') then raise exception 'BOOKING_TIME_PASSED'; end if;
  if extract(second from p_start_time) <> 0 then raise exception 'INVALID_BOOKING_SLOT'; end if;
  v_end_time := p_start_time + make_interval(mins=>v_total_duration);
  if not public.booking_slot_fits(p_booking_date,p_start_time,v_total_duration,v_settings.work_start_time,v_settings.work_end_time,v_settings.slot_interval_minutes) then raise exception 'INVALID_BOOKING_SLOT'; end if;
  if p_contact_source not in ('member','custom') then raise exception 'INVALID_BOOKING_CONTACT'; end if;
  if p_contact_source='custom' and (nullif(btrim(coalesce(p_contact_surname,'')),'') is null or p_contact_salutation not in ('mr','ms') or nullif(btrim(coalesce(p_contact_phone,'')),'') is null) then raise exception 'INVALID_BOOKING_CONTACT'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_booking_date::text || ':' || p_technician_id::text,0));
  begin
    update public.bookings set
      request_id=p_request_id, service_id=v_primary_service_id, booking_date=p_booking_date, start_time=p_start_time,
      end_time=v_end_time, total_duration_minutes=v_total_duration, status='pending', member_note=left(coalesce(p_member_note,''),500),
      admin_note='', confirmed_by=null, confirmed_at=null, technician_id=p_technician_id, party_size=v_party_size,
      contact_source=p_contact_source,
      contact_surname=case when p_contact_source='custom' then left(btrim(p_contact_surname),40) else null end,
      contact_salutation=case when p_contact_source='custom' then p_contact_salutation else null end,
      contact_phone=case when p_contact_source='custom' then left(btrim(p_contact_phone),20) else null end
    where id=p_booking_id returning * into v_booking;
  exception when exclusion_violation or unique_violation then raise exception 'BOOKING_SLOT_TAKEN'; end;

  delete from public.booking_items where booking_id=p_booking_id;
  delete from public.booking_participants where booking_id=p_booking_id;
  v_position := 0;
  for v_participant in select value from jsonb_array_elements(p_participants) loop
    v_position := v_position + 1;
    insert into public.booking_participants(booking_id,position) values (p_booking_id,v_position) returning id into v_participant_id;
    for v_item in select value from jsonb_array_elements(v_participant->'items') loop
      v_service_id := (v_item->>'serviceId')::uuid; v_quantity := coalesce((v_item->>'quantity')::integer,1);
      select * into v_service from public.booking_services where id=v_service_id;
      insert into public.booking_participant_items(participant_id,service_id,service_title,unit_duration_minutes,unit_price_amount,quantity)
      values(v_participant_id,v_service.id,v_service.title,v_service.duration_minutes,v_service.price_amount,v_quantity);
      insert into public.booking_items(booking_id,service_id,service_title,unit_duration_minutes,unit_price_amount,quantity,service_type,counts_toward_membership)
      values(p_booking_id,v_service.id,v_service.title,v_service.duration_minutes,v_service.price_amount,v_quantity,v_service.service_type,v_service.counts_toward_membership)
      on conflict (booking_id,service_id) do update set quantity=public.booking_items.quantity+excluded.quantity;
    end loop;
  end loop;
  insert into public.booking_items(booking_id,service_id,service_title,unit_duration_minutes,unit_price_amount,quantity,service_type,counts_toward_membership)
  values(p_booking_id,v_store.id,v_store.title,v_store.duration_minutes,v_store.price_amount,1,v_store.service_type,v_store.counts_toward_membership)
  on conflict (booking_id,service_id) do update set quantity=excluded.quantity;

  insert into public.booking_audit_events(actor_line_user_id,actor_role,action,target_type,target_id,result,metadata)
  values(p_actor,'member','BOOKING_UPDATED','booking',p_booking_id::text,'success',jsonb_build_object('previousDate',v_existing.booking_date,'previousStartTime',v_existing.start_time,'previousStatus',v_existing.status,'partySize',v_party_size,'technicianId',p_technician_id));
  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_group_booking_request_v2(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_participants jsonb, p_member_note text DEFAULT ''::text, p_contact_source text DEFAULT 'member'::text, p_contact_surname text DEFAULT NULL::text, p_contact_salutation text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_primary_technician_id uuid;
  v_booking public.bookings%rowtype;
  v_participant jsonb;
  v_position integer;
  v_participant_id uuid;
  v_technician_id uuid;
  v_duration integer;
begin
  v_primary_technician_id := public.validate_group_booking_technicians(p_participants);

  v_booking := public.update_group_booking_request(
    p_booking_id,
    p_expected_updated_at,
    p_actor,
    p_request_id,
    p_member_id,
    p_booking_date,
    p_start_time,
    v_primary_technician_id,
    p_participants,
    p_member_note,
    p_contact_source,
    p_contact_surname,
    p_contact_salutation,
    p_contact_phone
  );

  for v_participant, v_position in
    select value, ordinality::integer
    from jsonb_array_elements(p_participants) with ordinality
  loop
    select id into v_participant_id
    from public.booking_participants
    where booking_id = v_booking.id and position = v_position;
    if not found then raise exception 'INVALID_BOOKING_PARTICIPANTS'; end if;

    v_technician_id := null;
    if nullif(btrim(coalesce(v_participant->>'technicianId','')), '') is not null then
      v_technician_id := (v_participant->>'technicianId')::uuid;
    end if;

    update public.booking_participants
    set technician_id = v_technician_id
    where id = v_participant_id;

    delete from public.booking_participant_reservations where participant_id = v_participant_id;
    if v_technician_id is not null then
      select coalesce(sum(unit_duration_minutes * quantity), 0)::integer
      into v_duration
      from public.booking_participant_items
      where participant_id = v_participant_id;

      if v_duration < 1 then raise exception 'INVALID_BOOKING_DURATION'; end if;

      insert into public.booking_participant_reservations(
        participant_id, booking_id, technician_id, booking_date, start_time, end_time, is_active
      ) values (
        v_participant_id,
        v_booking.id,
        v_technician_id,
        v_booking.booking_date,
        v_booking.start_time,
        v_booking.start_time + make_interval(mins => v_duration),
        v_booking.status in ('pending','confirmed')
      );
    end if;
  end loop;

  return v_booking;
exception
  when exclusion_violation then
    raise exception 'BOOKING_SLOT_TAKEN';
end;
$function$

CREATE OR REPLACE FUNCTION public.update_group_booking_with_benefits_request_v2(p_booking_id uuid, p_expected_updated_at timestamp with time zone, p_actor text, p_request_id text, p_member_id uuid, p_booking_date date, p_start_time time without time zone, p_participants jsonb, p_member_note text, p_contact_source text, p_contact_surname text, p_contact_salutation text, p_contact_phone text, p_benefits jsonb DEFAULT '[]'::jsonb)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings%rowtype;
begin
  select * into v_booking
  from public.update_group_booking_request_v2(
    p_booking_id,p_expected_updated_at,p_actor,p_request_id,p_member_id,p_booking_date,p_start_time,
    p_participants,p_member_note,p_contact_source,p_contact_surname,p_contact_salutation,p_contact_phone
  );
  perform public.replace_booking_benefit_selections_request(v_booking.id,p_member_id,p_benefits);
  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_booking_benefit_service_requirement_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_required uuid[] := '{}'::uuid[];
  v_match_mode text := 'any';
  v_titles text[] := '{}'::text[];
begin
  if new.status = 'cancelled' or new.benefit_kind = 'calendar' then
    return new;
  end if;

  if new.benefit_kind = 'points' then
    select coalesce(r.required_service_ids, '{}'::uuid[]),
           coalesce(r.required_service_match_mode, 'any')
      into v_required, v_match_mode
    from public.point_tickets pt
    join public.point_card_rewards r on r.id = pt.reward_id
    where pt.ticket_id = new.benefit_ref;
  elsif new.benefit_kind = 'event' then
    select coalesce(et.required_service_ids, '{}'::uuid[]),
           coalesce(et.required_service_match_mode, 'any')
      into v_required, v_match_mode
    from public.event_ticket_claims ec
    join public.event_tickets et on et.id = ec.event_ticket_id
    where ec.claim_id = new.benefit_ref;
  end if;

  v_required := coalesce(v_required, '{}'::uuid[]);
  v_match_mode := case when v_match_mode = 'all' then 'all' else 'any' end;

  if cardinality(v_required) > 0
     and not public.booking_meets_required_services(new.booking_id, v_required, v_match_mode) then
    v_titles := public.required_booking_service_titles(v_required);
    raise exception 'BOOKING_BENEFIT_SERVICE_REQUIRED'
      using detail = format(
        case when v_match_mode = 'all'
          then '票券「%s」需預約所有指定項目：%s'
          else '票券「%s」需預約以下任一項目：%s'
        end,
        coalesce(nullif(new.title_snapshot, ''), new.benefit_ref),
        array_to_string(v_titles, '、')
      );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_booking_point_ticket_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_point_card_id uuid;
  v_threshold integer := 0;
  v_balance integer := 0;
  v_existing_required integer := 0;
  v_exclude_selection_id uuid := null;
begin
  if new.benefit_kind <> 'points' or new.status <> 'pending' then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    v_exclude_selection_id := old.id;
  end if;

  select pt.point_card_id, pt.threshold_stamps
    into v_point_card_id, v_threshold
  from public.point_tickets pt
  where pt.member_id = new.member_id
    and pt.ticket_id = new.benefit_ref
    and pt.status = 'available';

  -- Availability/ownership is enforced by replace_booking_benefit_selections_request.
  -- This trigger owns the aggregate point reservation invariant.
  if not found then
    return new;
  end if;

  select pb.stamps
    into v_balance
  from public.point_balances pb
  where pb.member_id = new.member_id
    and pb.point_card_id = v_point_card_id
  for update;

  v_balance := coalesce(v_balance, 0);

  select coalesce(sum(pt.threshold_stamps), 0)::integer
    into v_existing_required
  from public.booking_benefit_selections b
  join public.point_tickets pt
    on pt.member_id = b.member_id
   and pt.ticket_id = b.benefit_ref
  where b.member_id = new.member_id
    and b.benefit_kind = 'points'
    and b.status = 'pending'
    and pt.point_card_id = v_point_card_id
    and (v_exclude_selection_id is null or b.id <> v_exclude_selection_id);

  if v_existing_required + coalesce(v_threshold, 0) > v_balance then
    raise exception 'POINT_TICKET_INSUFFICIENT_POINTS';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_booking_service_requirements_on_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_selection record;
  v_required uuid[];
  v_match_mode text;
  v_titles text[];
begin
  if new.status <> 'completed' or old.status = 'completed' then
    return new;
  end if;

  for v_selection in
    select benefit_kind, benefit_ref, title_snapshot
    from public.booking_benefit_selections
    where booking_id = new.id
      and status in ('pending', 'redeemed', 'applied')
      and benefit_kind in ('points', 'event')
  loop
    v_required := '{}'::uuid[];
    v_match_mode := 'any';

    if v_selection.benefit_kind = 'points' then
      select coalesce(r.required_service_ids, '{}'::uuid[]),
             coalesce(r.required_service_match_mode, 'any')
        into v_required, v_match_mode
      from public.point_tickets pt
      join public.point_card_rewards r on r.id = pt.reward_id
      where pt.ticket_id = v_selection.benefit_ref;
    else
      select coalesce(et.required_service_ids, '{}'::uuid[]),
             coalesce(et.required_service_match_mode, 'any')
        into v_required, v_match_mode
      from public.event_ticket_claims ec
      join public.event_tickets et on et.id = ec.event_ticket_id
      where ec.claim_id = v_selection.benefit_ref;
    end if;

    v_required := coalesce(v_required, '{}'::uuid[]);
    v_match_mode := case when v_match_mode = 'all' then 'all' else 'any' end;

    if cardinality(v_required) > 0
       and not public.booking_meets_required_services(new.id, v_required, v_match_mode) then
      v_titles := public.required_booking_service_titles(v_required);
      raise exception 'BOOKING_BENEFIT_SERVICE_REQUIRED'
        using detail = format(
          case when v_match_mode = 'all'
            then '票券「%s」需預約所有指定項目：%s'
            else '票券「%s」需預約以下任一項目：%s'
          end,
          coalesce(nullif(v_selection.title_snapshot, ''), v_selection.benefit_ref),
          array_to_string(v_titles, '、')
        );
    end if;
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_booking_service_shared_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_canonical_name text;
begin
  if coalesce(new.counts_toward_membership, true) = false then
    return new;
  end if;

  if new.service_type is null or btrim(new.service_type) = '' then
    raise exception 'BOOKING_SERVICE_TYPE_REQUIRED';
  end if;

  select name
    into v_canonical_name
  from public.booking_service_types
  where lower(btrim(name)) = lower(btrim(new.service_type))
  limit 1;

  if not found then
    raise exception 'BOOKING_SERVICE_TYPE_INVALID';
  end if;

  new.service_type := v_canonical_name;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_group_booking_technicians(p_participants jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_settings public.booking_settings%rowtype;
  v_participant jsonb;
  v_technician_id uuid;
  v_technician public.booking_technicians%rowtype;
  v_selected uuid[] := array[]::uuid[];
  v_primary_selected boolean := false;
begin
  select * into v_settings from public.booking_settings where id = 1 for share;
  if not found then raise exception 'BOOKING_SETTINGS_MISSING'; end if;
  if v_settings.require_primary_technician then
    if v_settings.primary_technician_id is null then raise exception 'BOOKING_PRIMARY_TECHNICIAN_MISSING'; end if;

  select * into v_technician
  from public.booking_technicians
  where id = v_settings.primary_technician_id
  for share;
  if not found or not v_technician.is_active then raise exception 'BOOKING_PRIMARY_TECHNICIAN_DISABLED'; end if;
  end if;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then
    raise exception 'INVALID_BOOKING_PARTICIPANTS';
  end if;

  for v_participant in select value from jsonb_array_elements(p_participants) loop
    if nullif(btrim(coalesce(v_participant->>'technicianId','')), '') is null then
      continue;
    end if;

    begin
      v_technician_id := (v_participant->>'technicianId')::uuid;
    exception when others then
      raise exception 'INVALID_BOOKING_TECHNICIAN';
    end;

    if v_technician_id = any(v_selected) then
      raise exception 'DUPLICATE_PARTICIPANT_TECHNICIAN';
    end if;
    v_selected := array_append(v_selected, v_technician_id);

    select * into v_technician
    from public.booking_technicians
    where id = v_technician_id
    for share;
    if not found then raise exception 'BOOKING_TECHNICIAN_NOT_FOUND'; end if;
    if not v_technician.is_active then raise exception 'BOOKING_TECHNICIAN_DISABLED'; end if;

    if v_technician_id = v_settings.primary_technician_id then
      v_primary_selected := true;
    end if;
  end loop;

  if v_settings.require_primary_technician and not v_primary_selected then
    raise exception 'BOOKING_PRIMARY_TECHNICIAN_REQUIRED';
  end if;

  return case when v_primary_selected then v_settings.primary_technician_id else v_selected[1] end;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_snapshot_ticket_selection(p_member uuid, p_booking uuid, p_benefits jsonb, p_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item jsonb; kind text; ref text; title text; selections jsonb:='[]'; b public.bookings%rowtype;
 cost integer; card uuid; budget record; location_required boolean;
 v_reserved_points integer; v_balance integer; v_max_points integer; v_max_events integer; v_used_today integer;
begin
 if p_booking is not null then
 select * into b from public.bookings where id=p_booking for update;
 if not found or b.member_id<>p_member then raise exception 'BOOKING_NOT_OWNED'; end if;
 if b.status<>'confirmed' or b.completed_at is not null then raise exception 'BOOKING_TICKET_CONFIRMATION_REQUIRED'; end if;
 if b.cancellation_requested_at is not null and b.cancellation_reviewed_at is null then raise exception 'BOOKING_CANCELLATION_PENDING'; end if;
 end if;
 perform 1 from public.members where id=p_member and status='active' and membership_status='active' for update;
 if not found then raise exception 'MEMBERSHIP_REQUIRED'; end if;
 if jsonb_typeof(p_benefits) is distinct from 'array' or jsonb_array_length(p_benefits)>20 then raise exception 'INVALID_BOOKING_BENEFITS'; end if;
 for item in select value from jsonb_array_elements(p_benefits) loop
 kind:=item->>'kind'; ref:=item->>'id';
 if kind not in ('points','event') or kind is null or coalesce(ref,'')='' or length(ref)>160
 or exists(select 1 from jsonb_array_elements(selections) s where s->>'kind'=kind and s->>'id'=ref) then raise exception 'INVALID_BOOKING_BENEFITS'; end if;
 -- A future general booking reserves its own ticket and its share of points.
 -- A current snapshot may use that ticket only if the remaining unreserved
 -- balance can independently fund today's redemption. The future booking's
 -- ticket reference is replaced atomically before today's approval settles.
 if exists(
   select 1 from public.booking_benefit_selections s
   left join public.bookings future on future.id=s.booking_id
   where s.member_id=p_member and s.benefit_kind=kind and s.benefit_ref=ref
     and s.status='pending' and s.booking_id is distinct from p_booking
     and (
       kind<>'points' or p_booking is not null
       or future.id is null or future.status not in ('pending','confirmed')
       or future.completed_at is not null
       or future.start_at<=(clock_timestamp() at time zone 'Asia/Taipei')
     )
 ) then raise exception 'BOOKING_BENEFIT_RESERVED'; end if;
 if kind='points' then
 select t.ticket_title,t.threshold_stamps,t.point_card_id,t.requires_location into title,cost,card,location_required from public.point_tickets t
 join public.point_cards pc on pc.id=t.point_card_id where t.ticket_id=ref and t.member_id=p_member
 and t.status='available' and pc.status='active' and (pc.expiry_mode='unlimited' or pc.expires_on>=(clock_timestamp() at time zone 'Asia/Taipei')::date)
 for update of t;
 else
 select c.ticket_title,e.requires_location into title,location_required from public.event_ticket_claims c join public.event_tickets e on e.id=c.event_ticket_id
 where c.claim_id=ref and c.member_id=p_member and c.status='claimed' and e.status='active' and e.deleted_at is null
 and (e.starts_on is null or e.starts_on<=(clock_timestamp() at time zone 'Asia/Taipei')::date)
 and (e.ends_on is null or e.ends_on>=(clock_timestamp() at time zone 'Asia/Taipei')::date)
 and (cardinality(e.allowed_tier_keys)=0 or public.current_tier_key(p_member)=any(e.allowed_tier_keys))
 for update of c;
 end if;
 if not found then raise exception 'BOOKING_BENEFIT_NOT_AVAILABLE'; end if;
 -- Location rules must never be mistaken for the advance-booking policy.
 -- Snapshot review has no proof of GPS-based redemption at the configured site.
 if coalesce(location_required,false) and not public.snapshot_ticket_location_proven(p_receipt_id,p_member,kind,ref) then raise exception 'BOOKING_BENEFIT_LOCATION_REQUIRED'; end if;
 if p_booking is not null and not public.booking_ticket_matches_services(p_booking,p_member,kind,ref) then raise exception 'BOOKING_BENEFIT_SERVICE_REQUIRED'; end if;
 selections:=selections||jsonb_build_array(jsonb_build_object('kind',kind,'id',ref,'title',title));
 end loop;
 for budget in select t.point_card_id,sum(t.threshold_stamps)::integer amount
 from jsonb_array_elements(selections) s join public.point_tickets t on t.ticket_id=s->>'id' and t.member_id=p_member where s->>'kind'='points' group by t.point_card_id loop
 -- Match the member point-card screen: subtract all OTHER pending bookings
 -- from the same card before accepting the snapshot batch.
 select coalesce(stamps,0) into v_balance from public.point_balances
   where member_id=p_member and point_card_id=budget.point_card_id for update;
 select coalesce(sum(t.threshold_stamps),0)::integer into v_reserved_points
   from public.booking_benefit_selections s join public.point_tickets t
   on t.member_id=s.member_id and t.ticket_id=s.benefit_ref
   where s.member_id=p_member and s.benefit_kind='points' and s.status='pending'
     and t.point_card_id=budget.point_card_id
     and (p_booking is null or s.booking_id is distinct from p_booking);
 if budget.amount>greatest(0,coalesce(v_balance,0)-v_reserved_points) then
   raise exception 'POINT_TICKET_INSUFFICIENT_POINTS';
 end if;
 end loop;
 select coalesce((select max_tickets_per_redemption from public.point_card_settings where id=1),1) into v_max_points;
 if v_max_points>0 and
 (select count(*) from jsonb_array_elements(selections) s where s->>'kind'='points')>v_max_points
 then raise exception 'TICKET_BATCH_LIMIT_EXCEEDED'; end if;
 select coalesce((select max_tickets_per_day from public.event_ticket_settings where id=1),1) into v_max_events;
 if v_max_events>0 then
   select count(*)::integer into v_used_today from public.event_ticket_claims c
   where c.member_id=p_member and c.status='used'
     and c.used_at>=(((clock_timestamp() at time zone 'Asia/Taipei')::date)::timestamp at time zone 'Asia/Taipei')
     and c.used_at<(((((clock_timestamp() at time zone 'Asia/Taipei')::date)+1)::timestamp) at time zone 'Asia/Taipei');
   if v_used_today+
      (select count(*) from jsonb_array_elements(selections) s where s->>'kind'='event')>v_max_events
   then raise exception 'EVENT_TICKET_DAILY_LIMIT_REACHED'; end if;
 end if;
 return selections;
end $function$

CREATE OR REPLACE FUNCTION public.validate_ticket_required_service_ids()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if exists (
    select 1
    from unnest(coalesce(new.required_service_ids, '{}'::uuid[])) as required(service_id)
    left join public.booking_services bs on bs.id = required.service_id
    where bs.id is null
  ) then
    raise exception 'INVALID_REQUIRED_SERVICE_IDS';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.verify_ticket_redemption_location(p_latitude numeric, p_longitude numeric, p_radius_meters integer, p_location jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lat numeric;
  v_lng numeric;
  v_accuracy numeric;
  v_observed_at timestamptz;
  v_distance double precision;
begin
  if p_location is null or jsonb_typeof(p_location) <> 'object'
    or jsonb_typeof(p_location->'latitude') <> 'number'
    or jsonb_typeof(p_location->'longitude') <> 'number'
    or jsonb_typeof(p_location->'accuracy') <> 'number'
    or jsonb_typeof(p_location->'observedAt') <> 'string'
  then raise exception 'LOCATION_REQUIRED'; end if;
  begin
    v_lat := (p_location->>'latitude')::numeric;
    v_lng := (p_location->>'longitude')::numeric;
    v_accuracy := (p_location->>'accuracy')::numeric;
    v_observed_at := (p_location->>'observedAt')::timestamptz;
  exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
    raise exception 'LOCATION_INVALID';
  end;
  if v_lat not between -90 and 90 or v_lng not between -180 and 180
    or v_accuracy <= 0 or v_accuracy > 100
    or v_observed_at < clock_timestamp() - interval '2 minutes'
    or v_observed_at > clock_timestamp() + interval '30 seconds'
  then raise exception 'LOCATION_INVALID'; end if;
  v_distance := 6371000 * 2 * asin(sqrt(least(1.0,
    power(sin(radians((v_lat - p_latitude)::double precision) / 2), 2)
    + cos(radians(p_latitude::double precision)) * cos(radians(v_lat::double precision))
      * power(sin(radians((v_lng - p_longitude)::double precision) / 2), 2)
  )));
  if v_distance + v_accuracy > p_radius_meters then raise exception 'LOCATION_OUT_OF_RANGE'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.verify_ticket_redemption_locations(p_locations jsonb, p_location jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_location jsonb;
begin
  if not public.event_ticket_locations_valid(p_locations) then raise exception 'LOCATION_RULE_INVALID'; end if;
  for v_location in select value from jsonb_array_elements(p_locations) loop
    begin
      perform public.verify_ticket_redemption_location(
        (v_location->>'latitude')::numeric, (v_location->>'longitude')::numeric,
        (v_location->>'radiusMeters')::integer, p_location);
      return;
    exception when raise_exception then
      if sqlerrm <> 'LOCATION_OUT_OF_RANGE' then raise; end if;
    end;
  end loop;
  raise exception 'LOCATION_OUT_OF_RANGE';
end;
$function$
